Grid capture(ftxui::Element element,int width,int height){
    auto screen=ftxui::Screen::Create(ftxui::Dimension::Fixed(width),ftxui::Dimension::Fixed(height));ftxui::Render(screen,element);
    Grid result{width,height,{}};for(int y=0;y<height;++y)for(int x=0;x<width;++x)result.cells.push_back(screen.PixelAt(x,y).character);return result;
}
Grid mock(std::initializer_list<std::string_view> lines){
    int width=0;for(auto line:lines)width=std::max(width,ftxui::string_width(std::string(line)));
    Grid result{width,static_cast<int>(lines.size()),{}};
    for(auto line:lines){const auto end=result.cells.size()+static_cast<std::size_t>(width);for(const auto& c:ftxui::Utf8ToGlyphs(std::string(line)))result.cells.push_back(c);while(result.cells.size()<end)result.cells.emplace_back(" ");}return result;
}
std::string fenced(std::string_view source,std::string_view language){return "```"+std::string(language)+'\n'+std::string(source)+"\n```\n\nAFTER_RELATIONS_SEMANTICS";}

