constexpr std::string_view kStateSnapshotPortsSha="93c367429bbbefe778962428b0cc80d0124ca81cb7249561de43c77c7105ffc0";
struct AssertionObservation {int index=0;std::string mapping,status;std::vector<std::string> errors;};
// The source catalog supplements importer metadata; it never replaces the
// immutable original records or learns a predicate from Loom's rendered output.
std::vector<std::string> source_predicate(std::string_view text,JsonVal predicate){
    std::vector<std::string> errors;const auto kind=predicate.get_string("kind");const auto value=predicate.get_string("value");
    if(kind=="contains"){if(text.find(value)==std::string_view::npos)errors.push_back("Missing source literal: "+value);}
    else if(kind=="not_contains"){if(text.find(value)!=std::string_view::npos)errors.push_back("Unexpected source literal: "+value);}
    else if(kind=="line_before"){
        auto first_line=[&](std::string_view label){int line=0;for(std::size_t at=0;at<text.size();++line){const auto end=text.find('\n',at);const auto row=text.substr(at,end==std::string_view::npos?text.size()-at:end-at);if(row.find(label)!=std::string_view::npos)return line;if(end==std::string_view::npos)break;at=end+1;}return -1;};
        const int first=first_line(predicate.get_string("first")),last=first_line(predicate.get_string("last"));
        if(first<0||last<0||first>=last)errors.push_back("Source label line ordering failed");
    }else if(kind=="count"){
        if(value.empty())return {"Empty source glyph count"};
        std::size_t count=0;for(auto at=text.find(value);at!=std::string_view::npos;at=text.find(value,at+value.size()))++count;
        if(count!=static_cast<std::size_t>(predicate.get_int("expected")))errors.push_back("Source exact glyph count failed");
    }else if(kind=="any_contains"){
        bool found=false;predicate.get("values").iter([&](JsonVal candidate){if(text.find(candidate.as_str())!=std::string_view::npos)found=true;});
        if(!found)errors.push_back("No source alternative glyph present");
    }else errors.push_back("Unknown source predicate: "+kind);
    return errors;
}
std::string assertion_surface(const Grid& grid){std::string text;for(int y=0;y<grid.height;++y){const auto row=grid.row(y);if(row.find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)break;text+=row+'\n';}return text;}
void verify_source_catalog(){
    if(digest(kClassArrowSourceConditions)!=kClassArrowSourceConditionsSha||digest(kAssertionSourceCorrections)!=kAssertionSourceCorrectionsSha)throw std::runtime_error("Changed source assertion catalog");
    const auto catalog=json::parse(kClassArrowSourceConditions),overlay=json::parse(kAssertionSourceCorrections),ports=json::parse(kRelationAssertionPorts);
    if(!catalog||!overlay||!ports)throw std::runtime_error("Malformed source assertion catalog");
    const auto root=catalog->root();const auto source=read(std::filesystem::path(LOOM_TESTS_DIR).parent_path()/root.get_string("source_path"));
    if(digest(source)!=root.get_string("source_sha256"))throw std::runtime_error("Changed original class-arrow test source");
    std::set<std::string> functions;std::size_t count=0,ascii=0;
    root.get("functions").iter([&](JsonVal function){const auto at=static_cast<std::size_t>(function.get_int("function_byte_offset")),size=static_cast<std::size_t>(function.get_int("function_byte_length"));if(at>source.size()||size>source.size()-at||digest(std::string_view(source).substr(at,size))!=function.get_string("function_sha256"))throw std::runtime_error("Changed source assertion function");functions.insert(function.get_string("function_sha256"));function.get("conditions").iter([&](JsonVal condition){++count;if(condition.get("foreign_ascii_profile").as_bool())++ascii;if(source.find(condition.get_string("original"),at)>=at+size)throw std::runtime_error("Missing source assertion witness");});});
    if(functions.size()!=23||count!=59||ascii!=8)throw std::runtime_error("Dropped original source assertion");
    std::size_t corrected=0;overlay->root().get("corrections").iter([&](JsonVal correction){++corrected;bool matched=false;ports->root().get("ports").iter([&](JsonVal port){if(port.get_string("case_id")==correction.get_string("case_id")&&port.get_int("index")==correction.get_int("index")){matched=digest(port.to_string())==correction.get_string("original_record_sha256");}});if(!matched||!functions.contains(correction.get_string("function_sha256"))||correction.get_string("source_file_sha256")!=root.get_string("source_sha256")||correction.get_string("source_condition_catalog_sha256")!=kClassArrowSourceConditionsSha)throw std::runtime_error("Unwitnessed ASCII profile correction");});
    if(corrected!=2)throw std::runtime_error("Dropped ASCII profile correction");
}
std::vector<AssertionObservation> source_conditions(const Grid& grid,std::string_view id){
    static const auto catalog=json::parse(kClassArrowSourceConditions);if(!catalog)throw std::runtime_error("Malformed source assertion catalog");
    const auto text=assertion_surface(grid);std::vector<AssertionObservation> result;
    catalog->root().get("functions").iter([&](JsonVal function){if(function.get_string("case_id")!=id)return;function.get("conditions").iter([&](JsonVal condition){AssertionObservation observation;observation.index=static_cast<int>(condition.get_int("line"));observation.mapping="complete-source-function-condition";observation.status="passed";if(condition.get("foreign_ascii_profile").as_bool())observation.status="conditional_foreign_ascii_option";else observation.errors=source_predicate(text,condition.get("native_predicate"));if(!observation.errors.empty())observation.status="failed";result.push_back(std::move(observation));});});return result;
}
std::vector<AssertionObservation> original_assertions(const Grid& grid,std::string_view id,bool source_fallback){
    static const auto ports=json::parse(kRelationAssertionPorts);
    if(!ports)throw std::runtime_error("Malformed frozen original assertion ports");
    std::string text;int width=0,height=0;
    for(int y=0;y<grid.height;++y){auto row=grid.row(y);if(row.find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)break;
        int used=0;for(int x=0;x<grid.width;++x)if(grid.at({x,y})!=" "&&!grid.at({x,y}).empty())used=x+1;
        width=std::max(width,used);if(used)height=y+1;while(!row.empty()&&row.back()==' ')row.pop_back();text+=row+'\n';
    }
    std::vector<AssertionObservation> result;
    ports->root().get("ports").iter([&](JsonVal port){if(port.get_string("case_id")!=id)return;
        AssertionObservation observation;observation.index=static_cast<int>(port.get_int("index"));observation.mapping=port.get_string("mapping");observation.status="passed";
        static const auto corrections=json::parse(kAssertionSourceCorrections);if(!corrections)throw std::runtime_error("Malformed source corrections");
        corrections->root().get("corrections").iter([&](JsonVal correction){if(correction.get_string("case_id")==id&&correction.get_int("index")==observation.index)observation.mapping=correction.get_string("mapping");});
        if(observation.mapping.starts_with("conditional-"))observation.status="conditional_foreign_ascii_option";
        else port.get("predicates").iter([&](JsonVal predicate){const auto kind=predicate.get_string("kind");const auto value=predicate.get_string("value");
            if(kind=="pending_native_golden")observation.status="pending_reviewed_native_golden_equivalence";
            else if(kind=="contains"){if(text.find(value)==std::string::npos)observation.errors.push_back("Missing original literal: "+value);}
            else if(kind=="not_contains"){if(text.find(value)!=std::string::npos)observation.errors.push_back("Unexpected original literal: "+value);}
            else if(kind=="nonempty"){if(text.find_first_not_of(" \n")==std::string::npos)observation.errors.push_back("Original nonempty output predicate failed");}
            else if(kind=="native_string_return"){if(text.empty())observation.errors.push_back("Missing native string surface");}
            else if(kind=="valid_unicode"){if(!assertion_utf8(text))observation.errors.push_back("Invalid UTF-8 or replacement scalar in output");}
            else if(kind=="dimensions"){if(width>predicate.get_int("width")||height>predicate.get_int("height"))observation.errors.push_back("Original terminal dimension bound exceeded");}
            else if(kind=="source_error_control"){if(!source_fallback)observation.errors.push_back("Error-resilience control lost exact source");}
            else observation.errors.push_back("Unknown original assertion port: "+kind);
        });
        if(!observation.errors.empty()){observation.status="failed";}result.push_back(std::move(observation));
    });return result;
}

