const std::string kFirstBatch = std::string(kFirstBatchPart1)+std::string(kFirstBatchPart2);
constexpr std::string_view kFirstBatchSha="86a98592a1b4f72ede1b05fe63edcb64561d48fad54690e994e6a18399f0db39";
void verify_snapshot_ports(){
    if(digest(kStateSnapshotPorts)!=kStateSnapshotPortsSha)throw std::runtime_error("Changed state snapshot equivalence mapping");
    const auto mapping=json::parse(kStateSnapshotPorts),facts=json::parse(kFirstBatch),ports=json::parse(kRelationAssertionPorts);if(!mapping||!facts||!ports)throw std::runtime_error("Malformed snapshot mapping");
    const auto repo=std::filesystem::path(LOOM_TESTS_DIR).parent_path();const auto root=mapping->root();
    const auto test=read(repo/root.get_string("original_test_path"));const auto offset=static_cast<std::size_t>(root.get_int("original_function_byte_offset")),size=static_cast<std::size_t>(root.get_int("original_function_byte_length"));
    if(digest(test)!=root.get_string("original_test_sha256")||offset>test.size()||size>test.size()-offset||digest(std::string_view(test).substr(offset,size))!=root.get_string("original_function_sha256"))throw std::runtime_error("Changed original snapshot function");
    std::set<std::string> ids;root.get("records").iter([&](JsonVal record){const auto id=record.get_string("case_id");if(!ids.insert(id).second)throw std::runtime_error("Duplicate snapshot mapping");
        auto checked=[&](std::string_view pathkey,std::string_view hashkey){const auto bytes=read(repo/record.get_string(pathkey));if(digest(bytes)!=record.get_string(hashkey))throw std::runtime_error("Changed snapshot source/expected bytes");return bytes;};
        const auto fixture=checked("source_fixture","source_fixture_sha256");const auto first=fixture.find_first_not_of(" \t\r\n"),last=fixture.find_last_not_of(" \t\r\n");if(first==std::string::npos||digest(std::string_view(fixture).substr(first,last-first+1))!=record.get_string("input_sha256"))throw std::runtime_error("Snapshot input preprocessing mismatch");
        auto golden=checked("original_golden","original_golden_sha256"),reference=checked("generated_reference","generated_reference_sha256");while(!golden.empty()&&golden.back()=='\n')golden.pop_back();while(!reference.empty()&&reference.back()=='\n')reference.pop_back();if(golden!=reference)throw std::runtime_error("Reference changed original expected meaning");
        bool fact_found=false;facts->root().get("cases").iter([&](JsonVal fact){if(fact.get_string("id")!=id)return;fact_found=true;if(digest(fact.to_string())!=record.get_string("frozen_fact_sha256")||fact.get_string("input_sha256")!=record.get_string("input_sha256"))throw std::runtime_error("Snapshot mapping changed frozen facts");for(const auto* key:{"direction","entities","relations","groups","notes"})if(fact.get(key).to_string()!=record.get("native_obligations").get(key).to_string())throw std::runtime_error("Snapshot obligation missing from native geometry");});
        bool port_found=false;ports->root().get("ports").iter([&](JsonVal port){if(port.get_string("case_id")==id&&port.get_int("index")==record.get_int("original_port_index")){port_found=digest(port.to_string())==record.get_string("original_port_sha256");}});
        if(!fact_found||!port_found||record.get_string("original_assertion_function_sha256")!=root.get_string("original_function_sha256"))throw std::runtime_error("Unwitnessed original snapshot mapping");
    });if(ids.size()!=8)throw std::runtime_error("Dropped state snapshot obligation");
}
void apply_snapshot_equivalence(std::vector<AssertionObservation>& observations,std::string_view id,bool verified_geometry){
    static const auto mapping=json::parse(kStateSnapshotPorts);if(!mapping)throw std::runtime_error("Malformed snapshot mapping");
    mapping->root().get("records").iter([&](JsonVal record){if(record.get_string("case_id")!=id)return;bool found=false;for(auto& observation:observations)if(observation.index==record.get_int("original_port_index")){found=true;if(observation.status!="pending_reviewed_native_golden_equivalence")throw std::runtime_error("Original snapshot status unexpectedly changed");observation.mapping="reviewed-native-geometry-equivalence";observation.status="passed_native_geometry_equivalence";if(!verified_geometry){observation.status="failed";observation.errors.push_back("Reviewed snapshot port requires actual complete geometry, not source fallback or label-only evidence");}}if(!found)throw std::runtime_error("Original snapshot obligation missing");});
}
