void verify_family_inventory(){
    const auto root=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_terminal";std::size_t count=0;
    for(const auto& lock:kFamilyLocks){const auto doc=json::parse(read(root/lock.vendor/"cases.json"));if(!doc)throw std::runtime_error("Missing family inventory");std::map<std::string,std::pair<std::string,std::string>> rows;
        doc->root().get("cases").iter([&](JsonVal row){if(row.get_string("family")!=lock.family)return;const auto id=row.get_string("id"),sha=row.get_string("sha256");if(digest(row.get_string("input"))!=sha||!rows.emplace(id,std::pair{sha,digest(row.to_string())}).second)throw std::runtime_error("Changed/duplicate original family input");});
        std::string material;for(const auto& [id,facts]:rows){material+=id;material+='\0';material+=facts.first;material+='\0';material+=facts.second;material+='\n';}
        if(rows.size()!=lock.count||digest(material)!=lock.sha)throw std::runtime_error("Dropped/changed original family obligation");count+=rows.size();
    }if(count!=862)throw std::runtime_error("Complete family count changed");
}
Entity box_entity(std::string id,std::string label){Entity e;e.id=std::move(id);e.label=std::move(label);e.headers={{e.label}};return e;}
Model basic_relation(std::string start="none",std::string end="arrow",std::string stroke="solid"){
    return {"class","LR",{box_entity("A","A"),box_entity("B","B")},{{"A","B","",std::move(start),std::move(end),std::move(stroke),0}},{},{}};
}
Grid arrow_scene(){return mock({"┌───┐     ┌───┐","│ A ├────▶│ B │","└───┘     └───┘"});}
TEST(MermaidRelationsOracle, FreezesCompleteFamiliesAndSourceCorrections){
    EXPECT_NO_THROW(verify_family_inventory());EXPECT_EQ(digest(kFirstBatch),kFirstBatchSha);
    const auto doc=json::parse(kFirstBatch);ASSERT_TRUE(doc.has_value());EXPECT_EQ(doc->root().get("cases").size(),62u);
    std::size_t drawings=0,controls=0;doc->root().get("cases").iter([&](JsonVal row){EXPECT_EQ(digest(row.get_string("input")),row.get_string("input_sha256"));if(row.get_string("expected")=="drawing")++drawings;else ++controls;});EXPECT_EQ(drawings,61u);EXPECT_EQ(controls,1u);
}
