TEST(MermaidRelationsOracle, DenseRouteWorkspaceChargesTheSharedBudgetAndRejectsExtraInk){
    Grid dense{240,1040,std::vector<std::string>(249600," ")};
    auto box=[&](int left,int right,std::string name){for(int x=left+1;x<right;++x){dense.put({x,0},"─");dense.put({x,1000},"─");}for(int y=1;y<1000;++y){dense.put({left,y},"│");dense.put({right,y},"│");}dense.put({left,0},"┌");dense.put({right,0},"┐");dense.put({left,1000},"└");dense.put({right,1000},"┘");dense.put({left+1,1},std::move(name));};
    box(0,10,"A");box(230,239,"B");
    for(int n=1;n<=50;++n){const int y=n*10;dense.put({10,y},"├");for(int x=11;x<229;++x)dense.put({x,y},"─");dense.put({229,y},"▶");}
    // The optimized arena reaches the actual whole-scene structural verdict.
    // Keep that verdict separate from the independently measured Work boundary.
    const auto model=basic_relation();Work full;
    const auto errors=validate_impl(dense,model,full);
    EXPECT_EQ(errors,(std::vector<std::string>{"Unclaimed text/control/marker/route glyph exposes a lost or extra fact"}));
    ASSERT_GT(full.left,0u);const auto cost=8000000u-full.left;
    ASSERT_GT(cost,dense.cells.size()*2u);
    // Each budget is a fresh declared assertion; no failed ledger is retried.
    Work exact;exact.left=cost;
    EXPECT_EQ(validate_impl(dense,model,exact),errors);EXPECT_EQ(exact.left,0u);
    Work short_work;short_work.left=cost-1u;bool exhausted=false;
    try{static_cast<void>(validate_impl(dense,model,short_work));}
    catch(const std::runtime_error& error){exhausted=std::string_view(error.what())=="Relation oracle work exhausted";}
    EXPECT_TRUE(exhausted);EXPECT_EQ(short_work.left,0u);
}
