Model first_batch_typed_model(JsonVal fact);
TEST(MermaidRelationsSemantics, FrozenFirstBatchViaProductionMarkdown){
    verify_source_catalog();verify_snapshot_ports();
    const auto document=json::parse(kFirstBatch);ASSERT_TRUE(document.has_value());ASSERT_EQ(digest(kFirstBatch),kFirstBatchSha);
    const auto root=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_terminal";std::map<std::string,std::string> originals;
    for(const auto* vendor:{"beautiful_mermaid","termaid"}){const auto doc=json::parse(read(root/vendor/"cases.json"));ASSERT_TRUE(doc.has_value());doc->root().get("cases").iter([&](JsonVal row){originals.emplace(row.get_string("id"),digest(row.to_string()));});}
    json::JsonMutDoc report;auto report_root=report.object();auto report_cases=report_root.make_arr();
    report_root.set("qualification","Frozen source/model/assertion expectations; frames are observations. Conditional foreign ASCII options and pending foreign snapshot equivalence are never drawing passes.");
    std::map<std::string,int> assertion_counts,source_counts;
    std::size_t visited=0;document->root().get("cases").iter([&](JsonVal fact){++visited;SCOPED_TRACE(fact.get_string("id"));const auto source=fact.get_string("input");ASSERT_EQ(digest(source),fact.get_string("input_sha256"));ASSERT_EQ(originals[fact.get_string("id")],fact.get_string("original_case_sha256"));
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));auto ordinary=loom::ui::render_markdown(fenced(source,"text"));element->ComputeRequirement();const int height=std::min(1040,std::max({32,element->requirement().min_y+8,static_cast<int>(std::count(source.begin(),source.end(),'\n'))+12}));const auto wide=capture(element,240,height),plain=capture(ordinary,240,height);const bool drawing=fact.get_string("expected")=="drawing";
        EXPECT_EQ(wide==plain,!drawing)<<"Unmet positive drawing or incorrect error-control fallback";
        const auto errors=drawing?validate(wide,first_batch_typed_model(fact)):std::vector<std::string>{};
        if(drawing)EXPECT_TRUE(errors.empty())<<explain(errors);
        auto assertions=original_assertions(wide,fact.get_string("id"),wide==plain);
        apply_snapshot_equivalence(assertions,fact.get_string("id"),drawing&&wide!=plain&&errors.empty());
        const auto conditions=source_conditions(wide,fact.get_string("id"));for(const auto& condition:conditions){++source_counts[condition.status];EXPECT_TRUE(condition.errors.empty())<<"Original source line "<<condition.index<<": "<<explain(condition.errors);}
        for(const auto& assertion:assertions){++assertion_counts[assertion.status];EXPECT_TRUE(assertion.errors.empty())<<explain(assertion.errors);}
        const auto narrow=capture(element,40,height),restored=capture(element,240,height);EXPECT_TRUE(restored==wide)<<"Same Node did not restore";
        auto sentinel=[](const Grid& g){for(int y=0;y<g.height;++y)if(g.row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)return true;return false;};EXPECT_TRUE(sentinel(wide));EXPECT_TRUE(sentinel(narrow));EXPECT_TRUE(sentinel(restored));
        int content_width=0;for(int y=0;y<wide.height;++y){if(trim(wide.row(y))=="AFTER_RELATIONS_SEMANTICS")break;for(int x=0;x<wide.width;++x)if(wide.at({x,y})!=" "&&!wide.at({x,y}).empty())content_width=std::max(content_width,x+1);}
        if(!drawing||content_width>40)EXPECT_TRUE(narrow==capture(ordinary,40,height));
        else EXPECT_TRUE(validate(narrow,first_batch_typed_model(fact)).empty())<<explain(validate(narrow,first_batch_typed_model(fact)));
        auto row=report_root.make_obj();row.set("id",fact.get_string("id"));row.set("input_sha256",digest(source));row.set("expected",fact.get_string("expected"));row.set("source_fallback",wide==plain);row.set("restored_identically",restored==wide);row.set("content_width",content_width);
        auto assertion_rows=report_root.make_arr();for(const auto& assertion:assertions){auto observation=report_root.make_obj();observation.set("original_assertion_index",assertion.index);observation.set("mapping",assertion.mapping);observation.set("status",assertion.status);auto list=report_root.make_arr();for(const auto& error:assertion.errors)list.append(report_root.make_str(error));observation.add("errors",list);assertion_rows.append(observation);}row.add("original_assertions",assertion_rows);
        auto source_rows=report_root.make_arr();for(const auto& condition:conditions){auto observation=report_root.make_obj();observation.set("original_source_line",condition.index);observation.set("status",condition.status);auto list=report_root.make_arr();for(const auto& error:condition.errors)list.append(report_root.make_str(error));observation.add("errors",list);source_rows.append(observation);}row.add("complete_source_conditions",source_rows);
        auto append=[&](std::string_view key,const std::vector<std::string>& values){auto list=report_root.make_arr();for(const auto& value:values)list.append(report_root.make_str(value));row.add(key,list);};append("semantic_errors",errors);
        auto frame=[&](std::string_view key,const Grid& grid){std::vector<std::string> rows;for(int y=0;y<grid.height;++y)rows.push_back(grid.row(y));append(key,rows);};frame("wide_frame",wide);frame("narrow_frame",narrow);frame("restored_frame",restored);report_cases.append(row);
    });EXPECT_EQ(visited,62u);
    EXPECT_EQ(assertion_counts["passed"],59);EXPECT_EQ(assertion_counts["conditional_foreign_ascii_option"],19);EXPECT_EQ(assertion_counts["pending_reviewed_native_golden_equivalence"],0);EXPECT_EQ(assertion_counts["passed_native_geometry_equivalence"],8);EXPECT_EQ(assertion_counts["failed"],0);
    EXPECT_EQ(source_counts["passed"],51);EXPECT_EQ(source_counts["conditional_foreign_ascii_option"],8);EXPECT_EQ(source_counts["failed"],0);
    auto source_totals=report_root.make_obj();for(const auto& [status,count]:source_counts)source_totals.set(status,count);report_root.add("complete_source_condition_counts",source_totals);
    auto totals=report_root.make_obj();for(const auto& [status,count]:assertion_counts)totals.set(status,count);report_root.add("original_assertion_counts",totals);
    report_root.add("cases",report_cases);report.set_root(report_root);
#ifdef LOOM_MERMAID_REPORT_DIR
    const auto path=std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-relations-semantics.json";
    std::ofstream output(path,std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'))<<"Cannot write "<<path;
#endif
}

void check_relation_resource(std::string_view source,bool drawing,const Model* model=nullptr){
    auto element=loom::ui::render_markdown(fenced(source,"mermaid"));auto ordinary=loom::ui::render_markdown(fenced(source,"text"));element->ComputeRequirement();
    const int height=std::min(1040,std::max({32,element->requirement().min_y+8,static_cast<int>(std::count(source.begin(),source.end(),'\n'))+12}));
    const auto wide=capture(element,240,height),plain=capture(ordinary,240,height);
    EXPECT_EQ(wide==plain,!drawing);
    if(drawing&&model)EXPECT_TRUE(validate(wide,*model).empty())<<explain(validate(wide,*model));
    const auto narrow=capture(element,40,height),restored=capture(element,240,height);EXPECT_TRUE(restored==wide);
    int width=0;for(int y=0;y<height;++y){if(wide.row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)break;for(int x=0;x<wide.width;++x)if(wide.at({x,y})!=" "&&!wide.at({x,y}).empty())width=std::max(width,x+1);}
    if(!drawing||width>40)EXPECT_TRUE(narrow==capture(ordinary,40,height));else if(model)EXPECT_TRUE(validate(narrow,*model).empty())<<explain(validate(narrow,*model));
    for(const auto* grid:{&wide,&narrow,&restored}){bool found=false;for(int y=0;y<grid->height;++y)if(grid->row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)found=true;EXPECT_TRUE(found);}
}
