TEST(MermaidRelationsResources, TallCompositeHeadersKeepHorizontalChildrenInsideTheirOwnFrame){
    std::vector<std::string> labels;std::string raw;
    for(int n=0;n<20;++n){const auto label="Header"+std::to_string(n);labels.push_back(label);if(n)raw+="<br>";raw+=label;}
    for(const auto* direction:{"LR","RL"}){
        const std::string source="stateDiagram-v2\ndirection "+std::string(direction)+"\nstate \""+raw+"\" {\nstate A\n}\n";
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));auto ordinary=loom::ui::render_markdown(fenced(source,"text"));
        const auto wide=capture(element,240,256);ASSERT_FALSE(wide==capture(ordinary,240,256));
        Work work;const auto frames=outlines(wide,work);std::vector<Rect> groups;
        for(const auto& frame:frames)if(frame.shape=="box"){const auto body=content(wide,frame,work);if(!body.text.empty()&&body.text.front()==labels.front())groups.push_back(frame);}
        ASSERT_EQ(groups.size(),1u);const auto& group=groups.front();auto projected=wide;
        // Validate every authored header cell in its own closed frame before
        // removing only the extra verified header rows for the existing strong
        // single-line-group oracle. Child identity/containment and every other
        // original cell remain subject to that complete geometry validator.
        for(std::size_t n=0;n<labels.size();++n){const int y=group.t+1+static_cast<int>(n);ASSERT_LT(y,group.b);const auto glyphs=ftxui::Utf8ToGlyphs(labels[n]);const int x=group.l+1+(group.r-group.l-1-static_cast<int>(glyphs.size()))/2;
            ASSERT_GT(x,group.l);ASSERT_LT(x+static_cast<int>(glyphs.size())-1,group.r);
            for(std::size_t k=0;k<glyphs.size();++k){work.spend();const Point at{x+static_cast<int>(k),y};ASSERT_EQ(wide.at(at),glyphs[k]);if(n)projected.put(at," ");}
        }
        Model model;model.family="state";model.direction=direction;model.groups={{raw,labels.front(),"","",{"A"}}};model.entities={box_entity("A","A")};model.entities.front().shape="rounded";model.entities.front().owner=raw;
        EXPECT_TRUE(validate(projected,model).empty())<<explain(validate(projected,model));
        const auto narrow=capture(element,40,256),restored=capture(element,240,256);EXPECT_EQ(restored,wide);
        int width=0;for(int y=0;y<wide.height;++y){if(wide.row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)break;for(int x=0;x<wide.width;++x)if(wide.at({x,y})!=" "&&!wide.at({x,y}).empty())width=std::max(width,x+1);}
        if(width>40)EXPECT_TRUE(narrow==capture(ordinary,40,256));
    }
}
