TEST(MermaidErTypedTableOracle, SideDividerPortsPreserveIdentityWhenCompleteLegalTablesAreExchanged){
    auto model=basic_relation("card:one","card:zero-many");model.family="er";model.direction="LR";
    model.entities[0].typed_er=ErTableSpec{{"A"},{{"int","id",{},""}}};
    model.entities[1].typed_er=ErTableSpec{{"B"},{{"str","key",{},""}}};
    const auto good=mock({
        "┌───────────┐         ┌───────────┐",
        "│     A     │         │     B     │",
        "├─────┬─────┼||─────o{┼─────┬─────┤",
        "│ int │ id  │         │ str │ key │",
        "└─────┴─────┘         └─────┴─────┘"});
    ASSERT_TRUE(validate(good,model).empty())<<explain(validate(good,model));
    auto exchanged=good;
    for(int y=1;y<4;++y)for(int x=1;x<12;++x){
        const std::string first(good.at({x,y})),last(good.at({22+x,y}));
        exchanged.put({x,y},last);exchanged.put({22+x,y},first);
    }
    Work first_work,last_work;
    ASSERT_TRUE(er_table_errors(exchanged,{0,0,12,4,"box"},*model.entities[1].typed_er,first_work).empty());
    ASSERT_TRUE(er_table_errors(exchanged,{22,0,34,4,"box"},*model.entities[0].typed_er,last_work).empty());
    EXPECT_FALSE(validate(exchanged,model).empty());
    auto wrong=good;wrong.put({12,2},"┤");EXPECT_FALSE(validate(wrong,model).empty());
    wrong=good;wrong.put({22,2},"├");EXPECT_FALSE(validate(wrong,model).empty());
}
