constexpr std::string_view kEr296TypedProfileSha="966bfe56306c25a19221d1710971fa1c424518785387b187ee1b3598d084005c";
json::JsonDoc er296_typed_profiles(){
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_native/er296_typed_profiles.json";
    const auto bytes=read(path);if(digest(bytes)!=kEr296TypedProfileSha)throw std::runtime_error("Changed source-only ER table profile ledger");
    auto document=json::parse(bytes);if(!document)throw std::runtime_error("Malformed source-only ER table profile ledger");return std::move(*document);
}
using loom::test::mermaid_relations::er296_typed_model;
// The first five ER inputs retain their immutable original models. Their
// source-backed four-field facts strengthen the same entity obligations when
// ER tables replace the old flattened attribute rows; Class/State stay exact.
Model first_batch_typed_model(JsonVal fact){
    Work input_setup;const auto canonical_input=class481_canonical(fact,input_setup);
    input_setup.spend(canonical_input.size()*8u+256u);
    auto model=parse_model(fact,input_setup);if(model.family!="er")return model;
    const auto document=er296_document();std::optional<Model> typed;
    document.root().get("cases").iter([&](JsonVal row){
        if(row.get_string("id")!=fact.get_string("id"))return;
        if(typed||row.get_string("input_sha256")!=fact.get_string("input_sha256"))throw std::runtime_error("First ER source identity changed");
        Work work;typed=er296_typed_model(row.get("diagnostic_model"),work);
    });
    if(!typed||typed->entities.size()!=model.entities.size())throw std::runtime_error("First ER typed source entity set changed");
    for(auto& entity:model.entities){
        // The original first-batch foreign model retains quotes in its local
        // ID; ER296 independently corrected that source identity. Match only
        // this source spelling normalization, retaining every original ID.
        std::string_view source_id=entity.id;
        if(source_id.size()>=2&&source_id.front()=='"'&&source_id.back()=='"')source_id=source_id.substr(1,source_id.size()-2);
        const auto found=std::ranges::find_if(typed->entities,[&](const Entity& other){return other.id==source_id;});
        if(found==typed->entities.end()||found->headers!=entity.headers||found->rows.size()!=entity.rows.size())throw std::runtime_error("First ER field identity/header/row count changed");
        entity.typed_er=found->typed_er;
    }
    return model;
}
