TEST(MermaidEr296Semantics, CompleteSourceCohortKeepsUnmetProfilesAndRequiresTypedWholeSceneGeometry){
    const auto document=er296_document(),profiles=er296_typed_profiles();const auto originals=er296_originals();verify_er296(document.root(),originals);
    std::map<std::string,JsonVal> profile_by_id;profiles.root().get("cases").iter([&](JsonVal row){if(!profile_by_id.emplace(row.get_string("id"),row).second)throw std::runtime_error("Duplicate ER table profile identity");});
    ASSERT_EQ(profile_by_id.size(),296u);
    const auto logging_facts=er_log10_document();
    std::map<std::string,JsonVal> logging_by_id;
    logging_facts.root().get("cases").iter([&](JsonVal row){ASSERT_TRUE(logging_by_id.emplace(row.get_string("id"),row).second);});
    ASSERT_EQ(logging_by_id.size(),10u);std::set<std::string> logging_consumed;
    const auto presentation_facts=er_present_document(),empty_facts=er_empty2_document();
    std::map<std::string,JsonVal> presentation_by_id,empty_by_id;std::set<std::string> presentation_consumed,empty_consumed;
    presentation_facts.root().get("cases").iter([&](JsonVal row){const auto id=row.get_string("id");ASSERT_FALSE(logging_by_id.contains(id));ASSERT_TRUE(presentation_by_id.emplace(id,row).second);});
    empty_facts.root().get("cases").iter([&](JsonVal row){const auto id=row.get_string("id");ASSERT_FALSE(logging_by_id.contains(id));ASSERT_FALSE(presentation_by_id.contains(id));ASSERT_TRUE(empty_by_id.emplace(id,row).second);});
    ASSERT_EQ(presentation_by_id.size(),12u);ASSERT_EQ(empty_by_id.size(),2u);
    const auto rich_facts=er_rich13_document();std::map<std::string,JsonVal> rich_by_id;std::set<std::string> rich_consumed;
    rich_facts.root().get("cases").iter([&](JsonVal row){const auto id=row.get_string("id");ASSERT_FALSE(logging_by_id.contains(id));ASSERT_FALSE(presentation_by_id.contains(id));ASSERT_FALSE(empty_by_id.contains(id));ASSERT_TRUE(rich_by_id.emplace(id,row).second);});ASSERT_EQ(rich_by_id.size(),13u);
    const auto final9_facts=er_final9_document();std::map<std::string,JsonVal> final9_by_id;std::set<std::string> final9_consumed;
    final9_facts.root().get("cases").iter([&](JsonVal row){const auto id=row.get_string("id");ASSERT_FALSE(logging_by_id.contains(id));ASSERT_FALSE(presentation_by_id.contains(id));ASSERT_FALSE(empty_by_id.contains(id));ASSERT_FALSE(rich_by_id.contains(id));ASSERT_TRUE(final9_by_id.emplace(id,row).second);});ASSERT_EQ(final9_by_id.size(),9u);
    json::JsonMutDoc report;auto out=report.object(),records=out.make_arr();
    out.set("qualification","Complete296 source execution with reviewed plain typed geometry, exact10 logging,12 closed presentation Models,13 literal text/MD_PARENT full Models, nine complete configuration/title scenes and two source-proven valid-empty obligations. Native geometry/empty matches do not certify original complete functions, browser/SVG/CSS/private-API/ASCII predicates.");
    out.set("facts_sha256",kEr296FactsSha);out.set("source_profile_sha256",kEr296TypedProfileSha);out.set("certified_complete_geometry",0);out.set("certified_empty",0);
    out.set("logging_source_sidecar_sha256","0c47fcac4e7b10ee1598c4de7b1755d55b9673fb794a9f6434da196c1a37083c");
    out.set("complete_config_title_source_sidecar_sha256",kErFinal9FactsSha);
    std::map<std::string,int> counts;std::size_t visited=0,active=0,pending_count=0;
    document.root().get("cases").iter([&](JsonVal fact){
        ++visited;const auto id=fact.get_string("id");SCOPED_TRACE(id);const auto& source=originals.at(id).source;
        const auto profile=profile_by_id.at(id);ASSERT_EQ(profile.get_string("input_sha256"),digest(source));ASSERT_EQ(profile.get_string("model_sha256"),digest(fact.get("diagnostic_model").to_string()));
        const bool originally_pending=profile.get_string("oracle_profile")=="profile_pending";
        const bool logging_join=logging_by_id.contains(id);
        if(logging_join)ASSERT_TRUE(originally_pending);
        const bool presentation_join=presentation_by_id.contains(id),empty_join=empty_by_id.contains(id),rich_join=rich_by_id.contains(id),final9_join=final9_by_id.contains(id),new_source_profile=presentation_join||empty_join||rich_join||final9_join;
        if(new_source_profile)ASSERT_TRUE(originally_pending);
        const bool pending=originally_pending&&!logging_join&&!new_source_profile;
        if(pending)++pending_count;else {if(!logging_join&&!new_source_profile)ASSERT_EQ(profile.get_string("oracle_profile"),"plain_typed_table");++active;}
        auto record=out.make_obj();record.set("id",id);record.set("input_sha256",digest(source));record.set("oracle_profile",profile.get_string("oracle_profile"));record.set("original_conditions_status","pending_complete_function_ports");
        auto unmet=out.make_arr();if(!logging_join&&!new_source_profile)profile.get("pending").iter([&](JsonVal value){unmet.append(out.make_str(value.as_str()));});record.add("pending",unmet);
        if(logging_join){
            record.set("oracle_profile","reviewed_canonical_logging_typed_table");
            record.set("logging_source_sidecar_sha256","0c47fcac4e7b10ee1598c4de7b1755d55b9673fb794a9f6434da196c1a37083c");
            record.set("source_model_sha256",logging_by_id.at(id).get_string("model_sha256"));
            record.set("consumed_nonvisual_source_property","config.logLevel: 1.0");
        }
        if(new_source_profile){
            if(final9_join){
                record.set("oracle_profile","reviewed_complete_config_title_ER_scene");record.set("source_scene_sha256",final9_by_id.at(id).get_string("canonical_scene_sha256"));record.set("complete_config_title_source_sidecar_sha256",kErFinal9FactsSha);
            }else if(rich_join){
                record.set("oracle_profile","reviewed_terminal_literal_MD_PARENT_typed_table");record.set("source_model_sha256",rich_by_id.at(id).get_string("native_model_sha256"));record.set("rich_source_sidecar_sha256","234934990e8816e833204e6b022cc82a2f5448be1ec8933f6fb00d64067b1f23");
            }else{
                record.set("oracle_profile",empty_join?"reviewed_valid_empty_ER":"reviewed_closed_terminal_presentation_typed_table");
                record.set("source_model_sha256",(empty_join?empty_by_id.at(id):presentation_by_id.at(id)).get_string("model_sha256"));
                record.set("presentation_source_sidecar_sha256",empty_join?"60a374801484f655bb79bb576fb0b52f9e1285f8cac63e9f2c730653ec4e942a":"6163c3d927efbbbfa42273baf376e9927e58b0a24bbde0a7d92542d7b3ee81ce");
            }
        }
        std::vector<std::string> errors;std::string outcome="execution_error";
        try{
            auto element=loom::ui::render_markdown(fenced(source,"mermaid")),ordinary=loom::ui::render_markdown(fenced(source,"text"));element->ComputeRequirement();
            const int height=std::min(1040,std::max({32,element->requirement().min_y+8,static_cast<int>(std::count(source.begin(),source.end(),'\n'))+12}));
            const auto wide=capture(element,240,height),plain=capture(ordinary,240,height),narrow=capture(element,40,height),plain_narrow=capture(ordinary,40,height),restored=capture(element,240,height);
            auto has_sentinel=[](const Grid& grid){for(int y=0;y<grid.height;++y)if(grid.row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)return true;return false;};
            EXPECT_TRUE(wide==restored);EXPECT_TRUE(has_sentinel(wide));EXPECT_TRUE(has_sentinel(narrow));EXPECT_TRUE(has_sentinel(restored));
            record.set("restored_identically",wide==restored);record.set("wide_source_fallback",wide==plain);record.set("narrow_source_fallback",narrow==plain_narrow);
            const bool healthy=wide==restored&&has_sentinel(wide)&&has_sentinel(narrow)&&has_sentinel(restored);
            Work new_profile_work;std::optional<Model> new_expected;std::optional<ErFinal9Scene> final9_expected;
            if(new_source_profile){
                if(final9_join)final9_expected=er_final9_bound_scene(final9_by_id.at(id),originals.at(id),fact,new_profile_work);
                else new_expected=rich_join?er_rich13_bound_model(rich_by_id.at(id),originals.at(id),fact,new_profile_work):empty_join?er_empty2_bound_model(empty_by_id.at(id),originals.at(id),fact,new_profile_work):er_present_bound_model(presentation_by_id.at(id),originals.at(id),fact,new_profile_work);
                if(!(final9_join?final9_consumed:rich_join?rich_consumed:empty_join?empty_consumed:presentation_consumed).insert(id).second)throw std::runtime_error("Repeated full296 reviewed source consumption");
            }
            const auto geometry_allowance=new_profile_work.left;
            if(!healthy){outcome="execution_error";errors.emplace_back("ER public Markdown execution/restoration/sentinel changed");}
            else if(pending){outcome="source_profile_pending";errors.emplace_back("Unmet complete authored ER source profile");}
            else if(wide==plain){outcome="source_fallback";errors.emplace_back("Plain typed ER positive retains source instead of drawing");}
            else if(new_source_profile){
                if(empty_join){
                    const auto full=er_empty2_errors(wide,new_profile_work);errors.insert(errors.end(),full.begin(),full.end());
                    if(narrow==plain_narrow)errors.emplace_back("Source-declared valid empty ER retained narrow source");
                    else{Work narrow_work;narrow_work.left=geometry_allowance;const auto small=er_empty2_errors(narrow,narrow_work);errors.insert(errors.end(),small.begin(),small.end());}
                    outcome=errors.empty()?"valid_empty_match_not_complete_certification":"valid_empty_geometry_mismatch";
                }else{
                    const auto full=final9_join?er_final9_scene_errors(wide,final9_expected->graph,er_final9_title(*final9_expected),new_profile_work):validate_impl(wide,*new_expected,new_profile_work);errors.insert(errors.end(),full.begin(),full.end());
                    if(narrow!=plain_narrow){Work narrow_work;narrow_work.left=geometry_allowance;const auto small=final9_join?er_final9_scene_errors(narrow,final9_expected->graph,er_final9_title(*final9_expected),narrow_work):validate_impl(narrow,*new_expected,narrow_work);errors.insert(errors.end(),small.begin(),small.end());}
                    outcome=errors.empty()?"typed_geometry_match_not_complete_certification":"typed_geometry_mismatch";
                }
            }
            else{
                try{
                    Work work;
                    const auto expected=logging_join?er_log10_bound_model(logging_by_id.at(id),originals.at(id),fact,work):er296_typed_model(fact.get("diagnostic_model"),work);
                    if(logging_join&&!logging_consumed.insert(id).second)throw std::runtime_error("Repeated full296 logging source consumption");
                    errors=validate_impl(wide,expected,work);outcome=errors.empty()?"typed_geometry_match_not_complete_certification":"typed_geometry_mismatch";
                }
                catch(const std::exception& error){outcome="oracle_error";errors.emplace_back(error.what());}
                if(errors.empty()&&narrow!=plain_narrow){
                    try{
                        Work work;
                        const auto expected=logging_join?er_log10_bound_model(logging_by_id.at(id),originals.at(id),fact,work):er296_typed_model(fact.get("diagnostic_model"),work);
                        const auto narrow_errors=validate_impl(narrow,expected,work);if(!narrow_errors.empty()){outcome="narrow_geometry_mismatch";errors=narrow_errors;}
                    }
                    catch(const std::exception& error){outcome="narrow_oracle_error";errors.emplace_back(error.what());}
                }
            }
            auto frame=out.make_arr();for(int y=0;y<wide.height;++y)frame.append(out.make_str(wide.row(y)));record.add("wide_frame",frame);
        }catch(const std::exception& error){outcome="execution_error";errors.emplace_back(error.what());}
        EXPECT_TRUE(errors.empty())<<explain(errors);auto problems=out.make_arr();for(const auto& error:errors)problems.append(out.make_str(error));record.add("errors",problems);record.set("outcome",outcome);++counts[outcome];records.append(record);
    });
    EXPECT_EQ(visited,296u);EXPECT_EQ(active,296u);EXPECT_EQ(pending_count,0u);EXPECT_EQ(logging_consumed.size(),10u);EXPECT_EQ(presentation_consumed.size(),12u);EXPECT_EQ(empty_consumed.size(),2u);EXPECT_EQ(rich_consumed.size(),13u);EXPECT_EQ(final9_consumed.size(),9u);
    out.set("records",static_cast<int64_t>(visited));out.set("unique_sources",293);
    out.set("active_plain_typed",static_cast<int64_t>(active-logging_by_id.size()-presentation_by_id.size()-empty_by_id.size()-rich_by_id.size()-final9_by_id.size()));
    out.set("active_logging_metadata_models",static_cast<int64_t>(logging_by_id.size()));out.set("active_reviewed_models",static_cast<int64_t>(active));
    out.set("active_literal_MD_PARENT_models",static_cast<int64_t>(rich_by_id.size()));
    out.set("active_complete_config_title_models",static_cast<int64_t>(final9_by_id.size()));
    out.set("active_presentation_metadata_models",static_cast<int64_t>(presentation_by_id.size()));out.set("active_valid_empty_models",static_cast<int64_t>(empty_by_id.size()));out.set("active_drawing_models",static_cast<int64_t>(active-empty_by_id.size()));
    out.set("pending_profiles",static_cast<int64_t>(pending_count));
    auto totals=out.make_obj();for(const auto& [name,count]:counts)totals.set(name,count);out.add("outcome_counts",totals);out.add("cases",records);report.set_root(out);
#ifdef LOOM_MERMAID_REPORT_DIR
    const auto path=std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-er296-typed-semantics.json";std::ofstream output(path,std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'))<<"Cannot write "<<path;
#endif
}
