TEST(MermaidErTypedResources, HeaderOnlyEntityKeepsThreeDistinctIncidentPorts){
    const std::string source="erDiagram\n direction LR\n A ||--o{ B : x\n A ||--o{ C : y\n A ||--o{ D : z\n";
    Model model{"er","LR",{box_entity("A","A"),box_entity("B","B"),box_entity("C","C"),box_entity("D","D")},
        {{"A","B","x","card:one","card:zero-many","solid",0},{"A","C","y","card:one","card:zero-many","solid",1},{"A","D","z","card:one","card:zero-many","solid",2}},{},{}};
    auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
    const auto wide=capture(element,240,256),plain=capture(loom::ui::render_markdown(fenced(source,"text")),240,256);
    ASSERT_NE(wide,plain);ASSERT_TRUE(validate(wide,model).empty())<<explain(validate(wide,model));
    Work work;const auto boxes=outlines(wide,work);bool changed=false;
    for(const auto& box:boxes){
        if(box.shape!="box")continue;
        for(int y=box.t+1;y<box.b&&!changed;++y)for(const int x:{box.l,box.r}){
            const int outside=x==box.l?L:R;const auto bits=glyph(wide.at({x,y})).bits;
            if(!(bits&outside))continue;
            auto missing=wide;
            missing.put({x+(x==box.l?-1:1),y}," ");
            EXPECT_FALSE(validate(missing,model).empty());changed=true;break;
        }
    }
    ASSERT_TRUE(changed);
    auto invented=model;invented.entities[0].rows.push_back({"attribute",{"int id"}});
    EXPECT_FALSE(validate(wide,invented).empty());
    const auto narrow=capture(element,40,256),restored=capture(element,240,256);EXPECT_EQ(wide,restored);
    EXPECT_TRUE(narrow==capture(loom::ui::render_markdown(fenced(source,"text")),40,256)||validate(narrow,model).empty());
}
