TEST(MermaidErTypedResources, MainAxisClearanceKeepsCompleteLabelsCardinalitiesAndCrossRankEdges){
    const std::string full="relationship label that forces a wide lane";
    ASSERT_EQ(ftxui::string_width(full),42);
    for(const std::string direction:{"LR","RL"})for(int variation=0;variation<3;++variation){
        SCOPED_TRACE(direction+" label variation "+std::to_string(variation));
        const std::string authored=variation==0?full:variation==1?"     "+full+"   ":"relationship<br>label that forces a wide lane";
        const std::string displayed=variation<2?full:"relationship\nlabel that forces a wide lane";
        const std::string source="erDiagram\ndirection "+direction+"\nA }o--o{ B : \""+authored+"\"\n";
        const Model model{"er",direction,{box_entity("A","A"),box_entity("B","B")},
            {{"A","B",displayed,"card:zero-many","card:zero-many","solid",0}},{},{}};
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto wide=capture(element,240,256),plain=capture(loom::ui::render_markdown(fenced(source,"text")),240,256);
        EXPECT_NE(wide,plain)<<"A complete admitted42-column label must not be squeezed into a38-column canvas";
        if(wide!=plain){
            EXPECT_TRUE(validate(wide,model).empty())<<explain(validate(wide,model));
            auto wrong=model;wrong.relations[0].label.pop_back();EXPECT_FALSE(validate(wide,wrong).empty());
            wrong=model;wrong.relations[0].end="card:one";EXPECT_FALSE(validate(wide,wrong).empty());
            wrong=model;wrong.relations[0].to="A";EXPECT_FALSE(validate(wide,wrong).empty());
            Work work;const auto frames=outlines(wide,work);auto broken=wide;bool removed=false;
            for(int y=0;y<wide.height&&!removed;++y)for(int x=0;x<wide.width;++x){
                const Point p{x,y};if(wide.at(p)!="─")continue;
                if(std::ranges::any_of(frames,[&](const Rect& frame){return p.x>=frame.l&&p.x<=frame.r&&p.y>=frame.t&&p.y<=frame.b;}))continue;
                broken.put(p," ");removed=true;break;
            }
            ASSERT_TRUE(removed);EXPECT_FALSE(validate(broken,model).empty());
        }
        const auto narrow=capture(element,40,256),restored=capture(element,240,256);EXPECT_EQ(wide,restored);
        EXPECT_TRUE(narrow==capture(loom::ui::render_markdown(fenced(source,"text")),40,256)||validate(narrow,model).empty());
        for(const auto* frame:{&wide,&narrow,&restored}){
            bool sentinel=false;for(int y=0;y<frame->height;++y)if(frame->row(y).find("AFTER_RELATIONS_SEMANTICS")!=std::string::npos)sentinel=true;
            EXPECT_TRUE(sentinel);
        }
    }
    const std::string branch="erDiagram\ndirection LR\nA ||--|| B : short\nA ||--|| C : long\n";
    const Model model{"er","LR",{box_entity("A","A"),box_entity("B","B"),box_entity("C","C")},
        {{"A","B","short","card:one","card:one","solid",0},{"A","C","long","card:one","card:one","solid",1}},{},{}};
    check_relation_resource(branch,true,&model);
}
