    EXPECT_NE(wide,plain)<<"Complete valid reciprocal source requires drawing; source remains genuinely unmet";EXPECT_EQ(wide,restored);EXPECT_TRUE(er_dag_sentinel(wide)&&er_dag_sentinel(narrow)&&er_dag_sentinel(restored));
    if(wide!=plain){const auto generic=validate(wide,model);EXPECT_TRUE(generic.empty())<<explain(generic);if(generic.empty()){const auto policy=er_reciprocal_plan_errors(wide,model);EXPECT_TRUE(policy.empty())<<explain(policy);bool completed=false;er_reciprocal_mutations(wide,model,completed);EXPECT_TRUE(completed);}}
