        bool conflict=false;for(std::size_t i=0;i<spans.size();++i)for(std::size_t j=i+1;j<spans.size();++j){inventory.spend();const auto [a,b]=spans[i];const auto [c,d]=spans[j];conflict=conflict||(a<c&&c<b&&b<d)||(c<a&&a<d&&d<b);}
