    json::JsonMutDoc report;auto out=report.object(),rows=out.make_arr();
    for(const bool declarations:{false,true}){const auto c=er_reciprocal_permuted(declarations);auto row=out.make_obj();er_reciprocal_boundary_public(c,true,row);rows.append(row);}
    out.set("qualification","Two independently declared complete positive sources; generic geometry only, never the original four-node fixed-plan wrapper. Real first f5 failures are retained.");out.add("cases",rows);report.set_root(out);
