    const std::string literal="erDiagram\nA[\"style classDef ::: #f9f\"] {\n string id \"style class ::: #f9f\"\n}\nclassDef foo fill:#f9f\nclass A foo\n";EXPECT_NO_THROW(er_present_public(literal,data,true));
