std::vector<std::string> er_empty2_errors(const Grid& grid,Work& work){
    // Physical ASCII cells, not row-string concatenation, own this protocol.
    // Validate dimensions/storage before Grid::at can index its backing vector.
    if(grid.width<=0||grid.width>240||grid.height<=0||grid.height>1040)return {"ER valid empty frame domain"};
    const auto count=static_cast<std::size_t>(grid.width)*static_cast<std::size_t>(grid.height);
    if(grid.cells.size()!=count)return {"ER valid empty backing cell count"};
    constexpr std::string_view sentinel="AFTER_RELATIONS_SEMANTICS";int sentinels=0;
    for(int y=0;y<grid.height;++y){
        int first=-1,last=-1;
        for(int x=0;x<grid.width;++x){
            work.spend();const auto cell=grid.at({x,y});
            if(cell==" ")continue;
            if(cell.size()!=1)return {"ER valid empty requires one ASCII character per physical ink cell and space padding"};
            if(first<0)first=x;
            last=x;
        }
        if(first<0)continue;
        if(last-first+1!=static_cast<int>(sentinel.size()))return {"ER valid empty has orphan/source/diagram ink"};
        for(std::size_t n=0;n<sentinel.size();++n){
            work.spend();const auto cell=grid.at({first+static_cast<int>(n),y});
            if(cell.size()!=1||cell.front()!=sentinel[n])return {"ER valid empty changed/reordered physical sentinel cells"};
        }
        if(++sentinels>1)return {"ER valid empty repeated following physical sentinel"};
    }
    if(sentinels!=1)return {"ER valid empty lost following physical sentinel"};
    return {};
}
