std::string er_rich13_breaks(std::string_view raw,Work& work,std::size_t& tokens){
    work.spend(raw.size()*2+1);std::string result;result.reserve(raw.size());
    for(std::size_t at=0;at<raw.size();){
        const auto tail=raw.substr(at);std::size_t used=0;
        for(const auto token:{"<br>","<br/>","<br />"})if(tail.starts_with(token)){used=std::string_view(token).size();break;}
        if(used){result+='\n';at+=used;++tokens;}else result+=raw[at++];
    }return result;
}
