    for(const auto key:{"family","direction","groups","notes"})er_present_require(native.get(key).to_string()==raw.get(key).to_string(),"ER rich13 changed nonprojected graph field");
    er_present_require(native.get("entities").is_arr()&&native.get("relations").is_arr()&&native.get("entities").size()==raw.get("entities").size()&&native.get("relations").size()==raw.get("relations").size()&&raw_decoded.entities.size()==native.get("entities").size(),"ER rich13 full graph counts");
    std::size_t changed_fields=0,break_tokens=0,parents=0,entity_index=0;
    native.get("entities").iter([&](JsonVal entity){
        work.spend();const auto original_entity=raw.get("entities").at(entity_index++);
        er_present_require(entity.is_obj()&&entity.size()==6&&entity.get("rows").is_arr()&&entity.get("rows").size()==original_entity.get("rows").size(),"ER rich13 complete entity schema");
        for(const auto key:{"id","label","shape","headers","owner"})er_present_require(entity.get(key).to_string()==original_entity.get(key).to_string(),"ER rich13 changed identity/header/owner");
        std::size_t attribute_index=0;entity.get("rows").iter([&](JsonVal attribute){
            work.spend();const auto before=original_entity.get("rows").at(attribute_index++),a=attribute.get("source_fields"),b=before.get("source_fields");
            er_present_require(attribute.is_obj()&&attribute.size()==3&&attribute.get_string("role")=="attribute"&&a.is_obj()&&a.size()==4&&a.get("type").is_str()&&a.get("name").is_str()&&a.get("keys").is_arr()&&a.get("comment").is_str()&&attribute.get("alternatives").is_arr()&&attribute.get("alternatives").size()==1&&attribute.get("alternatives").at(0).is_str(),"ER rich13 complete attribute schema");
            for(const auto key:{"type","name","keys"})er_present_require(a.get(key).to_string()==b.get(key).to_string(),"ER rich13 literal type/name/key order changed");
            const auto expected=er_rich13_breaks(b.get("comment").as_str(),work,break_tokens);if(expected!=b.get("comment").as_str())++changed_fields;
            er_present_require(a.get("comment").as_str()==expected,"ER rich13 single-pass comment projection");
            std::string flat=a.get_string("type")+" "+a.get_string("name");a.get("keys").iter([&](JsonVal key){er_present_require(key.is_str()&&(key.as_str()=="PK"||key.as_str()=="FK"||key.as_str()=="UK"),"ER rich13 ordered key type");flat+=' ';flat+=key.as_str();});if(!expected.empty())flat+=" \""+expected+"\"";
            er_present_require(attribute.get("alternatives").at(0).as_str()==flat,"ER rich13 typed/fallback field disagreement");
        });
    });
