    EXPECT_EQ(visited.size(),13u);EXPECT_EQ(entities,34u);EXPECT_EQ(attributes,37u);EXPECT_EQ(relations,16u);EXPECT_EQ(parents,3u);EXPECT_EQ(fields,12u);EXPECT_EQ(tokens,14u);
