TEST(MermaidErFinal9Native, AllThirtyOneTypedScalarPartnersRequireTheirCompletePublicSceneOrWholeSource) {
    constexpr std::string_view path="mermaid_native/er_final9_scalar_partners.json";
    constexpr std::string_view fact_sha="4237ed3ef0d0c08f0de2209c648ab7b8fd917b0e5bc69824613c36d0cb08dab5";
    constexpr std::string_view body="erDiagram\nA { int id }\n";
    // Independent literal complete graph for the authored body, never obtained
    // from a renderer or by stripping a decorated source after fallback.
    constexpr std::string_view graph_literal=R"ERSP({"family":"er","direction":"TB","entities":[{"id":"A","label":"A","shape":"box","owner":"","headers":[["A"]],"rows":[{"role":"attribute","alternatives":["int id"],"source_fields":{"type":"int","name":"id","keys":[],"comment":""}}]}],"relations":[],"groups":[],"notes":[]})ERSP";
    const auto file=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/path;
    Work setup;const auto size=std::filesystem::file_size(file);
    er_present_require(size<=131072,"ER scalar partners immutable asset cap");setup.spend(static_cast<std::size_t>(size)*4);
    const auto bytes=read(file);ASSERT_EQ(bytes.size(),size);ASSERT_EQ(digest(bytes),fact_sha);
    const auto facts=json::parse(bytes);ASSERT_TRUE(facts);
    ASSERT_EQ(facts->root().get_string("schema"),"er_final9_v3_source_partners/proposed");
    ASSERT_EQ(facts->root().get_string("body"),body);ASSERT_EQ(digest(body),facts->root().get_string("body_sha256"));
    ASSERT_TRUE(facts->root().get("cases").is_arr());ASSERT_EQ(facts->root().get("cases").size(),31u);
    ASSERT_TRUE(facts->root().get("counts").get("whole_scene").is_int());ASSERT_EQ(facts->root().get("counts").get_int("whole_scene"),13);
    ASSERT_TRUE(facts->root().get("counts").get("whole_source").is_int());ASSERT_EQ(facts->root().get("counts").get_int("whole_source"),18);
    Work graph_setup;graph_setup.spend(4u*131072u);
    const auto independent=json::parse(graph_literal);ASSERT_TRUE(independent);
    const auto base_graph=er296_typed_model(independent->root(),graph_setup);
    std::set<std::string> names,sources;int visited=0,scene_expected=0,source_expected=0,public_completed=0,titled=0,nonvisual=0;
    facts->root().get("cases").iter([&](JsonVal row){
        ++visited;ASSERT_TRUE(row.is_obj());ASSERT_TRUE(row.get("name").is_str());SCOPED_TRACE(row.get_string("name"));
        // Immutable source-integrity/decode scope is separate from the existing
        // public helper's per-scene Work. Neither catches/retries exhaustion.
        Work source_work;source_work.spend(4u*131072u);
        ASSERT_TRUE(row.get("source").is_str());ASSERT_TRUE(row.get("source_sha256").is_str());
        const auto source=row.get("source").as_str();source_work.spend(source.size()*4+row.get("name").as_str().size()*2+64);
        ASSERT_LE(source.size(),65536u);ASSERT_EQ(digest(source),row.get_string("source_sha256"));
        ASSERT_TRUE(source.ends_with(body));ASSERT_TRUE(names.insert(row.get_string("name")).second);ASSERT_TRUE(sources.insert(row.get_string("source_sha256")).second);
        ASSERT_TRUE(row.get("expected").is_str());ASSERT_EQ(row.get_string("runtime_status"),"not_executed");
        const auto expected=row.get("expected").as_str();ASSERT_TRUE(expected=="whole_scene"||expected=="whole_source");
        ErFinal9Scene scene;
        if(expected=="whole_scene") {
            ++scene_expected;ASSERT_TRUE(row.get("complete_graph").is_obj());
            ASSERT_TRUE(er_present_same_json(row.get("complete_graph"),independent->root(),source_work));
            scene.graph=er296_typed_model(row.get("complete_graph"),source_work);
            ASSERT_EQ(scene.graph.family,"er");ASSERT_EQ(scene.graph.direction,"TB");ASSERT_EQ(scene.graph.entities.size(),1u);
            ASSERT_TRUE(scene.graph.relations.empty()&&scene.graph.groups.empty()&&scene.graph.notes.empty());
            const auto& entity=scene.graph.entities.front();ASSERT_EQ(entity.id,"A");ASSERT_EQ(entity.label,"A");ASSERT_TRUE(entity.typed_er.has_value());
            ASSERT_EQ(entity.typed_er->header,(std::vector<std::string>{"A"}));ASSERT_EQ(entity.typed_er->attributes.size(),1u);
            const auto& field=entity.typed_er->attributes.front();ASSERT_EQ(field.type,"int");ASSERT_EQ(field.name,"id");ASSERT_TRUE(field.keys.empty());ASSERT_TRUE(field.comment.empty());
            if(row.get("title").is_str()){scene.title=row.get_string("title");ASSERT_FALSE(scene.title->empty());++titled;}
            else{ASSERT_TRUE(row.get("title").is_null());++nonvisual;}
        } else {
            ++source_expected;ASSERT_TRUE(row.get("complete_graph").is_null());ASSERT_TRUE(row.get("title").is_null());
            // The closed-source branch never treats an empty drawing or a
            // partial body as success. Its helper compares whole source cells.
            source_work.spend(4096);scene.graph=base_graph;
        }
        try {
            // This unchanged helper owns its sole public Work: source/captures,
            // prefix/separator and full graph share that helper's allowance.
            // For non-title positives it also requires exact baseline pixels;
            // for closed controls both240 and40 must equal the entire source.
            er_final9_public_control(source,scene,expected=="whole_scene");++public_completed;
        } catch(const std::exception& error) {ADD_FAILURE()<<"ER scalar partner public execution: "<<error.what();}
    });
    EXPECT_EQ(visited,31);EXPECT_EQ(names.size(),31u);EXPECT_EQ(sources.size(),31u);
    EXPECT_EQ(scene_expected,13);EXPECT_EQ(source_expected,18);EXPECT_EQ(titled,7);EXPECT_EQ(nonvisual,6);EXPECT_EQ(public_completed,31);
}
