        auto item=root.make_obj();item.set("id",id);item.set("source_sha256",row.get_string("source_sha256"));item.set("whole_native_model_sha256",row.get_string("whole_native_model_sha256"));item.set("facts_sha256",std::string(kClass481FactsSha));std::vector<std::string> errors,observations;std::string phase="source",outcome="execution_error";bool is_fallback=false,good=false,negative_done=false;
