            work.spend(static_cast<std::size_t>(height)*(3u*240u+2u*40u)*4u+256u);const auto wide=capture(node,240,height),ordinary=capture(plain,240,height),narrow=capture(node,40,height),small=capture(plain,40,height),restored=capture(node,240,height);++observed;is_fallback=wide==ordinary;fallback+=is_fallback;
            item.set("wide_source_fallback",is_fallback);item.set("narrow_source_fallback",narrow==small);item.set("restored_identically",restored==wide);bool physical=true;for(const auto* frame:{&wide,&narrow,&restored})physical&=class481_sentinel(*frame,work);item.set("following_content_retained",physical);
            if(!physical)observations.emplace_back("Namespace45 complete physical sentinel missing/repeated");if(restored!=wide)observations.emplace_back("Namespace45 same-Node restore differs");
            work.spend(static_cast<std::size_t>(height)*(240u+40u+240u)*8u+256u);
            for(const auto& [name,grid]:std::array<std::pair<std::string_view,const Grid*>,3>{{{"wide_frame",&wide},{"narrow_frame",&narrow},{"restored_frame",&restored}}}){auto frame=root.make_arr();for(int y=0;y<grid->height;++y)frame.append(root.make_str(grid->row(y)));item.add(name,frame);}
            item.set("wide_frame_sha256",class481_frame_hash(wide,work));item.set("narrow_frame_sha256",class481_frame_hash(narrow,work));item.set("restored_frame_sha256",class481_frame_hash(restored,work));
            phase="complete_original_source_binding";class481_bind(row,at,originals,work);const auto found=std::ranges::find_if(kNamespace45Bindings,[&](const auto& pin){work.spend(pin[0].size()+id.size()+1u);return pin[0]==id;});
            class481_require(found!=kNamespace45Bindings.end()&&row.get_string("source_sha256")==(*found)[1]&&row.get_string("whole_native_model_sha256")==(*found)[2],"Namespace45 selected complete source/Model pins");
            phase="complete_Model_decode";const auto model=class481_model(meaning,work);++decoded;
