    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-grammar35-hands.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_string()<<'\n'));
#endif
    EXPECT_EQ(visited,6);EXPECT_EQ(paper_good,6);EXPECT_EQ(paper_mutated,6);EXPECT_EQ(public_observed,6);EXPECT_EQ(public_good,6);EXPECT_EQ(public_mutated,6);EXPECT_EQ(oracle_errors,0);
