    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-grammar35-native.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_string()<<'\n'));
