TEST(MermaidClassGrammar35, BlankHeaderKeepsPhysicalRowCompartmentAndObservableEndpointIdentity){
    Work preparation;preparation.spend(kClassBlankRepairHand.size()*3u+256u);const auto doc=json::parse(kClassBlankRepairHand);ASSERT_TRUE(doc);const auto paper=doc->root();
    const auto meaning=paper.get("whole_native_model");class481_require(digest(class481_canonical(meaning,preparation))==paper.get_string("whole_native_model_sha256"),"Class blank repair complete hand Model digest");
    const auto input=class481_text(paper.get("source"),preparation);class481_require(digest(input)==paper.get_string("source_sha256"),"Class blank repair complete hand source digest");
    const auto model=class481_model(meaning,preparation);const auto good=namespace45_grid(paper,preparation);ASSERT_TRUE(namespace45_good(good,model,preparation));
    auto pixel_bad=[&](const Grid& original,const Model& expected,auto change){
        Work work;work.spend(original.cells.size()*(sizeof(std::string)+12u)+256u);static_cast<void>(class481_copy_charge(expected,work));auto changed=original;change(changed);
        const auto errors=validate_impl(changed,expected,work);class481_no_resource(errors);EXPECT_FALSE(errors.empty())<<"Class blank repair accepted a physical adversary";
    };
    namespace45_reject_cell(good,model,{3,2}," ","X");
    namespace45_reject_cell(good,model,{3,2}," ","");
    namespace45_reject_cell(good,model,{1,1},"┌"," ");
    pixel_bad(good,model,[](Grid& bad){for(int x=2;x<5;++x)bad.put({x,7},"─");bad.put({1,7},"┌");bad.put({5,7},"┐");bad.put({1,8},"│");bad.put({5,8},"│");for(int x=2;x<5;++x)bad.put({x,9},"─");bad.put({1,9},"└");bad.put({5,9},"┘");});
    namespace45_reject_model(good,model,[](Model& wrong){wrong.relations[0].to="class:43";});
    const auto changes=class481_mutations(good,model,preparation);EXPECT_TRUE(changes.errors.empty())<<explain(changes.errors);
    Work member_setup;member_setup.spend(kClass35Papers.size()*3u+256u);const auto papers=json::parse(kClass35Papers);ASSERT_TRUE(papers);const auto member_paper=papers->root().at(1);
    const auto member_model=class481_model(member_paper.get("whole_native_model"),member_setup);const auto member=namespace45_grid(member_paper,member_setup);ASSERT_TRUE(namespace45_good(member,member_model,member_setup));
    pixel_bad(member,member_model,[](Grid& bad){bad.put({1,3},"│");for(int x=2;x<11;++x)bad.put({x,3}," ");bad.put({11,3},"│");});
    pixel_bad(member,member_model,[](Grid& bad){bad.put({1,2},"├");for(int x=2;x<11;++x)bad.put({x,2},"─");bad.put({11,2},"┤");});
    // This direct forged header is schema-invalid, not a geometry negative.
    // It must fail safely without entering any header.size()-1 member index.
    Work invalid;static_cast<void>(class481_copy_charge(member_model,invalid));auto headerless=member_model;headerless.entities[0].headers={{}};
    EXPECT_FALSE(class_blank_header_content(member,{1,1,11,5,"box"},headerless.entities[0],invalid));
    Work zero{0};bool resource=false;try{static_cast<void>(class_blank_header_content(good,{1,1,5,3,"box"},model.entities[0],zero));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource)<<"Zero Work must remain a resource error, not a semantic rejection";
}
