TEST(MermaidClassGrammar35, SourceOwnedLexicalBoundariesKeepWholeSourceAndFollowingContent){
    constexpr std::array<std::string_view,8> closed{{
    R"CLASS35SOURCE(classDiagram
class A
class B
A ()-- B
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
class A["<i>Title</i>"]
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
<<bad name>> A
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
class A["Alias"] { +x }
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
class A
click A call unknown()
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
<<interface>> Missing
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
class C {
+half(
}
)CLASS35SOURCE",
    R"CLASS35SOURCE(classDiagram
class C {
+half)
}
)CLASS35SOURCE"
    }};
    constexpr std::string_view first_annotation_source="classDiagram\n<<interface>> Missing\n";
    constexpr std::string_view first_annotation_Model=R"ANNOTATIONMODEL({"direction":"TB","entities":[{"headers":[["Missing","<<interface>>"],["<<interface>>","Missing"]],"id":"class:4d697373696e67","label":"Missing","owner":"","rows":[],"shape":"box"}],"family":"class","groups":[],"notes":[],"relations":[]})ANNOTATIONMODEL";
    int observed=0;
    for(const auto source:closed){SCOPED_TRACE(std::string(source));try{
        Work work;const auto frames=class35_observe(source,work);++observed;
        if(source==first_annotation_source){
            // Preserve this exact historical source; its source-owned annotation
            // creates the class before add_annotation. Require the whole scene.
            work.spend(first_annotation_Model.size()*8u+4096u);
            class481_require(digest(source)=="865b06e7fa7575e1434dc74b1fdc9cf7b2b9fbf2d9e10e520d5e33f919d240cc","Class35 first annotation exact historical source");
            const auto doc=json::parse(first_annotation_Model);class481_require(doc.has_value(),"Class35 first annotation full Model parse");
            const auto model=class481_model(doc->root(),work);const auto allowance=work.left;
            class481_require(frames.wide!=frames.ordinary,"Class35 first annotation mandatory positive fell back");
            const auto large=validate_impl(frames.wide,model,work);class481_no_resource(large);EXPECT_TRUE(large.empty())<<explain(large);
            if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow);class481_no_resource(small);EXPECT_TRUE(small.empty())<<explain(small);}
            if(large.empty()){
                const auto changes=class481_mutations(frames.wide,model,work);EXPECT_TRUE(changes.errors.empty())<<explain(changes.errors);
            }
            EXPECT_TRUE(frames.restored==frames.wide);
        }else{
            EXPECT_TRUE(frames.wide==frames.ordinary);EXPECT_TRUE(frames.narrow==frames.small);EXPECT_TRUE(frames.restored==frames.wide);
        }
        // Source preservation must contain real physical source ink, not only
        // an ordinary/fallback equality and the following sentinel.
        constexpr std::string_view token="classDiagram";bool source_ink=false;
        for(int y=0;y<frames.ordinary.height;++y){work.spend();for(int x=0;x+static_cast<int>(token.size())<=frames.ordinary.width;++x){
            work.spend();bool exact=true;for(std::size_t n=0;n<token.size();++n){work.spend();exact&=frames.ordinary.at({x+static_cast<int>(n),y})==token.substr(n,1);}
            source_ink|=exact;
        }}
        EXPECT_TRUE(source_ink)<<"Closed Class35 profile lost real source header ink";
        for(const auto* frame:{&frames.wide,&frames.narrow,&frames.restored})EXPECT_TRUE(class481_sentinel(*frame,work));
    }catch(const std::exception& error){ADD_FAILURE()<<"Class35 closed profile/resource/execution failure: "<<error.what();}}
    EXPECT_EQ(observed,static_cast<int>(closed.size()));
    // Following whitespace separates an unmarked line from the real 'other'
    // Class identity. The suffix parser must not steal its first letter.
    constexpr std::string_view source=R"CLASS35SOURCE(classDiagram
direction LR
class A
class other
A -- other : plain
)CLASS35SOURCE";
    constexpr std::string_view meaning=R"CLASS35MODEL({"direction":"LR","entities":[{"headers":[["A"]],"id":"class:41","label":"A","owner":"","rows":[],"shape":"box"},{"headers":[["other"]],"id":"class:6f74686572","label":"other","owner":"","rows":[],"shape":"box"}],"family":"class","groups":[],"notes":[],"relations":[{"end":"none","label":"plain","order":0,"source":"class:41","start":"none","stroke":"solid","target":"class:6f74686572"}]})CLASS35MODEL";
    Work work;const auto frames=class35_observe(source,work);
    work.spend(meaning.size()*3u+128u);const auto doc=json::parse(meaning);ASSERT_TRUE(doc);
    ASSERT_EQ(digest(source),"eadf24d545215d18b865ba41f8bd67f8d820dda3a5880ea360f18376727ff49d");ASSERT_EQ(digest(class481_canonical(doc->root(),work)),"88d51e298887f7af5820f2ff995f79413ca64b01911873d8f0a8a9fef89b37e8");
    const auto model=class481_model(doc->root(),work);
    for(const auto* frame:{&frames.wide,&frames.narrow,&frames.restored})ASSERT_TRUE(class481_sentinel(*frame,work));
    const auto allowance=work.left;const auto errors=class35_geometry(frames,model,allowance);ASSERT_TRUE(errors.empty())<<explain(errors);
    const auto changes=class481_mutations(frames.wide,model,work);EXPECT_TRUE(changes.errors.empty())<<explain(changes.errors);
}
