bool angle6eba_central_tokens(std::string_view text,Work& work){
    // This is a native profile boundary, not an upstream-invalidity claim.
    // Model BRs are already decoded; no HTML/entity/alias/member parsing here.
    for(std::size_t n=0;n<text.size();++n){work.spend();if(text[n]!='<'&&text[n]!='>')continue;
        const auto boundary=[](char value){return value==' '||value=='\t';};
        if((n&& !boundary(text[n-1]))||(n+1<text.size()&&!boundary(text[n+1])))return false;
    }return true;
}
