    Work setup;const auto added=endpoint29_document(setup);endpoint29_schema(added.root(),setup);const auto facts=class481_document();const auto originals=class481_originals(facts.root());const auto angle=angle6eba_document(setup);json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
