            work.spend(static_cast<std::size_t>(height)*(3u*240u+2u*40u)*4u+256u);
            const auto wide=capture(node,240,height),ordinary=capture(plain,240,height),narrow=capture(node,40,height),small=capture(plain,40,height),restored=capture(node,240,height);++observed;const bool source_fallback=wide==ordinary;fallback+=source_fallback;
            item.set("wide_source_fallback",source_fallback);item.set("narrow_source_fallback",narrow==small);const bool same_restore=class481_same_grid(wide,restored,work);item.set("restored_identically",same_restore);
