            const bool restored_sentinel=same_restore?wide_sentinel:class481_sentinel(restored,work);
            for(const bool physical:{wide_sentinel,narrow_sentinel,restored_sentinel})if(!physical)observations.emplace_back("Endpoint29 physical following sentinel");
            work.spend(static_cast<std::size_t>(height)*(240u+40u+240u)*8u+256u);
            for(const auto& [name,grid]:std::array<std::pair<std::string_view,const Grid*>,3>{{{"wide_frame",&wide},{"narrow_frame",&narrow},{"restored_frame",&restored}}}){auto frame=root.make_arr();for(int y=0;y<grid->height;++y)frame.append(root.make_str(grid->row(y)));item.add(name,frame);}
            item.set("frame_width",wide.width);item.set("frame_height",wide.height);const auto wide_hash=class481_frame_hash(wide,work);item.set("wide_frame_sha256",wide_hash);item.set("narrow_frame_sha256",class481_frame_hash(narrow,work));item.set("restored_frame_sha256",same_restore?wide_hash:class481_frame_hash(restored,work));
            phase="complete_original_source_binding";const auto ordinal=static_cast<std::size_t>(row.get_int("inventory_ordinal"));class481_require(ordinal<481,"Endpoint29 original ordinal");endpoint29_bind(row,facts.root().get("cases").at(ordinal),originals,work);
            const auto declared=row.get("whole_native_model_candidate");
