json::JsonDoc endpoint_row_band_document(Work& setup){
    setup.spend(kEndpointRowBandBytes*3u+256u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kEndpointRowBandPath;
    class481_require(std::filesystem::file_size(path)==kEndpointRowBandBytes,"Endpoint row-band exact asset size");
    const auto bytes=read(path);
    class481_require(bytes.size()==kEndpointRowBandBytes&&digest(bytes)==kEndpointRowBandSha,"Endpoint row-band complete immutable paper asset");
    auto document=json::parse(bytes);class481_require(document.has_value(),"Endpoint row-band JSON parse");
    const auto root=document->root();class481_keys(root,{"schema","author","source_design_review_sha256","qualification","papers"},setup);
    class481_require(root.get_string("schema")=="class_endpoint_row_band_literal_papers/v1"&&root.get_string("source_design_review_sha256")=="c9feb736c21e96da552064830e30dfde1f0f0f741d57ab64d753bfef5dc5ffe1"&&root.get("papers").is_arr()&&root.get("papers").size()==5,"Endpoint row-band source/design denominator");
    return std::move(*document);
}
Model endpoint_row_band_model(JsonVal paper,std::size_t index,JsonVal reviewed,Work& work){
    class481_require(index<kEndpointRowBandBindings.size(),"Endpoint row-band fixed ordinal");
    class481_keys(paper,{"name","original_immutable_source","source","source_sha256","whole_native_model","whole_native_model_sha256","width","height","literal_rows","cards","edge_coordinate_transcription","pixel_controls","removed_physical_row","qualification"},work);
    const auto source=class481_text(paper.get("source"),work);
    work.spend(source.size()*4u+256u);
    class481_require(digest(source)==paper.get_string("source_sha256")&&paper.get_string("source_sha256")==kEndpointRowBandBindings[index][0],"Endpoint row-band exact complete source");
    const auto meaning=paper.get("whole_native_model");const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*3u+64u);
    class481_require(digest(encoded)==paper.get_string("whole_native_model_sha256")&&paper.get_string("whole_native_model_sha256")==kEndpointRowBandBindings[index][1],"Endpoint row-band complete source Model digest");
    class481_require(paper.get("original_immutable_source").is_bool()&&paper.get("original_immutable_source").as_bool()==(index<2),"Endpoint row-band actual versus independent source scope");
    if(index<2){
        int found=0;reviewed.get("cases").iter([&](JsonVal row){
            work.spend(row.get("id").as_str().size()+64u);if(row.get_string("id")!=paper.get_string("name"))return;++found;
            work.spend(source.size()*2u+128u);
            class481_require(row.get_string("source")==source&&row.get_string("source_sha256")==paper.get_string("source_sha256")&&row.get_string("whole_native_model_candidate_sha256")==paper.get_string("whole_native_model_sha256"),"Endpoint row-band immutable K3 authority");
            class481_require(class481_canonical(row.get("whole_native_model_candidate"),work)==encoded,"Endpoint row-band unchanged whole K3 Model");
        });class481_require(found==1,"Endpoint row-band actual source binds once");
    }
    const auto model=class481_model(meaning,work,true);
    class481_require(model.entities.size()==(index==4?4u:3u)&&model.relations.size()==(index==4?12u:6u)&&model.groups.empty()&&model.notes.empty(),"Endpoint row-band complete actors and all reciprocal edges");
    return model;
}
bool endpoint_row_band_reject_grid(const Grid& good,const Model& model,auto mutate){
    Work work;work.spend(good.cells.size()*(sizeof(std::string)+12u)+256u);
    auto changed=good;mutate(changed,work);
    const auto errors=validate_impl(changed,model,work);class481_no_resource(errors);
    EXPECT_FALSE(errors.empty())<<"Accepted Endpoint row-band actual glyph/row adversary";return !errors.empty();
}
void endpoint_row_band_run(std::size_t index){
    Work setup;
    const auto papers=endpoint_row_band_document(setup),reviewed=endpoint29_document(setup);
    endpoint29_schema(reviewed.root(),setup);
    class481_require(index<5,"Endpoint row-band complete paper ordinal");
    const auto paper=papers.root().get("papers").at(index);SCOPED_TRACE(paper.get_string("name"));
    try{
        Work work;
        const auto model=endpoint_row_band_model(paper,index,reviewed.root(),work);
        const auto grid=namespace45_grid(paper,work);
        class481_require(paper.get("removed_physical_row").is_int()&&paper.get_int("removed_physical_row")>0&&paper.get_int("removed_physical_row")<grid.height-3,"Endpoint row-band removed row is within whole scene before sentinel");
        const auto controls=paper.get("pixel_controls");
        class481_require(controls.is_arr()&&controls.size()>=model.relations.size()+4u,"Endpoint row-band all owned marker and pixel controls");
        controls.iter([&](JsonVal control){
            class481_keys(control,{"kind","x","y","before","after"},work);
            class481_require(control.get("x").is_int()&&control.get("y").is_int()&&control.get_int("x")>=0&&control.get_int("x")<grid.width&&control.get_int("y")>=0&&control.get_int("y")<grid.height,"Endpoint row-band control physical domain");
            const Point at{static_cast<int>(control.get_int("x")),static_cast<int>(control.get_int("y"))};
            const auto before=class481_text(control.get("before"),work,16),after=class481_text(control.get("after"),work,16);
            class481_require(before!=after&&grid.at(at)==before,"Endpoint row-band real changed-cell witness");
        });
        // A failed complete good paper executes no geometry-negative claims.
        if(!namespace45_good(grid,model,work))return;
        const auto changes=endpoint29_mutations(grid,model,work);
        for(const auto& error:changes.errors)ADD_FAILURE()<<error;
        if(!changes.errors.empty())return;
        class481_require(changes.executed.at("endpoint_text_value")==static_cast<int>(model.relations.size()*2u),"Endpoint row-band both endpoint-value adversaries for every edge");
        std::size_t executed=0;
        controls.iter([&](JsonVal control){
            work.spend(256u);
            const Point at{static_cast<int>(control.get_int("x")),static_cast<int>(control.get_int("y"))};
            const auto before=class481_text(control.get("before"),work,16),after=class481_text(control.get("after"),work,16);
            class481_require(grid.at(at)==before&&before!=after,"Endpoint row-band positive pixel exists before mutation");
            if(endpoint_row_band_reject_grid(grid,model,[&](Grid& wrong,Work& local){local.spend(after.size()*4u+16u);wrong.put(at,std::string(after));}))++executed;
        });
        EXPECT_EQ(executed,controls.size());
        if(executed!=controls.size())return;
        const int row=static_cast<int>(paper.get_int("removed_physical_row"));
        const bool removed=endpoint_row_band_reject_grid(grid,model,[&](Grid& wrong,Work& local){
            class481_require(row>0&&row<wrong.height-3,"Endpoint row-band real physical row-removal bounds");
            local.spend(wrong.cells.size()*4u+256u);
            for(int y=row;y+1<wrong.height;++y)for(int x=0;x<wrong.width;++x)wrong.put({x,y},std::string(grid.at({x,y+1})));
            for(int x=0;x<wrong.width;++x)wrong.put({x,wrong.height-1}," ");
        });
        EXPECT_TRUE(removed);
        Work zero;zero.left=0;bool resource=false;
        try{static_cast<void>(validate_impl(grid,model,zero));}
        catch(const std::runtime_error& error){resource=class481_resource(error.what());}
        EXPECT_TRUE(resource)<<"Resource exhaustion is not semantic rejection credit";
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
