TEST(MermaidClassEndpointRowBands, OriginalSingleRowBTK3HasAllSixOwnedRoutes){endpoint_row_band_run(0);}
TEST(MermaidClassEndpointRowBands, OriginalTwoRowBTK3HasAllSixOwnedRoutes){endpoint_row_band_run(1);}
TEST(MermaidClassEndpointRowBands, UnequalEndpointRowsTBRetainBothSemanticEnds){endpoint_row_band_run(2);}
TEST(MermaidClassEndpointRowBands, UnequalEndpointRowsBTRetainBothSemanticEnds){endpoint_row_band_run(3);}
TEST(MermaidClassEndpointRowBands, TwoPageK4KeepsIndependentSameVertexBands){endpoint_row_band_run(4);}

