TEST(MermaidClassEndpoint29, DistinctRolesOnOneRouteCannotShareOnePrintedMultilineCell){
    Work setup;setup.spend(kEndpointIntraRelationRolePaper.size()*3u+256u);
    const auto document=json::parse(kEndpointIntraRelationRolePaper);ASSERT_TRUE(document);
    const auto paper=document->root();
    try{
        Work work;
        const auto source=class481_text(paper.get("source"),work,1024);
        work.spend(source.size()*2u+128u);
        class481_require(digest(source)==paper.get_string("source_sha256"),"Intra-relation complete literal source hash");
        const auto meaning=paper.get("whole_native_model");
        class481_require(digest(class481_canonical(meaning,work))==paper.get_string("whole_native_model_sha256"),"Intra-relation complete Model hash");
        const auto model=class481_model(meaning,work,true);
        class481_require(model.entities.size()==2&&model.relations.size()==1&&model.groups.empty()&&model.notes.empty(),"Intra-relation complete literal scene");
        class481_require(model.relations[0].source_text==std::optional<std::string>{"a\nb"}&&model.relations[0].label=="b\nc"&&!model.relations[0].target_text,"Intra-relation exact two authored roles");
        const auto good=namespace45_grid(paper.get("independent_good"),work);
        // No negative credit is possible before the full independent scene passes.
        if(!namespace45_good(good,model,work))return;
        const auto shared=namespace45_grid(paper.get("shared_bad"),work);
        class481_require(shared.at({20,5})=="a"&&shared.at({20,6})=="b"&&shared.at({20,7})=="c","Intra-relation exact borrowed middle b cell");
        const auto errors=validate_impl(shared,model,work);class481_no_resource(errors);
        EXPECT_FALSE(errors.empty())<<"One printed b cannot own both source a\nb and central b\nc on two real gaps";
        // Exhaustion is separately visible and cannot satisfy the semantic negative.
        Work zero;zero.left=0;bool resource=false;
        try{static_cast<void>(validate_impl(shared,model,zero));}
        catch(const std::runtime_error& error){resource=class481_resource(error.what());}
        EXPECT_TRUE(resource)<<"Resource exhaustion is not role-cell rejection evidence";
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
