namespace {
TEST(MermaidClassEndpoint29, SourceLiteralSupplementPreservesWholeNullLineageAndRejectsTypedBoundaryMutations){
    try{
        Work setup;const auto parent=endpoint29_document(setup);endpoint29_schema(parent.root(),setup);const auto supplement=angle6eba_document(setup);
        JsonVal original;std::size_t nulls=0;
        parent.root().get("cases").iter([&](JsonVal row){setup.spend();if(row.get("whole_native_model_candidate").is_null()){++nulls;original=row;}});
        class481_require(nulls==1&&original.valid(),"Angle6eba exactly one immutable historical null");
        Work work;const auto meaning=angle6eba_meaning(supplement.root(),original,work);const auto model=class481_model(meaning,work,true);
        EXPECT_EQ(model.entities.size(),28u);EXPECT_EQ(model.relations.size(),15u);EXPECT_EQ(model.relations.at(14).label,"< owns");
        EXPECT_TRUE(original.get("whole_native_model_candidate").is_null());
        std::size_t endpoint_fields=0;for(const auto& relation:model.relations){work.spend();endpoint_fields+=relation.source_text.has_value()+relation.target_text.has_value();}EXPECT_EQ(endpoint_fields,3u);
        // Semantic source/token checks precede final immutable provenance hash.
        // None of these controls passes merely because a digest mismatched.
        const auto encoded=class481_canonical(supplement.root(),work);
        auto reject=[&](std::string_view expected,auto change){
            Work local;local.spend(encoded.size()*16u+256u);json::JsonMutDoc altered;auto value=altered.raw_json(encoded);altered.set_root(value);change(value,local);
            const auto changed=altered.to_string();local.spend(changed.size()*4u+128u);const auto parsed=json::parse(changed);ASSERT_TRUE(parsed);bool rejected=false;
            try{static_cast<void>(angle6eba_meaning(parsed->root(),original,local));}
            catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()))<<error.what();EXPECT_EQ(std::string_view(error.what()),expected);rejected=true;}
            EXPECT_TRUE(rejected);
        };
        reject("CLASS481 exact object fields",[](json::JsonMutVal value,Work&){value.set("unknown",true);});
        reject("CLASS481 exact bounded text type",[](json::JsonMutVal value,Work&){value.get("case").get("whole_native_model_candidate").get("relations").at(14).set("label",false);});
        reject("Angle6eba sole source label delta",[](json::JsonMutVal value,Work&){value.get("case").get("whole_native_model_candidate").get("relations").at(14).set("label","");});
        for(const auto text:{"<owns","abc>","2>1","x<tag","<BR>","<br\t/>"}){
            SCOPED_TRACE(text);
            reject("Angle6eba central angle token boundary",[&](json::JsonMutVal value,Work&){value.get("case").get("whole_native_model_candidate").get("relations").at(14).set("label",text);});
        }
        reject("Angle6eba exact whole source binding",[](json::JsonMutVal value,Work& local){
            auto row=value.get("case");const auto source=row.get("source").as_str();local.spend(source.size()*8u+1024u);
            // Equal-length complete source with its own matching hash is still
            // not the approved original427 bytes. No renderer is consulted.
            std::string wrong(source);wrong.back()='x';row.set("source",wrong);row.set("source_sha256",digest(wrong));row.set("source_bytes",static_cast<std::int64_t>(wrong.size()));
        });
        for(const auto text:{"< owns","drives >","have 4 >","<\t>"}){Work local;EXPECT_TRUE(angle6eba_central_tokens(text,local));}
        // Strict existing nullable endpoint codec is tested directly, rather
        // than hiding its type/field errors behind supplement provenance.
        const auto model_json=class481_canonical(meaning,work);
        auto bad_codec=[&](std::string_view expected,auto change){
            Work local;local.spend(model_json.size()*16u+256u);json::JsonMutDoc altered;auto root=altered.raw_json(model_json);altered.set_root(root);change(root);
            const auto changed=altered.to_string();local.spend(changed.size()*4u+128u);const auto parsed=json::parse(changed);ASSERT_TRUE(parsed);bool rejected=false;
            try{static_cast<void>(class481_model(parsed->root(),local,true));}
            catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()))<<error.what();EXPECT_EQ(std::string_view(error.what()),expected);rejected=true;}EXPECT_TRUE(rejected);
        };
        bad_codec("Class endpoint text exact nullable profile",[](json::JsonMutVal value){value.get("relations").at(0).set("source_text",false);});
        bad_codec("Class endpoint text exact nullable profile",[](json::JsonMutVal value){value.get("relations").at(0).set("source_text","");});
        bad_codec("CLASS481 exact object fields",[](json::JsonMutVal value){static_cast<void>(value.get("relations").at(0).remove("target_text"));});
        Work zero;zero.left=0;bool resource=false;
        try{static_cast<void>(angle6eba_meaning(supplement.root(),original,zero));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource)<<"No source-schema rejection credit from zero Work";
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
} // namespace

