TEST(MermaidClassEndpoint29, OriginalSingleEndpointBoundarySourcesNowRequireCompleteGeometry){
    // These exact two inputs formerly lived in Class35's closed-profile list.
    // Keep their source bytes and require the newly supported whole semantics.
    constexpr std::array<std::array<std::string_view,4>,2> samples{{
        {{R"ENDPOINTSOURCE(classDiagram
class A
class B
A "1" --> B
)ENDPOINTSOURCE",R"ENDPOINTMODEL({"direction":"TB","entities":[{"headers":[["A"]],"id":"class:41","label":"A","owner":"","rows":[],"shape":"box"},{"headers":[["B"]],"id":"class:42","label":"B","owner":"","rows":[],"shape":"box"}],"family":"class","groups":[],"notes":[],"relations":[{"end":"arrow","label":"","order":0,"source":"class:41","source_text":"1","start":"none","stroke":"solid","target":"class:42","target_text":null}]})ENDPOINTMODEL","8d7cde322826417803941df2b3174b27a6f01cc655a7ea0e41a3e3d36ea4990e","591b08e915389d1423e0953e88e2154c465c46172b7b46060159ca5601754e1b"}},
        {{R"ENDPOINTSOURCE(classDiagram
class A
class B
A --> "1" B
)ENDPOINTSOURCE",R"ENDPOINTMODEL({"direction":"TB","entities":[{"headers":[["A"]],"id":"class:41","label":"A","owner":"","rows":[],"shape":"box"},{"headers":[["B"]],"id":"class:42","label":"B","owner":"","rows":[],"shape":"box"}],"family":"class","groups":[],"notes":[],"relations":[{"end":"arrow","label":"","order":0,"source":"class:41","source_text":null,"start":"none","stroke":"solid","target":"class:42","target_text":"1"}]})ENDPOINTMODEL","49d66c297acc87bc6883ef2d96acda905582fb9f00d68a85fb8ca9ed278e9d42","f23dd19ac56fb1443641717a869b579e00dedf4bff9dff409213678281ba360a"}},
    }};
    int matched=0,mutated=0;
    for(const auto& sample:samples){SCOPED_TRACE(std::string(sample[0]));try{
        Work work;const auto frames=class35_observe(sample[0],work);
        ASSERT_TRUE(frames.restored==frames.wide);
        for(const auto* frame:{&frames.wide,&frames.narrow,&frames.restored})ASSERT_TRUE(class481_sentinel(*frame,work));
        work.spend(sample[1].size()*3u+128u);const auto doc=json::parse(sample[1]);ASSERT_TRUE(doc);
        ASSERT_EQ(digest(sample[0]),sample[2]);ASSERT_EQ(digest(class481_canonical(doc->root(),work)),sample[3]);
        const auto model=class481_model(doc->root(),work,true);const auto allowance=work.left;
        const auto errors=class35_geometry(frames,model,allowance);ASSERT_TRUE(errors.empty())<<explain(errors);++matched;
        const auto changes=endpoint29_mutations(frames.wide,model,work);EXPECT_TRUE(changes.errors.empty())<<explain(changes.errors);
        if(changes.errors.empty())++mutated;
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}}
    EXPECT_EQ(matched,2);EXPECT_EQ(mutated,2);
}
