constexpr std::string_view kAnglePhysicalSourceGuardsSha="3c2f490121c7d79740022faa1118ecd2bbdadda9b9e4daa7d34c288a3dfe2c71";
void angle_physical_source_guards(bool positive) {
    Work setup;
    setup.spend(kAnglePhysicalSourceGuards.size()*3u+256u);
    class481_require(digest(kAnglePhysicalSourceGuards)==kAnglePhysicalSourceGuardsSha,"Angle physical exact authored controls");
    const auto authored=json::parse(kAnglePhysicalSourceGuards);
    ASSERT_TRUE(authored);
    const auto catalog=authored->root();
    ASSERT_EQ(catalog.get_string("schema"),"class_angle_physical_source_guards/v1");
    ASSERT_EQ(catalog.get("cases").size(),21u);
    const auto parent=endpoint29_document(setup);
    endpoint29_schema(parent.root(),setup);
    const auto supplement=angle6eba_document(setup);
    JsonVal original;
    std::size_t nulls=0;
    parent.root().get("cases").iter([&](JsonVal row){
        setup.spend();
        if(row.get("whole_native_model_candidate").is_null()) { ++nulls;original=row; }
    });
    ASSERT_EQ(nulls,1u);
    ASSERT_TRUE(original.valid());
    json::JsonMutDoc report;
    auto root=report.object(),records=root.make_arr();
    int total=0,observed=0,decoded=0,matched=0,closed=0,unmet=0,mutated=0,oracle_errors=0;
    catalog.get("cases").iter([&](JsonVal row){
        const auto ordinal=row.get_int("ordinal");
        if((ordinal<6)!=positive)return;
        ++total;
        SCOPED_TRACE(row.get_string("name"));
        Work work;
        work.spend(1024u);
        auto item=root.make_obj();
        item.set("name",row.get_string("name"));
        item.set("source_sha256",row.get_string("source_sha256"));
        std::vector<std::string> errors,observations;
        std::string phase="source",outcome="oracle_or_execution_error";
        bool good=false,done=false;
        try {
            const auto input=class481_text(row.get("source"),work,65536);
            work.spend(input.size()*8u+256u);
            class481_require(row.get("source_bytes").is_int()&&row.get_int("source_bytes")>=0&&static_cast<std::size_t>(row.get_int("source_bytes"))==input.size()&&digest(input)==row.get_string("source_sha256"),"Angle physical exact source bytes/hash");
            const std::string source(input);
            phase="public_observation_before_Model";
            const auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
            const auto ordinary_node=loom::ui::render_markdown(fenced(source,"text"));
            node->ComputeRequirement();ordinary_node->ComputeRequirement();
            const int height=std::min(1040,std::max(40,std::max(node->requirement().min_y,ordinary_node->requirement().min_y)+12));
            work.spend(static_cast<std::size_t>(height)*(3u*240u+2u*40u)*4u+256u);
            const auto wide=capture(node,240,height),ordinary=capture(ordinary_node,240,height),narrow=capture(node,40,height),small=capture(ordinary_node,40,height),restored=capture(node,240,height);
            ++observed;
            const bool fallback=wide==ordinary,narrow_fallback=narrow==small;
            item.set("wide_source_fallback",fallback);item.set("narrow_source_fallback",narrow_fallback);
            const bool same_restore=class481_same_grid(wide,restored,work);item.set("restored_identically",same_restore);
            if(!same_restore)observations.emplace_back("Angle physical same-Node restoration differs");
            const bool wide_sentinel=class481_sentinel(wide,work),narrow_sentinel=class481_sentinel(narrow,work);
            const bool restored_sentinel=same_restore?wide_sentinel:class481_sentinel(restored,work);
            for(const bool physical:{wide_sentinel,narrow_sentinel,restored_sentinel})if(!physical)observations.emplace_back("Angle physical following sentinel");
            work.spend(static_cast<std::size_t>(height)*(240u+40u+240u)*8u+256u);
            for(const auto& [name,grid]:std::array<std::pair<std::string_view,const Grid*>,3>{{{"wide_frame",&wide},{"narrow_frame",&narrow},{"restored_frame",&restored}}}) {
                auto frame=root.make_arr();
                for(int y=0;y<grid->height;++y)frame.append(root.make_str(grid->row(y)));
                item.add(name,frame);
            }
            item.set("frame_height",height);
            const auto wide_hash=class481_frame_hash(wide,work);item.set("wide_frame_sha256",wide_hash);
            item.set("narrow_frame_sha256",class481_frame_hash(narrow,work));
            item.set("restored_frame_sha256",same_restore?wide_hash:class481_frame_hash(restored,work));
            phase="complete_source_Model_binding";
            if(!positive) {
                class481_require(row.get("whole_native_model").is_null()&&row.get("whole_native_model_sha256").is_null()&&row.get_string("model_binding")=="none","Angle physical closed profiles have no invented drawing Model");
                // Bare CR may be valid after upstream normalization. These are
                // explicit closed native profiles, not syntax-invalid claims.
                if(!fallback||!narrow_fallback)errors.emplace_back("Angle closed profile did not preserve the complete source");
                if(errors.empty()&&observations.empty()){++closed;outcome="whole_source_preserved_closed_profile";}
                else outcome="source_preservation_or_observation_error";
            } else {
                JsonVal meaning;
                if(ordinal<4) {
                    class481_require(row.get_string("model_binding")=="independent_complete_AB","Angle physical independent tiny whole Model");
                    meaning=row.get("whole_native_model");
                    class481_require(digest(class481_canonical(meaning,work))==row.get_string("whole_native_model_sha256"),"Angle physical independent full Model digest");
                } else {
                    class481_require((ordinal==4||ordinal==5)&&row.get_string("model_binding")=="strict_angle6eba_supplement"&&row.get("whole_native_model").is_null(),"Angle physical whole6eba binding profile");
                    // The original supplement binder consumes every source,
                    // nullable endpoint, primary witness and complete Model.
                    meaning=angle6eba_meaning(supplement.root(),original,work);
                    const auto lf=original.get("source").as_str();
                    if(ordinal==4)class481_require(input==lf,"Angle physical original whole427 source");
                    else {
                        work.spend(lf.size()*6u+input.size()*4u+sizeof(std::string)+128u);
                        std::string crlf;crlf.reserve(lf.size()*2u);
                        for(const char ch:lf){if(ch=='\n')crlf+='\r';crlf+=ch;}
                        class481_require(input==crlf&&input.size()==446u,"Angle physical whole446 differs only by CRLF");
                    }
                }
                phase="complete_Model_decode";
                const auto model=class481_model(meaning,work,true);
                ++decoded;
                const auto allowance=work.left;
                item.set("post_decode_geometry_allowance",static_cast<std::int64_t>(allowance));
                phase="complete_geometry";
                if(fallback){++unmet;errors.emplace_back("Angle complete positive source remains unmet");outcome="source_positive_unmet";}
                else {
                    const auto found=validate_impl(wide,model,work);
                    class481_no_resource(found);errors.insert(errors.end(),found.begin(),found.end());
                    if(!narrow_fallback) {
                        Work small_work;small_work.left=allowance;
                        const auto found_small=validate_impl(narrow,model,small_work);
                        class481_no_resource(found_small);errors.insert(errors.end(),found_small.begin(),found_small.end());
                    }
                    good=errors.empty()&&observations.empty();
                    if(good) {
                        phase="schema_valid_complete_mutations";
                        // Existing mutation enumerator pays each Model/pixel
                        // copy and rejects resource errors as oracle failures.
                        const auto changes=endpoint29_mutations(wide,model,work);
                        errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());
                        class35_counts(root,item,changes);
                        done=changes.errors.empty();
                        if(done)++mutated;
                    }
                    if(good&&done&&errors.empty()){++matched;outcome="complete_geometry_and_mutations_match";}
                    else outcome="complete_geometry_or_observation_error";
                }
            }
        } catch(const std::exception& error) {
            ++oracle_errors;errors.emplace_back(phase+": "+error.what());outcome="oracle_or_resource_or_execution_error";
        }
        item.set("phase",phase);item.set("native_outcome",outcome);
        item.set("good_geometry_before_mutations",good);item.set("mutations_completed",done);
        class35_errors(root,item,errors,observations);records.append(item);
    });
    root.set("qualification","Six source-derived whole geometry positives and fifteen distinct closed native source profiles. Closed preservation is not drawing, CR validity or foreign API/ASCII equivalence credit. The source controls append to the current native suite; existing whole-source fixture assets and Models are unchanged.");
    root.set("source_controls_sha256",std::string(kAnglePhysicalSourceGuardsSha));
    root.set("parent_endpoint29_sha256",std::string(kEndpoint29Sha));root.set("whole6eba_supplement_sha256",std::string(kAngle6ebaSha));
    root.set("whole_sources",total);root.set("public_observations",observed);root.set("complete_Models_decoded",decoded);
    root.set("native_geometry_matches",matched);root.set("sources_with_mutations",mutated);root.set("source_positive_unmet",unmet);
    root.set("closed_source_profiles_preserved",closed);root.set("oracle_or_resource_errors",oracle_errors);
    root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    const auto filename=positive?"mermaid-class-angle-physical-positives.json":"mermaid-class-angle-physical-closed.json";
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/filename,std::ios::binary);
    ASSERT_TRUE(output&&(output<<report.to_string()<<'\n'));
#endif
    EXPECT_EQ(total,positive?6:15);EXPECT_EQ(observed,total);EXPECT_EQ(oracle_errors,0);
    EXPECT_EQ(decoded,positive?6:0);EXPECT_EQ(matched,positive?6:0);EXPECT_EQ(mutated,positive?6:0);
    EXPECT_EQ(closed,positive?0:15);EXPECT_EQ(unmet,0);
}
