TEST(MermaidClassEndpoint29, IndependentSingleRoleWholePapersRejectTheOppositeEndpoint){
    try{
        Work setup;
        constexpr std::size_t bytes=9658u;
        setup.spend(bytes*3u+256u);
        const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_native/class_endpoint_single_role_geodesic_papers.json";
        ASSERT_EQ(std::filesystem::file_size(path),bytes);
        const auto encoded=read(path);ASSERT_EQ(encoded.size(),bytes);ASSERT_EQ(digest(encoded),"c36fa167ae0aff68785ef656a4d1205ddc7a824449f0b38d9f74ee4ce8adff04");
        const auto doc=json::parse(encoded);ASSERT_TRUE(doc);ASSERT_EQ(doc->root().get("papers").size(),2u);
        int good=0,rejected=0;
        doc->root().get("papers").iter([&](JsonVal paper){SCOPED_TRACE(paper.get_string("name"));try{
            Work work;
            class481_require(digest(class481_text(paper.get("source"),work))==paper.get_string("source_sha256"),"Single endpoint whole paper source hash");
            const auto meaning=paper.get("whole_native_model");class481_require(digest(class481_canonical(meaning,work))==paper.get_string("whole_native_model_sha256"),"Single endpoint whole paper Model hash");
            const auto model=class481_model(meaning,work,true);
            const auto right=namespace45_grid(paper.get("independent_good"),work);
            if(!namespace45_good(right,model,work))return;
            ++good;
            const auto wrong=namespace45_grid(paper.get("same_Model_wrong_endpoint_bad"),work);
            const auto errors=validate_impl(wrong,model,work);class481_no_resource(errors);
            EXPECT_FALSE(errors.empty())<<"Single endpoint text at opposite real entity was accepted";
            if(!errors.empty())++rejected;
        }catch(const std::exception& error){ADD_FAILURE()<<error.what();}});
        EXPECT_EQ(good,2);EXPECT_EQ(rejected,2);
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
