json::JsonDoc envelope22_papers_document(Work& setup){
    setup.spend(kEnvelope22PapersBytes*3u+256u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kEnvelope22PapersFile;
    class481_require(std::filesystem::file_size(path)==kEnvelope22PapersBytes,"Envelope22 paper actual fixture stat");
    const auto bytes=read(path);class481_require(bytes.size()==kEnvelope22PapersBytes&&digest(bytes)==kEnvelope22PapersSha,"Envelope22 paper complete fixture hash");
    auto doc=json::parse(bytes);class481_require(doc.has_value(),"Envelope22 paper fixture parse");const auto root=doc->root();
    class481_keys(root,{"counterexamples","papers","qualification","records","schema","source_contract_sha256","stage1_fixture_sha256"},setup);
    class481_require(root.get_string("schema")=="class_envelope22_stage2_literal_papers/v1"&&root.get_string("source_contract_sha256")=="c33db3168e57851723a100ccb847137eac13dc813110ccd7e96303f479bc0356"&&root.get_string("stage1_fixture_sha256")=="566f49b94956b9685a12d3e021cd21b53f1996d2f7b3ed0cca7c8e15e33bb8fd","Envelope22 paper source protocol");
    class481_require(root.get("records").is_int()&&root.get_int("records")==16&&root.get("counterexamples").is_int()&&root.get_int("counterexamples")==106&&root.get("papers").is_arr()&&root.get("papers").size()==16,"Envelope22 complete paper denominator");return std::move(*doc);
}
std::string envelope22_papers_rows_hash(JsonVal rows,Work& work){
    class481_require(rows.is_arr()&&rows.size()==20,"Envelope22 paper physical row cardinality");
    // Every frozen row is <=48 single-cell glyphs of at most3 UTF-8 bytes.
    // Pay the complete concatenation bound before its first allocation.
    work.spend(20u*(48u*3u+1u)*8u+256u);std::string text;text.reserve(20u*(48u*3u+1u));
    rows.iter([&](JsonVal line){const auto value=class481_text(line,work,144);text+=value;text+='\n';});work.spend(text.size()*3u+64u);return digest(text);
}
Model envelope22_papers_bind(JsonVal paper,std::size_t index,Work& work,ClassPresentation* selected_presentation=nullptr){
    class481_require(index<kEnvelope22PaperPins.size(),"Envelope22 paper fixed index");const auto& pin=kEnvelope22PaperPins[index];
    // Source, small Model and source-witness bundle allocations only; do not
    // canonicalize the27,145-byte full paper through the old17,531 bound.
    work.spend(4096u*16u+512u);
    class481_keys(paper,{"chosen_rect_witnesses","complete_physical_source_witnesses","counterexamples","height","literal_rows","literal_rows_utf8_sha256","name","presentation","qualification","sentinel","source","source_sha256","source_utf8_bytes","whole_native_model","whole_native_model_sha256","width"},work);
    class481_require(paper.get_string("name")==pin.name,"Envelope22 fixed paper identity");const auto source=class481_text(paper.get("source"),work,512);work.spend(source.size()*4u+64u);
    class481_require(paper.get("source_utf8_bytes").is_int()&&paper.get_int("source_utf8_bytes")==static_cast<std::int64_t>(source.size())&&digest(source)==pin.source_sha&&paper.get_string("source_sha256")==pin.source_sha,"Envelope22 whole paper source binding");
    class481_require(paper.get("width").is_int()&&paper.get_int("width")==48&&paper.get("height").is_int()&&paper.get_int("height")==20,"Envelope22 fixed literal canvas types");
    const auto presentation=paper.get("presentation");class481_keys(presentation,{"authored_hide_empty_members_box","diagram_title","terminal_empty_default","title_role"},work);
    const auto hide=presentation.get("authored_hide_empty_members_box"),title=presentation.get("diagram_title");
    class481_require(hide.is_null()||hide.is_bool(),"Envelope22 paper authored hide type");class481_require(title.is_null()||(title.is_str()&&!title.as_str().empty()&&title.as_str().size()<=48),"Envelope22 paper optional title type");
    class481_require(presentation.get_string("terminal_empty_default")=="compact_independent_of_envelope"&&presentation.get_string("title_role")== (title.is_null()?"absent":"owned_prefix_row_then_complete_blank_separator"),"Envelope22 paper presentation protocol");
    const auto spans=paper.get("complete_physical_source_witnesses");class481_require(spans.is_arr()&&spans.size()>0&&spans.size()<=16,"Envelope22 complete source witness domain");std::size_t offset=0,line=0;
    spans.iter([&](JsonVal span){class481_keys(span,{"length_utf8_bytes","line","offset_utf8_bytes","sha256","text"},work);class481_require(span.get("offset_utf8_bytes").is_int()&&span.get_int("offset_utf8_bytes")==static_cast<std::int64_t>(offset)&&span.get("length_utf8_bytes").is_int()&&span.get_int("length_utf8_bytes")>0&&span.get("line").is_int()&&span.get_int("line")==static_cast<std::int64_t>(++line),"Envelope22 physical source witness typed order");const auto text=class481_text(span.get("text"),work,512);const auto length=static_cast<std::size_t>(span.get_int("length_utf8_bytes"));class481_require(offset<=source.size()&&length<=source.size()-offset&&length==text.size(),"Envelope22 physical source witness bounds");work.spend(length*4u+64u);class481_require(source.substr(offset,length)==text&&digest(text)==span.get_string("sha256"),"Envelope22 complete physical source bytes");offset+=length;});class481_require(offset==source.size(),"Envelope22 whole source witness coverage");
    const auto marker=paper.get("sentinel");class481_keys(marker,{"physical_ascii_cells","text","x","y"},work);class481_require(marker.get("physical_ascii_cells").is_bool()&&marker.get("physical_ascii_cells").as_bool()&&marker.get_string("text")=="AFTER_RELATIONS_SEMANTICS"&&marker.get("x").is_int()&&marker.get_int("x")==0&&marker.get("y").is_int()&&marker.get_int("y")==18,"Envelope22 literal sentinel protocol");
    const auto witnesses=paper.get("chosen_rect_witnesses");class481_require(witnesses.is_arr()&&witnesses.size()==paper.get("whole_native_model").get("entities").size(),"Envelope22 complete author Rect witness count");
    // Bind the complete reviewed witness/presentation objects, but never use
    // their coordinates to select a box, header, route or accepted result.
    json::JsonMutDoc bundle_doc;auto bundle=bundle_doc.object();for(const auto field:{"chosen_rect_witnesses","complete_physical_source_witnesses","presentation","sentinel","qualification"})bundle.add(field,bundle_doc.copy_val(paper.get(field)));bundle_doc.set_root(bundle);const auto encoded=bundle_doc.to_string();work.spend(encoded.size()*4u+64u);auto parsed_bundle=json::parse(encoded);class481_require(parsed_bundle.has_value(),"Envelope22 paper witness bundle parse");class481_require(digest(class481_canonical(parsed_bundle->root(),work))==pin.bundle_sha,"Envelope22 independent source/presentation/witness binding");
    auto model=class481_model(paper.get("whole_native_model"),work);class481_require(digest(class481_canonical(paper.get("whole_native_model"),work))==pin.model_sha&&paper.get_string("whole_native_model_sha256")==pin.model_sha,"Envelope22 unchanged complete paper Model binding");
    class481_require(envelope22_papers_rows_hash(paper.get("literal_rows"),work)==pin.frame_sha&&paper.get_string("literal_rows_utf8_sha256")==pin.frame_sha,"Envelope22 complete independent good frame binding");
    class481_require(paper.get("counterexamples").is_arr()&&paper.get("counterexamples").size()==pin.mutations,"Envelope22 complete counterexample denominator");
    if(selected_presentation){work.spend(16u);selected_presentation->title=title.is_null()?std::nullopt:std::optional<std::string_view>{title.as_str()};selected_presentation->hide_empty_members_box=hide.is_null()?std::nullopt:std::optional<bool>{hide.as_bool()};}
    return model;
}
Grid envelope22_papers_bad_grid(JsonVal bad,Work& work){
    // The existing literal Grid reader is reused. Only its three input fields
    // are copied, not the full source paper/counterexample collection.
    work.spend(4096u*16u+960u*(sizeof(std::string)+16u)+256u);json::JsonMutDoc doc;auto root=doc.object();root.set("width",48);root.set("height",20);root.add("literal_rows",doc.copy_val(bad.get("literal_rows")));doc.set_root(root);const auto text=doc.to_string();work.spend(text.size()*4u+64u);auto parsed=json::parse(text);class481_require(parsed.has_value(),"Envelope22 counterframe reader bridge parse");return namespace45_grid(parsed->root(),work);
}
void envelope22_papers_counter_bind(JsonVal bad,JsonVal paper,Work& work){
    class481_keys(bad,{"baseline_good_must_pass_first","cell_changes","expected_rejection_layer","literal_rows","literal_rows_utf8_sha256","name","obligation","resource_or_schema_failure_credit","row_removal","same_schema_valid_model_and_presentation"},work);
    for(const auto key:{"baseline_good_must_pass_first","same_schema_valid_model_and_presentation"})class481_require(bad.get(key).is_bool()&&bad.get(key).as_bool(),"Envelope22 counterexample complete-good prerequisite");class481_require(bad.get("resource_or_schema_failure_credit").is_bool()&&!bad.get("resource_or_schema_failure_credit").as_bool(),"Envelope22 counterexample excludes resource/schema credit");
    static_cast<void>(class481_text(bad.get("name"),work,96));static_cast<void>(class481_text(bad.get("obligation"),work,512));const auto layer=class481_text(bad.get("expected_rejection_layer"),work,64);class481_require(layer=="existing_complete_geometry"||layer=="future_same_assignment_compartments"||layer=="future_same_scene_title_prefix","Envelope22 counterexample declared layer");
    class481_require(bad.get("cell_changes").is_arr()&&(bad.get("row_removal").is_null()||bad.get("row_removal").is_obj()),"Envelope22 counterexample physical edit protocol");
    const auto hash=envelope22_papers_rows_hash(bad.get("literal_rows"),work);class481_require(hash==bad.get_string("literal_rows_utf8_sha256")&&hash!=paper.get_string("literal_rows_utf8_sha256"),"Envelope22 observable whole counterframe binding");
}
void envelope22_papers_no_schema_errors(const std::vector<std::string>& errors){
    for(const auto& error:errors)if(error.starts_with("Unknown ")||error.starts_with("Duplicate ")||error=="Transition/declaration order facts changed"||error.starts_with("Typed ER ")||error.starts_with("Inconsistent group/")||error=="Unlisted owner/member fact"||error=="Cyclic/too-deep group parent"||error.starts_with("Class presentation protocol"))throw std::runtime_error("Envelope22 schema/domain outcome is not geometry evidence: "+error);
}
