TEST(MermaidClassEnvelope22Stage2Presentation, OptionalPresentationMustAcceptEveryCompleteLiteralGoodPaper){
    Work setup;const auto facts=envelope22_papers_document(setup);setup.spend(4096u);std::size_t visited=0,bound=0,constructed=0,attempted=0,matched=0,unmet=0,source_errors=0,oracle_errors=0;json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    for(std::size_t n=0;n<16;++n){const auto paper=facts.root().get("papers").at(n);SCOPED_TRACE(paper.get_string("name"));Work work;work.spend(8192u);auto item=root.make_obj();item.set("name",paper.get_string("name"));item.set("source_sha256",paper.get_string("source_sha256"));++visited;std::string phase="source/schema",outcome="source_or_schema_error";std::vector<std::string> errors;
        try{work.spend(sizeof(ClassPresentation));ClassPresentation presentation;const auto model=envelope22_papers_bind(paper,n,work,&presentation);++bound;phase="literal_good";const auto grid=namespace45_grid(paper,work);++constructed;phase="optional_presentation_complete_geometry";++attempted;errors=validate_impl(grid,model,work,false,&presentation);class481_no_resource(errors);envelope22_papers_no_schema_errors(errors);
            if(errors.empty()){++matched;outcome="complete_good_matched_with_optional_Class_presentation";}else{++unmet;outcome="mandatory_good_unmet_with_optional_Class_presentation";}EXPECT_TRUE(errors.empty())<<explain(errors);
        }catch(const std::exception& error){errors.emplace_back(error.what());if(!class481_resource(error.what())&&(phase=="source/schema"||phase=="literal_good"||phase=="literal_bad"||(std::string_view(error.what()).starts_with("Envelope22 schema/domain")||std::string_view(error.what()).starts_with("Class presentation protocol"))))++source_errors;else ++oracle_errors;ADD_FAILURE()<<phase<<": "<<error.what();}
        item.set("phase",phase);item.set("outcome",outcome);item.set("source_bound",phase!="source/schema");item.set("presentation_witness_used_for_acceptance",false);item.set("active_validation_path","same_assignment_optional_Class_presentation");item.set("errors",explain(errors));item.set("work_remaining",static_cast<std::int64_t>(work.left));records.append(item);
    }
    // Typed parsed controls do not count as pixel adversaries. Construction,
    // full-paper mutable copy and parse all pay before the same binding Work.
    auto typed_reject=[&](const std::function<void(json::JsonMutVal)>& edit,std::string_view expected){Work work;work.spend(27145u*16u+4096u);json::JsonMutDoc mutated;auto row=mutated.copy_val(facts.root().get("papers").at(0));mutated.set_root(row);edit(row);const auto text=mutated.to_string();work.spend(text.size()*4u+64u);auto parsed=json::parse(text);ASSERT_TRUE(parsed);bool rejected=false;
        try{static_cast<void>(envelope22_papers_bind(parsed->root(),0,work));}catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()))<<error.what();EXPECT_EQ(std::string_view(error.what()),expected);rejected=true;}EXPECT_TRUE(rejected);
    };
    typed_reject([](auto row){row.get("presentation").set("authored_hide_empty_members_box","false");},"Envelope22 paper authored hide type");
    typed_reject([](auto row){row.set("width",false);},"Envelope22 fixed literal canvas types");
    typed_reject([](auto row){row.set("source","classDiagram\nclass X\n");},"Envelope22 whole paper source binding");
    {Work preparation;const auto first=facts.root().get("papers").at(0);preparation.spend(sizeof(ClassPresentation));ClassPresentation presentation;const auto model=envelope22_papers_bind(first,0,preparation,&presentation);const auto grid=namespace45_grid(first,preparation);Work zero;zero.left=0;bool resource=false;
        try{static_cast<void>(validate_impl(grid,model,zero,false,&presentation));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource)<<"Zero-work geometry failure cannot be semantic evidence";
    }
    EXPECT_EQ(visited,16u);EXPECT_EQ(bound,16u);EXPECT_EQ(constructed,16u);EXPECT_EQ(attempted,16u);EXPECT_EQ(matched,16u);EXPECT_EQ(unmet,0u);EXPECT_EQ(source_errors,0u);EXPECT_EQ(oracle_errors,0u);
    root.set("qualification","All16 complete goods mandatory through the source-bound optional Class presentation path. Header/compartment checks reuse real matching alternatives; title cells are owned in the same complete scene. No crop, expected-Rect assignment or producer change. Original115 first-red remains frozen.");root.set("fixture_sha256",kEnvelope22PapersSha);root.set("papers",16);root.set("source_bound",static_cast<int>(bound));root.set("literal_goods_constructed",static_cast<int>(constructed));root.set("geometry_attempted",static_cast<int>(attempted));root.set("complete_good_matches",static_cast<int>(matched));root.set("mandatory_good_unmet",static_cast<int>(unmet));root.set("source_or_schema_errors",static_cast<int>(source_errors));root.set("oracle_or_resource_errors",static_cast<int>(oracle_errors));root.set("whole22_admitted",0);root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-envelope22-stage2-optional-presentation-goods.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'));
#endif
}
TEST(MermaidClassEnvelope22Stage2Presentation, EveryPairedPixelAdversaryRequiresItsCompleteGoodFirst){
    Work setup;const auto facts=envelope22_papers_document(setup);setup.spend(4096u);std::size_t visited=0,baselines_good=0,declared=0,attempted=0,executed=0,rejected=0,accepted=0,skipped=0,source_errors=0,oracle_errors=0;json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    for(std::size_t n=0;n<16;++n){const auto paper=facts.root().get("papers").at(n);SCOPED_TRACE(paper.get_string("name"));++visited;bool good=false;std::vector<std::string> baseline_errors;Work baseline;std::string phase="source/schema";
        try{baseline.spend(sizeof(ClassPresentation));ClassPresentation presentation;const auto model=envelope22_papers_bind(paper,n,baseline,&presentation);phase="literal_good";const auto grid=namespace45_grid(paper,baseline);phase="good_geometry";baseline_errors=validate_impl(grid,model,baseline,false,&presentation);class481_no_resource(baseline_errors);envelope22_papers_no_schema_errors(baseline_errors);good=baseline_errors.empty();if(good)++baselines_good;
        }catch(const std::exception& error){baseline_errors.emplace_back(error.what());if(!class481_resource(error.what())&&(phase=="source/schema"||phase=="literal_good"||phase=="literal_bad"||(std::string_view(error.what()).starts_with("Envelope22 schema/domain")||std::string_view(error.what()).starts_with("Class presentation protocol"))))++source_errors;else ++oracle_errors;ADD_FAILURE()<<phase<<": "<<error.what();}
        EXPECT_TRUE(good)<<explain(baseline_errors);
        for(std::size_t k=0;k<paper.get("counterexamples").size();++k){const auto bad=paper.get("counterexamples").at(k);++declared;Work work;work.spend(8192u);auto item=root.make_obj();item.set("paper",paper.get_string("name"));item.set("name",bad.get_string("name"));item.set("expected_rejection_layer",bad.get_string("expected_rejection_layer"));item.set("complete_good_passed",good);std::vector<std::string> errors;std::string outcome="skipped_mandatory_good_unmet";item.set("geometry_attempted",false);item.set("geometry_completed",false);
            if(!good){++skipped;item.set("geometry_executed",false);item.set("semantic_rejection_credited",false);}
            else{phase="source/schema";
                try{work.spend(sizeof(ClassPresentation));ClassPresentation presentation;const auto expected=envelope22_papers_bind(paper,n,work,&presentation);envelope22_papers_counter_bind(bad,paper,work);phase="literal_bad";const auto grid=envelope22_papers_bad_grid(bad,work);phase="bad_geometry";++attempted;item.set("geometry_attempted",true);errors=validate_impl(grid,expected,work,false,&presentation);class481_no_resource(errors);envelope22_papers_no_schema_errors(errors);++executed;item.set("geometry_completed",true);
                    if(errors.empty()){++accepted;outcome="observable_pixel_adversary_accepted_with_optional_Class_presentation";}else{++rejected;outcome="schema_valid_pixel_adversary_rejected";}EXPECT_FALSE(errors.empty())<<"Optional Class presentation accepted "<<bad.get_string("name");item.set("geometry_executed",true);item.set("semantic_rejection_credited",!errors.empty());
                }catch(const std::exception& error){errors.emplace_back(error.what());if(!class481_resource(error.what())&&(phase=="source/schema"||phase=="literal_good"||phase=="literal_bad"||(std::string_view(error.what()).starts_with("Envelope22 schema/domain")||std::string_view(error.what()).starts_with("Class presentation protocol"))))++source_errors;else ++oracle_errors;outcome="source_schema_or_resource_error_no_credit";item.set("geometry_executed",phase=="bad_geometry");item.set("semantic_rejection_credited",false);ADD_FAILURE()<<phase<<": "<<error.what();}
            }
            item.set("outcome",outcome);item.set("errors",explain(errors));item.set("work_remaining",static_cast<std::int64_t>(work.left));records.append(item);
        }
    }
    EXPECT_EQ(visited,16u);EXPECT_EQ(baselines_good,16u);EXPECT_EQ(declared,106u);EXPECT_EQ(attempted,106u);EXPECT_EQ(executed,106u);EXPECT_EQ(rejected,106u);EXPECT_EQ(accepted,0u);EXPECT_EQ(skipped,0u);EXPECT_EQ(source_errors,0u);EXPECT_EQ(oracle_errors,0u);
    root.set("qualification","All106 immutable complete pixel pairs retained through source-bound optional Class presentation. Each uses the identical schema-valid Model/presentation, with source/Model rebind and fresh independent assertion Work paid before construction. A failing good skips its pairs without rejection credit; no failure is retried/reset. Original115 results remain frozen.");root.set("fixture_sha256",kEnvelope22PapersSha);root.set("papers",16);root.set("complete_good_baselines",static_cast<int>(baselines_good));root.set("declared_pixel_adversaries",static_cast<int>(declared));root.set("geometry_executed",static_cast<int>(attempted));root.set("geometry_completed",static_cast<int>(executed));root.set("semantic_rejections",static_cast<int>(rejected));root.set("accepted_pixel_adversaries",static_cast<int>(accepted));root.set("skipped_good_unmet",static_cast<int>(skipped));root.set("source_or_schema_errors",static_cast<int>(source_errors));root.set("oracle_or_resource_errors",static_cast<int>(oracle_errors));root.set("whole22_admitted",0);root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-envelope22-stage2-optional-presentation-pixel-adversaries.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'));
#endif
}

// Extra source-preserving physical-junction controls are separate from the
// immutable16 goods/106 bads. Each complete good passes before its own mutation.
TEST(MermaidClassEnvelope22Stage2Presentation, EachSemanticDividerRequiresBothPhysicalInwardArms){
    Work setup;const auto facts=envelope22_papers_document(setup);
    const auto paper=facts.root().get("papers").at(3);
    class481_require(paper.get_string("name")=="empty_false","Envelope22 divider-junction source paper binding");
    std::size_t goods=0,mutations=0,rejections=0;
    for(const Point point:{Point{1,3},Point{11,3}}){
        SCOPED_TRACE(point.x==1?"missing left inward R arm":"missing right inward L arm");
        Work work;work.spend(8192u+sizeof(ClassPresentation));ClassPresentation presentation;
        const auto model=envelope22_papers_bind(paper,3,work,&presentation);
        const auto good=namespace45_grid(paper,work);
        const auto baseline=validate_impl(good,model,work,false,&presentation);
        class481_no_resource(baseline);envelope22_papers_no_schema_errors(baseline);
        ASSERT_TRUE(baseline.empty())<<explain(baseline);++goods;
        // Prepay the complete physical Grid vector/string copy and the one new
        // UTF-8 glyph before constructing either. No assertion Work is reset.
        work.spend(good.cells.size()*(2u*sizeof(std::string)+16u)+128u);
        for(const auto& cell:good.cells)work.spend(cell.size()*2u+1u);
        work.spend(16u);
        auto bad=good;
        ASSERT_EQ(bad.at(point),point.x==1?"├":"┤");
        bad.put(point,"│");++mutations;
        const auto errors=validate_impl(bad,model,work,false,&presentation);
        class481_no_resource(errors);envelope22_papers_no_schema_errors(errors);
        EXPECT_FALSE(errors.empty())<<"A detached semantic divider is not complete";
        if(!errors.empty())++rejections;
    }
    EXPECT_EQ(goods,2u);EXPECT_EQ(mutations,2u);EXPECT_EQ(rejections,2u);
}

