TEST(MermaidRelationsBudgetAlgorithm, TextStartCandidatesAndExactRestoreKeepPhysicalPredicates){
    auto grid=mock({"ab aba a", "a b ab", "ab", "b"});
    grid.put({4,2},"é");grid.put({6,2},"猫");grid.put({7,2},"");
    for(const std::string_view text:{"a","ab","aba","b","é","猫","a\nb","absent"}){
        SCOPED_TRACE(text);RelationTextStarts starts;
        for(int y=0;y<grid.height;++y)for(int x=0;x<grid.width;++x){const auto cell=grid.at({x,y});if(!cell.empty())starts[static_cast<unsigned char>(cell.front())].push_back({x,y});}
        Work original,indexed;EXPECT_EQ(occurrences(grid,text,original),occurrences(grid,text,indexed,&starts));
        Work original_blocks,indexed_blocks;const auto expected=label_blocks(grid,text,original_blocks),actual=label_blocks(grid,text,indexed_blocks,&starts);
        ASSERT_EQ(actual.size(),expected.size());
        for(std::size_t n=0;n<actual.size();++n){EXPECT_EQ(actual[n].text,expected[n].text);EXPECT_EQ(actual[n].cells,expected[n].cells);EXPECT_EQ(actual[n].box.l,expected[n].box.l);EXPECT_EQ(actual[n].box.t,expected[n].box.t);EXPECT_EQ(actual[n].box.r,expected[n].box.r);EXPECT_EQ(actual[n].box.b,expected[n].box.b);}
    }
    Work empty_original,empty_indexed;const RelationTextStarts no_starts;
    EXPECT_EQ(occurrences(grid,"",empty_original),occurrences(grid,"",empty_indexed,&no_starts));
    Work absent;EXPECT_TRUE(occurrences(grid,"ab",absent,&no_starts).empty());
    RelationTextStarts one_start;one_start[static_cast<unsigned char>('a')].push_back({0,0});Work exhausted;exhausted.left=0;EXPECT_THROW(static_cast<void>(occurrences(grid,"ab",exhausted,&one_start)),std::runtime_error);

    const auto paper=mock({"AFTER_RELATIONS_SEMANTICS", " "});const auto restored=paper;
    Work equality;EXPECT_TRUE(class481_same_grid(paper,restored,equality));
    EXPECT_LT(equality.left,8000000u);
    Work physical;EXPECT_TRUE(class481_sentinel(paper,physical));EXPECT_TRUE(class481_sentinel(restored,physical));
    Work hashing;const auto wide_hash=class481_frame_hash(paper,hashing);EXPECT_EQ(wide_hash,class481_frame_hash(restored,hashing));
    auto changed=restored;changed.put({0,0},"X");Work changed_work;
    EXPECT_FALSE(class481_same_grid(paper,changed,changed_work));EXPECT_FALSE(class481_sentinel(changed,changed_work));EXPECT_NE(wide_hash,class481_frame_hash(changed,changed_work));
    auto packed=restored;for(int x=0;x<packed.width;++x)packed.put({x,0}," ");packed.put({0,0},"AFTER_RELATIONS_SEMANTICS");Work packed_work;
    EXPECT_EQ(trim(paper.row(0)),trim(packed.row(0))); // Joined trimmed text is insufficient.
    EXPECT_FALSE(class481_same_grid(paper,packed,packed_work));EXPECT_FALSE(class481_sentinel(packed,packed_work));EXPECT_NE(wide_hash,class481_frame_hash(packed,packed_work));
    auto dimensions=restored;dimensions.width=1;Work dimension_work;EXPECT_FALSE(class481_same_grid(paper,dimensions,dimension_work));
    Work zero;zero.left=0;EXPECT_THROW(static_cast<void>(class481_same_grid(paper,restored,zero)),std::runtime_error);
}
