// The body checker and metadata binding remain the existing owners. This helper
// only targets one uniquely matched real card after complete good geometry.
std::optional<Rect> envelope22_stage3_card(const Grid& grid,const Model& model,const ClassPresentation& presentation,Work& work){
    class481_require(!model.entities.empty(),"Envelope22 pixel target requires a complete entity");
    work.spend(128u*(4u*sizeof(Rect)+32u)+sizeof(std::optional<Rect>)+128u);
    const auto frames=outlines(grid,work);const auto& entity=model.entities.front();
    std::optional<Rect> selected;std::size_t matches=0;
    for(const auto& frame:frames){
        work.spend();if(frame.shape!="box")continue;
        const auto height=static_cast<std::size_t>(frame.b-frame.t-1),width=static_cast<std::size_t>(frame.r-frame.l-1);
        work.spend(height*(4u*sizeof(std::string)+8u*sizeof(int)+32u)+width*height*8u+128u);
        for(int y=frame.t+1;y<frame.b;++y)for(int x=frame.l+1;x<frame.r;++x){work.spend();work.spend(grid.at({x,y}).size()*4u);}
        const auto body=content(grid,frame,work);
        // Prepay temporary token vectors before the existing content matcher,
        // including its physical blank-header branch. Matching stays solely
        // in the existing source-backed content predicates below.
        std::size_t bytes=0,alternatives=0;
        for(const auto& text:body.text){work.spend();bytes+=text.size();}
        for(const auto& row:entity.rows){work.spend();alternatives=std::max(alternatives,row.alternatives.size());for(const auto& text:row.alternatives){work.spend();bytes+=text.size();}}
        const auto factor=(alternatives+1u)*(entity.headers.size()+1u)*(4u*sizeof(std::string)+16u);
        if(bytes>work.left/factor)throw std::runtime_error("Envelope22 content recheck work exhausted");
        work.spend(bytes*factor+256u);
        const bool found=class_complete_content(grid,frame,entity,work,&body,&presentation);
        if(found){++matches;selected=frame;}
    }
    return matches==1?selected:std::nullopt;
}

// A single owned card row changes. Stage every replacement before editing;
// swap transfers the original string objects without copying the whole Grid.
// The same complete mutable Grid is restored on every exit, including an
// exhausted validator or a throwing finish/record operation.
struct Envelope22Stage3RowPatch {
    Grid& grid;std::size_t begin=0;std::vector<std::string> saved;
    Envelope22Stage3RowPatch(Grid& target,const Rect& box,int row,bool erase,Work& work):grid(target){
        work.spend(sizeof(Envelope22Stage3RowPatch)+128u);
        class481_require(box.l>=0&&box.l<grid.width&&box.r>=0&&box.r<grid.width&&box.r>box.l&&box.r-box.l>=2&&row>box.t&&row<box.b&&grid.has({box.l,row})&&grid.has({box.r,row}),"Envelope22 divider patch row domain");
        const auto count=static_cast<std::size_t>(box.r-box.l+1);begin=static_cast<std::size_t>(row)*static_cast<std::size_t>(grid.width)+static_cast<std::size_t>(box.l);
        // One reserved string vector, <=3-byte replacements, all glyph probes,
        // construction/destruction and both noexcept swap traversals. Existing
        // source cell payload reads are charged before any Grid cell changes.
        work.spend(count*(2u*sizeof(std::string)+96u)+256u);saved.reserve(count);
        for(int x=box.l;x<=box.r;++x){
            const auto cell=grid.at({x,row});work.spend(cell.size()*2u+16u);
            std::string_view value;
            if(x==box.l){const bool outward=(glyph(cell).bits&L)!=0;value=erase?(outward?"┤":"│"):(outward?"┼":"├");}
            else if(x==box.r){const bool outward=(glyph(cell).bits&R)!=0;value=erase?(outward?"├":"│"):(outward?"┼":"┤");}
            else{if(!erase)class481_require(cell==" ","Envelope22 new-divider target must be an actual full blank row");value=erase?" ":"─";}
            saved.emplace_back(value);
        }
        // No allocating, charging, bounds-checked or otherwise throwing
        // operation follows the first swap inside this constructor.
        for(std::size_t n=0;n<saved.size();++n)grid.cells[begin+n].swap(saved[n]);
    }
    ~Envelope22Stage3RowPatch()noexcept{for(std::size_t n=0;n<saved.size();++n)grid.cells[begin+n].swap(saved[n]);}
    Envelope22Stage3RowPatch(const Envelope22Stage3RowPatch&)=delete;
    Envelope22Stage3RowPatch& operator=(const Envelope22Stage3RowPatch&)=delete;
};
Class481Mutations envelope22_stage3_presentation_mutations(Grid& good,const Model& model,const ClassPresentation& presentation,std::size_t allowance,Work& enumeration,const ClassCardWitness* verified_target=nullptr){
    enumeration.spend(4096u);Class481Mutations out;
    auto finish=[&](std::string_view kind,const std::vector<std::string>& errors){
        class481_no_resource(errors);envelope22_papers_no_schema_errors(errors);
        enumeration.spend(kind.size()*4u+512u);++out.executed[std::string(kind)];
        if(errors.empty())out.errors.emplace_back("Accepted Envelope22 observable presentation adversary: "+std::string(kind));
    };
    {
        Work work{allowance};work.spend(sizeof(ClassPresentation)+64u);auto wrong=presentation;
        wrong.title=wrong.title==std::optional<std::string_view>{"Different_Title"}?"Other_Title":"Different_Title";
        finish("exact_title_presence_or_value",validate_impl(good,model,work,false,&wrong));
    }
    enumeration.spend(model.entities.size()+1u);
    const bool has_empty=std::ranges::any_of(model.entities,[](const Entity& entity){return entity.rows.empty();});
    if(has_empty){
        Work work{allowance};work.spend(sizeof(ClassPresentation)+model.entities.size()+64u);auto wrong=presentation;
        wrong.hide_empty_members_box=!presentation.hide_empty_members_box.value_or(true);
        finish("visible_empty_compartment_setting",validate_impl(good,model,work,false,&wrong));
    }else{enumeration.spend(256u);++out.skipped["hide_has_no_completely_empty_card_native_equivalence"];}
    if(verified_target){
        Work work{allowance};work.spend(sizeof(ClassCardWitness)+sizeof(Rect)+128u);
        class481_require(verified_target->grid==&good&&verified_target->model==&model&&verified_target->presentation==&presentation&&verified_target->box.has_value(),"Class card witness exact live scene identity");
        const auto& box=*verified_target->box;const bool erase=verified_target->separator.has_value();const int row=erase?*verified_target->separator:box.b-1;
        const Envelope22Stage3RowPatch patch(good,box,row,erase,work);
        finish(erase?"complete_owned_divider_erasure":"unauthored_complete_divider_insertion",validate_impl(good,model,work,false,&presentation));
    }else{
        Work work{allowance};work.spend(sizeof(Rect)+sizeof(Content)+128u);
        const auto selected=envelope22_stage3_card(good,model,presentation,work);
        class481_require(selected.has_value(),"Envelope22 presentation pixel target requires unique complete card match");
        const auto& box=*selected;
        const auto height=static_cast<std::size_t>(box.b-box.t-1),width=static_cast<std::size_t>(box.r-box.l-1);
        work.spend(height*(4u*sizeof(std::string)+8u*sizeof(int)+32u)+width*height*8u+128u);
        for(int y=box.t+1;y<box.b;++y)for(int x=box.l+1;x<box.r;++x){work.spend();work.spend(good.at({x,y}).size()*4u);}
        const auto body=content(good,box,work);
        const bool erase=!body.separators.empty();const int row=erase?body.separators.front():box.b-1;
        const Envelope22Stage3RowPatch patch(good,box,row,erase,work);
        finish(erase?"complete_owned_divider_erasure":"unauthored_complete_divider_insertion",validate_impl(good,model,work,false,&presentation));
    }
    class481_require(out.executed["exact_title_presence_or_value"]==1&&out.executed["visible_empty_compartment_setting"]==(has_empty?1:0)&&out.executed["complete_owned_divider_erasure"]+out.executed["unauthored_complete_divider_insertion"]==1,"Envelope22 mandatory observable presentation adversaries completed");
    return out;
}
void envelope22_stage3_ordinary_frames(const Class35Frames& frames,json::JsonMutVal root,json::JsonMutVal item,Work& work){
    for(const auto& [name,grid]:std::array<std::pair<std::string_view,const Grid*>,2>{{{"ordinary_frame",&frames.ordinary},{"ordinary_narrow_frame",&frames.small}}}){
        work.spend(grid->cells.size()*8u+static_cast<std::size_t>(grid->height)*16u+128u);
        for(const auto& cell:grid->cells){work.spend();work.spend(cell.size()*4u);}
        auto rows=root.make_arr();for(int y=0;y<grid->height;++y)rows.append(root.make_str(grid->row(y)));item.add(name,rows);
    }
    item.set("ordinary_frame_sha256",class481_frame_hash(frames.ordinary,work));
    item.set("ordinary_narrow_frame_sha256",class481_frame_hash(frames.small,work));
}
