TEST(MermaidState85SourceFirst, CompleteSourcesPrimaryFieldsAndReviewedCandidateModelsRemainBound){
    Work setup;const auto document=state85_document(setup);const auto root=document.root();const auto originals=state85_originals(root);
    json::JsonMutDoc report;auto output=report.object(),records=output.make_arr();int models=0,positive_pending=0,original_error=0,old_records=0,old_models=0,choice_policy=0,errors=0;
    for(std::size_t n=0;n<85;++n){
        Work work;work.spend(4096u);const auto binding=root.get("cases").at(n);SCOPED_TRACE(binding.get_string("id"));auto item=output.make_obj();item.set("id",binding.get_string("id"));item.set("inventory_ordinal",static_cast<std::int64_t>(n));
        try{
            const auto row=state85_bind(root,n,originals,work);state85_field_integrity(root,n,work);const auto meaning=row.get("whole_native_model_candidate");
            if(!meaning.is_null()){
                static_cast<void>(state85_model(meaning,work));++models;
                bool hidden=false;meaning.get("entities").iter([&](JsonVal entity){work.spend();hidden|=entity.get_string("shape")=="choice"&&entity.get_string("label").empty();});
                class481_require(hidden==binding.get("choice_display_policy_pending").as_bool(),"State85 hidden choice policy is source-property bound");choice_policy+=hidden;
            }else if(binding.get_string("disposition")=="source_positive_profile_pending")++positive_pending;
            else{class481_require(binding.get_string("disposition")=="retained_original_error_source_correction","State85 explicit null disposition");++original_error;}
            const auto old=root.get("inventory").get("cases").at(n).get("existing_first62_native_Model");
            if(!old.is_null()){
                ++old_records;if(old.get_string("expected")=="drawing"){
                    class481_require(meaning.is_obj(),"State85 old drawing Model cannot become null");for(const auto key:{"family","direction","entities","relations","groups","notes"})class481_require(er_present_same_json(old.get(key),meaning.get(key),work),"State85 existing27 whole Model fields remain exact");++old_models;
                }else class481_require(old.get_string("expected")=="source"&&meaning.is_null()&&binding.get_string("disposition")=="retained_original_error_source_correction","State85 original error/source correction preserved");
            }
            item.set("complete_binding_and_typed_Model",true);
        }catch(const std::exception& error){++errors;ADD_FAILURE()<<error.what();item.set("complete_binding_and_typed_Model",false);item.set("error",error.what());}
        records.append(item);
    }
    // Specific typed guards bypass no source authority: they test only the
    // private codec against a separately paid parsed copy of a bound full Model.
    Work encode;const auto bytes=class481_canonical(root.get("source40").get("cases").at(0).get("whole_native_model_candidate"),encode);
    auto reject=[&](std::string_view expected,auto change){
        Work work;work.spend(bytes.size()*16u+512u);json::JsonMutDoc changed;auto value=changed.raw_json(bytes);changed.set_root(value);change(value);const auto text=changed.to_string();work.spend(text.size()*4u+128u);auto parsed=json::parse(text);ASSERT_TRUE(parsed);bool rejected=false;
        try{static_cast<void>(state85_model(parsed->root(),work));}catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()));EXPECT_EQ(std::string_view(error.what()),expected);EXPECT_GT(work.left,0u);rejected=true;}EXPECT_TRUE(rejected);
    };
    reject("State85 family",[](auto value){value.set("family","class");});
    reject("CLASS481 exact bounded text type",[](auto value){value.set("direction","UNKNOWN");});
    reject("State85 direction enum",[](auto value){value.set("direction","XX");});
    reject("State85 shape enum",[](auto value){value.get("entities").at(0).set("shape","box");});
    reject("CLASS481 exact object fields",[](auto value){value.set("unknown_state_field",1);});
    const auto paper=mock({"╭───╮","│ A │","╰───╯","AFTER_RELATIONS_SEMANTICS"});Model literal;literal.family="state";literal.entities={box_entity("A","A")};literal.entities.front().shape="rounded";
    Work good;ASSERT_TRUE(validate_impl(paper,literal,good).empty());Work zero;zero.left=0;bool exhausted=false;
    try{static_cast<void>(validate_impl(paper,literal,zero));}catch(const std::runtime_error& error){EXPECT_EQ(std::string_view(error.what()),"Relation oracle work exhausted");exhausted=true;}EXPECT_TRUE(exhausted);
    output.set("qualification","Source integrity only; all complete original dictionaries/functions/configuration/metadata remain retained.77 candidate Models are not77 native passes;7 positive profile gaps, hidden-choice family policy and1 original malformed/error API policy remain mandatory.");
    output.set("facts_sha256",std::string(kState85Sha));output.set("source_applications",85);output.set("candidate_Models_decoded",models);output.set("positive_profile_nulls",positive_pending);output.set("retained_original_error_null",original_error);output.set("hidden_choice_policy_pending",choice_policy);output.set("old28_records_preserved",old_records);output.set("old27_Models_exact",old_models);output.set("source_integrity_errors",errors);output.set("setup_work_remaining",static_cast<std::int64_t>(setup.left));output.add("cases",records);report.set_root(output);state85_write("mermaid-state85-source-integrity.json",report);
    EXPECT_EQ(models,77);EXPECT_EQ(positive_pending,7);EXPECT_EQ(original_error,1);EXPECT_EQ(choice_policy,1);EXPECT_EQ(old_records,28);EXPECT_EQ(old_models,27);EXPECT_EQ(errors,0);
}
TEST(MermaidCapabilityReport, State85) {
    Work setup;const auto document=state85_document(setup);const auto root=document.root();const auto originals=state85_originals(root);
    json::JsonMutDoc report;auto output=report.object(),records=output.make_arr();
    struct IdGap { std::string id; std::string outcome; };
    std::vector<IdGap> mandatory_gaps;
    int observed=0,decoded=0,matched=0,mutated=0,positive_pending=0,original_policy=0,choice_policy=0,whole_source_retained=0,fallbacks=0,oracle_errors=0,geometry_errors=0,observation_errors=0;
    for(std::size_t n=0;n<85;++n){
        Work work;work.spend(4096u);const auto binding=root.get("cases").at(n);const auto inventory=root.get("inventory").get("cases").at(n);SCOPED_TRACE(binding.get_string("id"));auto item=output.make_obj();item.set("id",binding.get_string("id"));item.set("source_sha256",binding.get_string("input_sha256"));item.set("inventory_ordinal",static_cast<std::int64_t>(n));item.set("source_fact_sha256",std::string(kState85Sha));
        std::vector<std::string> errors,observations;std::string phase="source_before_capture",outcome="execution_error";bool model_decoded=false,good=false,mutations_done=false,complete=false;
        try{
            const auto input=class481_text(inventory.get("source"),work);work.spend(input.size()*4u+128u);item.set("complete_source",std::string(input));
            phase="public_capture_before_Model_decode";const auto frames=class35_observe(input,work);++observed;
            // Complete five captures and all three retained frame grids precede
            // the per-case source/primary binding and strict Model decode.
            observations=class35_observations(frames,output,item,work);fallbacks+=frames.wide==frames.ordinary;
            phase="complete_source_and_primary_binding";const auto row=state85_bind(root,n,originals,work);const auto meaning=row.get("whole_native_model_candidate");
            const auto semantic=class481_canonical(row.get("complete_source_state_semantics"),work);work.spend(semantic.size()*4u+128u);item.set("source_state_semantics_json",semantic);
            item.set("source_authority_root",binding.get_string("authority_root"));item.set("source_authority_ordinal",binding.get_int("authority_ordinal"));if(binding.get("native_Model_sha256").is_null())item.add("complete_Model_sha256",item.make_null());else item.set("complete_Model_sha256",binding.get_string("native_Model_sha256"));
            if(meaning.is_null()){
                item.set("whole_native_Model_json","null");const auto disposition=binding.get_string("disposition");
                if(disposition=="source_positive_profile_pending"){
                    ++positive_pending;outcome="mandatory_positive_source_profile_unmet";errors.emplace_back("State85 complete positive profile remains mandatory; fallback or unmodeled drawing is not geometry credit");
                }else{
                    class481_require(disposition=="retained_original_error_source_correction","State85 exact original error/source disposition");++original_policy;
                    const bool preserved=frames.wide==frames.ordinary&&frames.narrow==frames.small&&frames.restored==frames.wide;
                    item.set("whole_source_preservation_met",preserved);whole_source_retained+=preserved;
                    if(!preserved)errors.emplace_back("State85 retained malformed/error source correction did not preserve the complete source");
                    outcome="original_malformed_error_API_policy_pending";errors.emplace_back("State85 original returned-string/error API predicate is pending; whole source preservation does not prove its error policy");
                }
            }else{
                phase="strict_State_Model_decode";const auto model=state85_model(meaning,work);model_decoded=true;++decoded;const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*4u+128u);item.set("whole_native_Model_json",encoded);
                bool hidden_choice=false;for(const auto& entity:model.entities){work.spend();hidden_choice|=entity.shape=="choice"&&entity.label.empty();}
                class481_require(hidden_choice==binding.get("choice_display_policy_pending").as_bool(),"State85 complete choice policy binding");choice_policy+=hidden_choice;item.set("choice_display_policy_pending",hidden_choice);
                const auto allowance=work.left;item.set("post_prepare_geometry_allowance",static_cast<std::int64_t>(allowance));phase="complete_whole_source_geometry";
                if(frames.wide==frames.ordinary){errors.emplace_back("State85 complete positive remains whole-source fallback");outcome="mandatory_source_positive_unmet";}
                else{
                    const auto large=validate_impl(frames.wide,model,work);class481_no_resource(large);errors.insert(errors.end(),large.begin(),large.end());
                    if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow);class481_no_resource(small);errors.insert(errors.end(),small.begin(),small.end());}
                    good=errors.empty()&&observations.empty();if(good){++matched;phase="schema_valid_semantic_adversaries";const auto changes=state85_mutations(frames.wide,model,work);class35_counts(output,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());mutations_done=changes.errors.empty();mutated+=mutations_done;}
                    if(!good||!mutations_done||!errors.empty()){++geometry_errors;outcome="complete_geometry_or_adversary_error";}
                    else outcome="native_geometry_pending_original_foreign_predicates";
                }
                if(hidden_choice){errors.emplace_back("State85 hidden versus visible choice family contract remains mandatory unadjudicated; generic geometry is not policy admission");outcome="choice_display_contract_pending";}
                complete=good&&mutations_done&&!hidden_choice&&errors.empty()&&observations.empty();
            }
        }catch(const std::exception& error){++oracle_errors;errors.emplace_back(phase+": "+error.what());outcome="schema_resource_or_execution_error";}
        observation_errors+=!observations.empty();item.set("native_outcome",outcome);item.set("phase",phase);item.set("complete_Model_decoded",model_decoded);item.set("generic_geometry_good_before_mutations",good);item.set("mutations_completed",mutations_done);item.set("complete_native_source_contract_met",complete);item.set("original_foreign_assertions_closed",false);if(outcome=="mandatory_positive_source_profile_unmet"||outcome=="mandatory_source_positive_unmet"||outcome=="choice_display_contract_pending"||outcome=="original_malformed_error_API_policy_pending")mandatory_gaps.push_back({binding.get_string("id"),outcome});class35_errors(output,item,errors,observations,false);records.append(item);
    }
    output.set("qualification","All85 exact whole inputs are observed before per-case Model decode.77 reviewed Models require complete geometry and useful mutants;7 positive profile nulls,1 original malformed/error policy and hidden-choice family policy remain explicit mandatory failures.Original APIs/options/ANSI/SVG/typed mutation/snapshot predicates are not claimed by this terminal source gate.");output.set("facts_sha256",std::string(kState85Sha));output.set("whole_sources",85);output.set("public_observations",observed);output.set("complete_Models_decoded",decoded);output.set("native_geometry_matches",matched);output.set("sources_with_mutations",mutated);output.set("mandatory_positive_profile_pending",positive_pending);output.set("original_error_policy_pending",original_policy);output.set("hidden_choice_family_policy_pending",choice_policy);output.set("original_error_whole_source_preserved",whole_source_retained);output.set("wide_source_fallbacks",fallbacks);output.set("oracle_or_resource_errors",oracle_errors);output.set("geometry_errors",geometry_errors);output.set("observation_errors",observation_errors);auto state85_gaps=output.make_arr();for(const auto& gap:mandatory_gaps){auto gap_row=output.make_obj();gap_row.set("id",gap.id);gap_row.set("outcome",gap.outcome);state85_gaps.append(gap_row);}output.add("mandatory_gaps",state85_gaps);output.add("cases",records);report.set_root(output);state85_write("mermaid-state85-whole-source-scenes.json",report);
    EXPECT_EQ(observed,85);EXPECT_EQ(decoded,77);EXPECT_EQ(oracle_errors,0);EXPECT_EQ(geometry_errors,1);EXPECT_EQ(observation_errors,0);EXPECT_EQ(matched,71);EXPECT_EQ(mutated,71);
    EXPECT_EQ(positive_pending,7);EXPECT_EQ(original_policy,1);EXPECT_EQ(choice_policy,1);EXPECT_EQ(static_cast<int>(mandatory_gaps.size()),14);
    if(auto roster=gap_roster::load_verified_roster()){auto published=json::parse(report.to_string());ASSERT_TRUE(published.has_value());const auto gap_diff=gap_roster::diff_gate(*roster,"state85",published->root().get("mandatory_gaps"));EXPECT_TRUE(gap_diff.ok())<<gap_diff.render("state85");}
}
