    class481_require(doc->root().get_string("schema")=="state_bare_alias_native_controls/v2"&&doc->root().get_string("source_review_gate_sha256")=="7939b9429c972a837fdcf5cc0506a9e732c4c29a2efaef3f37fe4b6b4c30a23b"&&doc->root().get_string("v1_control_payload_sha256")=="704e8ed63e8dd104e7aa3a36927c7599d911038eaf14075cbfecfd8f956851af"&&doc->root().get_string("note_source_review_gate_sha256")=="32fe3906ad0935a9a60197b1a2688756ca13dcb5427cb7c887965e6cd27a3f7d","State bare/alias v2 source lineage and Note expectation review gate");
    class481_require(doc->root().get("cases").is_arr()&&doc->root().get("cases").size()==19,"State bare/alias complete control count");return std::move(*doc);
