TEST(MermaidClassEnvelope22Stage3, DividerRowTransactionRestoresWholeGoodAfterNormalAndExceptionalExits){
    Work setup;const auto papers=envelope22_papers_document(setup);const auto paper=papers.root().get("papers").at(10);
    Work source;source.spend(sizeof(ClassPresentation)+8192u);ClassPresentation presentation;
    const auto model=envelope22_papers_bind(paper,10,source,&presentation);auto grid=namespace45_grid(paper,source);
    const auto good=validate_impl(grid,model,source,false,&presentation);class481_no_resource(good);envelope22_papers_no_schema_errors(good);ASSERT_TRUE(good.empty())<<explain(good);
    const auto selected=envelope22_stage3_card(grid,model,presentation,source);ASSERT_TRUE(selected.has_value());
    source.spend(512u);const auto witness=paper.get("chosen_rect_witnesses").at(0);const int divider_row=static_cast<int>(witness.get("semantic_divider_rows").at(0).as_int()),clear_row=static_cast<int>(witness.get_int("clear_route_row"));
    source.spend(grid.cells.size()*sizeof(std::string)+sizeof(Grid)+256u);for(const auto& cell:grid.cells){source.spend();source.spend(cell.size()*2u);}const auto original=grid;
    // Each is an independent restoration-protocol assertion, not a geometry
    // adversary retry or additional allowance for any source assertion above.
    for(const bool erase:{true,false})for(int mode=0;mode<3;++mode){
        SCOPED_TRACE(erase?"erase":"insert");
        SCOPED_TRACE(mode);
        const int row=erase?divider_row:clear_row;Work assertion;bool expected_exception=false;
        try{
            const Envelope22Stage3RowPatch patch(grid,*selected,row,erase,assertion);
            EXPECT_FALSE(class481_same_grid(grid,original,assertion));
            if(mode==1)throw std::runtime_error("Envelope22 deliberate restoration probe");
            if(mode==2){Work zero;zero.left=0;static_cast<void>(validate_impl(grid,model,zero,false,&presentation));}
            else{const auto errors=validate_impl(grid,model,assertion,false,&presentation);class481_no_resource(errors);envelope22_papers_no_schema_errors(errors);EXPECT_FALSE(errors.empty());}
        }catch(const std::runtime_error& error){
            expected_exception=mode==1?std::string_view(error.what())=="Envelope22 deliberate restoration probe":mode==2&&class481_resource(error.what());
            EXPECT_TRUE(expected_exception)<<error.what();
        }
        EXPECT_EQ(expected_exception,mode!=0);
        EXPECT_TRUE(class481_same_grid(grid,original,assertion));
    }
    Work zero;zero.left=0;bool preallocation_resource=false;
    try{const Envelope22Stage3RowPatch patch(grid,*selected,divider_row,true,zero);}catch(const std::runtime_error& error){preallocation_resource=class481_resource(error.what());}
    EXPECT_TRUE(preallocation_resource);
    EXPECT_TRUE(class481_same_grid(grid,original,source));
}

