    if(row.get("model").is_null()){class481_require(obligations.size()==0,"State scoped closed source has no geometry obligation");return {};}
    auto model=state85_model(row.get("model"),work);std::set<std::string> seen;
    obligations.iter([&](JsonVal id){const auto name=state85_string(id,work);work.spend(name.size()+128u);class481_require(seen.insert(std::string(name)).second,"State scoped unique observable direction owner");
        bool found=false;for(const auto& group:model.groups){work.spend(group.id.size()+name.size()+1u);if(group.id==name)found=!group.direction.empty();}class481_require(found,"State scoped authored observable group direction");
    });return model;
