    root.set("qualification","Complete source-backed scoped direction gate only. Five original State85 rows stay in the unchanged full85 gate; fourteen focused Models require complete geometry before schema-valid semantic/direction mutants. Version2 upgrades only the exact original block_note input under its separate Note source gate; six deferred profiles are not upstream-invalid proofs. Original77Models/eightnulls/choice/foreign APIs remain mandatory and unpromoted.");
    root.set("public_observations",static_cast<int>(observed));root.set("complete_Models_decoded",static_cast<int>(decoded));root.set("native_geometry_matches",static_cast<int>(matched));root.set("sources_with_meaningful_mutations",static_cast<int>(mutated));root.set("closed_whole_sources_retained",static_cast<int>(closed));root.set("oracle_or_execution_errors",static_cast<int>(errors_count));root.set("observation_errors",static_cast<int>(observation_errors));root.set("setup_work_remaining",static_cast<std::int64_t>(setup.left));root.add("cases",records);report.set_root(root);state85_write("mermaid-state-scoped-direction-controls.json",report);
