std::optional<std::size_t> class481_generic13_index(JsonVal legacy,std::size_t ordinal,Work& work){
    work.spend(sizeof(std::optional<std::size_t>)+64u);
    const auto id=class481_text(legacy.get("id"),work,256);
    for(std::size_t n=0;n<kGeneric13Pins.size();++n){
        const auto& pin=kGeneric13Pins[n];work.spend(id.size()+pin.id.size()+4u);
        // The same complete input can legitimately occur at another vendor ID.
        // Only ID or inventory ordinal selects a tuple; SHA alone never does.
        if(id!=pin.id&&ordinal!=pin.ordinal)continue;
        class481_require(id==pin.id&&ordinal==pin.ordinal,"Class481 Generic13 conflicting ID/ordinal tuple");
        const auto hash=class481_text(legacy.get("source_sha256"),work,64);work.spend(hash.size()+pin.source_sha.size()+1u);
        class481_require(hash==pin.source_sha,"Class481 Generic13 tuple source SHA");
        class481_require(legacy.get("whole_native_model").is_null()&&legacy.get("whole_native_model_sha256").is_null(),"Class481 Generic13 historical null required");
        return n;
    }
    return std::nullopt;
}
void class481_generic13_consume(std::array<bool,13>& consumed,std::size_t index,Work& work){
    work.spend(3u);class481_require(index<consumed.size(),"Class481 Generic13 consumption index");
    class481_require(!consumed[index],"Class481 Generic13 duplicate authority consumption");consumed[index]=true;
}
void class481_generic13_finish(const std::array<bool,13>& consumed,Work& work){
    work.spend(consumed.size()+1u);
    class481_require(std::ranges::all_of(consumed,[](bool value){return value;}),"Class481 Generic13 unused authority");
}
std::string generic13_hash(JsonVal value,Work& work,std::size_t bound){
    // Caller-local immutable/parsed-control bound. The existing canonical
    // helper prepays17531*8; this supplements it before any allocation.
    if(bound>17531u)work.spend((bound-17531u)*8u);
    const auto encoded=class481_canonical(value,work);work.spend(encoded.size()*3u+64u);return digest(encoded);
}
