TEST(MermaidClassGeneric13, CompleteOriginalSourcesPrimaryObjectsAndNullHistoryStayBound){
    Work setup;const auto added=generic13_document(setup);const auto facts=class481_document();const auto originals=class481_originals(facts.root());std::size_t decoded=0,entities=0,types=0,edges=0,members=0,groups=0,fields=0;
    for(std::size_t n=0;n<13;++n){Work work;const auto row=added.root().get("cases").at(n);SCOPED_TRACE(std::string(kGeneric13Pins[n].id));try{const auto model=generic13_bind(row,n,facts.root().get("cases").at(kGeneric13Pins[n].ordinal),originals,work);++decoded;entities+=model.entities.size();edges+=model.relations.size();groups+=model.groups.size();for(const auto& e:model.entities)members+=e.rows.size();types+=row.get("authority").get("generic_headers").size();fields+=kGeneric13Pins[n].fields;}catch(const std::exception& e){ADD_FAILURE()<<e.what();}}
    EXPECT_EQ(decoded,13u);EXPECT_EQ(entities,41u);EXPECT_EQ(types,25u);EXPECT_EQ(edges,18u);EXPECT_EQ(members,44u);EXPECT_EQ(groups,11u);EXPECT_EQ(fields,1720u);
    const auto seed=added.root().get("cases").at(0);
    auto reject=[&](auto change,std::string_view expected,bool refresh_model=false){Work work;work.spend((kGeneric13AuthorityBound+4096u)*16u+8192u);json::JsonMutDoc altered;auto row=altered.copy_val(seed);altered.set_root(row);change(row);
        if(refresh_model){const auto temporary=altered.to_string();work.spend(temporary.size()*4u+256u);auto parsed=json::parse(temporary);ASSERT_TRUE(parsed);row.set("whole_native_model_sha256",generic13_hash(parsed->root().get("whole_native_model"),work,kGeneric13ModelBound));}
        const auto bytes=altered.to_string();work.spend(bytes.size()*4u+256u);auto parsed=json::parse(bytes);ASSERT_TRUE(parsed);bool rejected=false;try{static_cast<void>(generic13_bind(parsed->root(),0,facts.root().get("cases").at(kGeneric13Pins[0].ordinal),originals,work));}catch(const std::runtime_error& e){ASSERT_FALSE(class481_resource(e.what()))<<e.what();EXPECT_EQ(std::string_view(e.what()),expected);rejected=true;}EXPECT_TRUE(rejected);
    };
    reject([](json::JsonMutVal r){r.set("unknown",true);},"CLASS481 exact object fields");
    reject([](json::JsonMutVal r){r.get("whole_native_model").set("family","state");},"CLASS481 Model family");
    reject([](json::JsonMutVal r){r.get("whole_native_model").set("direction","XX");},"CLASS481 direction enum");
    reject([](json::JsonMutVal r){r.get("whole_native_model").get("entities").at(0).get("rows").at(0).set("role","state_body");},"CLASS481 member compartment role");
    reject([](json::JsonMutVal r){r.get("whole_native_model").get("entities").at(0).set("label","Wrong");},"Generic13 source-visible generic label",true);
    reject([](json::JsonMutVal r){r.get("authority").get("primary_field_accounting").at(0).set("type","unknown");},"Generic13 primary field type enum");
    reject([](json::JsonMutVal r){r.get("authority").get("primary_field_accounting").at(1).set("pointer","");},"Generic13 duplicate primary field pointer");
    reject([](json::JsonMutVal r){r.get("authority").get("complete_original_inventory_case").get("complete_vendor_case").set("input","decoy");},"Generic13 complete original vendor case");
    Work zero;zero.left=0;bool resource=false;try{static_cast<void>(generic13_bind(seed,0,facts.root().get("cases").at(kGeneric13Pins[0].ordinal),originals,zero));}catch(const std::runtime_error& e){resource=class481_resource(e.what());}EXPECT_TRUE(resource);
}
