            class481_keys(p,{"name","source","source_sha256","whole_native_model","whole_native_model_sha256","generic_header_mapping","width","height","literal_rows","physical_controls","qualification","literal_rows_sha256"},work);
            class481_require(p.get("width").is_int()&&p.get("height").is_int()&&p.get_int("width")>0&&p.get_int("width")<=240&&p.get_int("height")>0&&p.get_int("height")<=256,"Generic13 literal paper bounds");work.spend(static_cast<std::size_t>(p.get_int("width")*p.get_int("height"))*8u+1024u);std::string literal;
