json::JsonDoc generic_branch_document(Work& setup){
    setup.spend(kGenericBranchBytes*3u+8192u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kGenericBranchFile;
    class481_require(std::filesystem::file_size(path)==kGenericBranchBytes,"Generic branch exact fixture stat");
    const auto bytes=read(path);class481_require(bytes.size()==kGenericBranchBytes&&digest(bytes)==kGenericBranchSha,"Generic branch exact fixture bytes/hash");
    auto doc=json::parse(bytes);class481_require(doc.has_value(),"Generic branch fixture parse");const auto root=doc->root();
    class481_keys(root,{"schema","qualification","parent_design_r1_sha256","primary_references","cases","unreviewed_source_debts"},setup);
    class481_require(root.get_string("schema")=="class_generic_branch_controls/v1"&&root.get_string("parent_design_r1_sha256")=="66f8739195cf7a307cacf9d2bcca170e049ddbd0c14fa64412481f2d725a1493"&&root.get("cases").is_arr()&&root.get("cases").size()==15&&root.get("primary_references").is_arr()&&root.get("primary_references").size()==11&&root.get("unreviewed_source_debts").is_arr()&&root.get("unreviewed_source_debts").size()==2,"Generic branch fixed source collections");
    // Exact whole-asset digest owns the reviewed primary-span/source witness tuple;
    // no build-directory primary file or extra renderer/parser is loaded at runtime.
    return std::move(*doc);
}
void generic_branch_bind(JsonVal row,std::size_t ordinal,Work& work){
    class481_require(ordinal<kGenericBranchPins.size(),"Generic branch ordinal");const auto& pin=kGenericBranchPins[ordinal];
    class481_keys(row,{"name","source","source_sha256","expected","whole_native_model","whole_native_model_sha256","source_witness"},work);
    const auto name=class481_text(row.get("name"),work,64),source=class481_text(row.get("source"),work);
    work.spend(source.size()*3u+256u);class481_require(name==pin.name&&row.get_string("source_sha256")==pin.source_sha&&digest(source)==pin.source_sha,"Generic branch complete source/order/name binding");
    const auto witness=row.get("source_witness");class481_keys(witness,{"primary_rule","reference_ids","ordered_actions","qualification"},work);
    class481_require(witness.get("reference_ids").is_arr()&&witness.get("reference_ids").size()>0&&witness.get("ordered_actions").is_arr()&&witness.get("ordered_actions").size()>0,"Generic branch complete source action witness");
    class481_require(generic13_hash(row,work,17531u)==pin.row_sha,"Generic branch full source/Model/primary witness binding");
    if(pin.whole)class481_require(row.get_string("expected")=="whole_scene"&&row.get("whole_native_model").is_obj()&&row.get_string("whole_native_model_sha256")==pin.model_sha,"Generic branch complete positive Model binding");
    else class481_require(row.get_string("expected")=="unreviewed_whole_source_profile"&&row.get("whole_native_model").is_null()&&row.get("whole_native_model_sha256").is_null(),"Generic branch explicit null debt cannot become a drawing Model");
}
