    root.set("source_facts_sha256",kGenericBranchSha);root.set("public_sources",15);root.set("public_observations",static_cast<int>(observed));root.set("complete_Models_decoded",static_cast<int>(decoded));root.set("complete_geometry_and_mutations_match",static_cast<int>(strong));root.set("source_profiles_with_null_Model",4);root.set("whole_source_profiles_preserved",static_cast<int>(closed));root.set("source_design_only_debts",2);root.set("resource_errors",static_cast<int>(resources));root.set("oracle_or_protocol_or_resource_errors",static_cast<int>(oracle_errors));root.add("cases",records);report.set_root(root);
