TEST(MermaidClassGenericAdjacency, SeparatedSuffixKeepsTheCompleteUnreviewedSourceAtEveryOperandOwner){
    // These are finite native profile boundaries, not upstream-invalid claims.
    // Positive adjacent operands already have complete Models in Generic13 and
    // the separately reviewed branch15. Never infer a partial graph here.
    constexpr std::array<std::string_view,5> sources{{
        "classDiagram\nclass A ~U~\n",
        "classDiagram\n<<interface>> A ~U~\n",
        "classDiagram\nA ~U~ --> B\n",
        "classDiagram\nB --> A ~U~\n",
        "classDiagram\nA ~U~ : +U item\n",
    }};
    Work setup;setup.spend(8192u);json::JsonMutDoc report;
    auto root=report.object(),records=root.make_arr();std::size_t observed=0,preserved=0,errors=0;
    for(const auto source:sources){
        Work work;work.spend(8192u+source.size()*8u);
        SCOPED_TRACE(std::string(source));auto item=root.make_obj();
        item.set("complete_source",source);item.set("source_sha256",digest(source));
        try{
            const auto frames=class35_observe(source,work);++observed;
            const auto observations=class35_observations(frames,root,item,work);
            envelope22_stage3_ordinary_frames(frames,root,item,work);
            const bool closed=observations.empty()&&frames.wide==frames.ordinary&&
                frames.narrow==frames.small&&frames.restored==frames.ordinary;
            EXPECT_TRUE(closed);preserved+=closed;
            item.set("whole_unreviewed_source_preserved",closed);
            item.set("native_geometry_credit",0);
            for(const auto& failure:observations){ADD_FAILURE()<<failure;++errors;}
        }catch(const std::exception& failure){ADD_FAILURE()<<failure.what();++errors;item.set("execution_error",failure.what());}
        // Finite metadata/error publication was reserved before capture; no
        // failed Work ledger is reset, and later complete inputs still run.
        records.append(item);
    }
    EXPECT_EQ(observed,5u);EXPECT_EQ(preserved,5u);EXPECT_EQ(errors,0u);
    root.set("qualification","Five complete synthesized native source-profile boundaries only. Physical adjacency is deliberately not widened by the trimmed Class identifier remainder. No upstream-invalid, drawing, source Model, original suite admission or foreign API credit.");
    root.set("public_observations",static_cast<int>(observed));root.set("whole_sources_preserved",static_cast<int>(preserved));root.set("execution_or_observation_errors",static_cast<int>(errors));root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-generic-adjacency-controls.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'));
#endif
}

TEST(MermaidClassGenericSourceOrigin, BareCRStaysAWholeBoundaryAndCRLFKeepsCompleteTypedScenes){
    // Source spelling controls, independent of production output. Two complete
    // Models are exact CRLF spellings of independently reviewed LF positives.
    constexpr std::size_t fixture_bytes=6081u;
    constexpr std::string_view fixture_sha="0022b03d4b746c7b8caa12cb96ad9fc1029507359daa0c407abe2d6c2714e6e0";
    Work setup;setup.spend(fixture_bytes*3u+16384u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_native/class_generic_raw_cr_controls.v1.json";
    ASSERT_EQ(std::filesystem::file_size(path),fixture_bytes);const auto bytes=read(path);
    ASSERT_EQ(bytes.size(),fixture_bytes);ASSERT_EQ(digest(bytes),fixture_sha);
    const auto doc=json::parse(bytes);ASSERT_TRUE(doc);
    const auto rows=doc->root().get("cases");ASSERT_TRUE(rows.is_arr());ASSERT_EQ(rows.size(),7u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    std::size_t observed=0,decoded=0,strong=0,mutated=0,closed=0,execution_errors=0,resource_errors=0;
    for(std::size_t n=0;n<7u;++n){
        Work work;work.spend(16384u);const auto row=rows.at(n);auto item=root.make_obj();
        std::string phase="capture_complete_source_before_binding";std::vector<std::string> errors,observations;bool matched=false;
        try{
            const auto source=class481_text(row.get("source"),work),name=class481_text(row.get("name"),work,64);
            work.spend(source.size()*8u+name.size()*4u+512u);SCOPED_TRACE(std::string(name));
            item.set("name",name);item.set("complete_source",source);item.set("source_sha256",digest(source));
            const auto frames=class35_observe(source,work);++observed;
            observations=class35_observations(frames,root,item,work);envelope22_stage3_ordinary_frames(frames,root,item,work);
            phase="source_and_complete_Model_binding";
            class481_require(digest(source)==row.get_string("source_sha256"),"Generic raw-CR exact source binding");
            const auto meaning=row.get("whole_native_model");
            if(n<5u){
                class481_require(meaning.is_null()&&row.get("whole_native_model_sha256").is_null(),"Generic bare-CR profile keeps null Model");
                matched=observations.empty()&&frames.wide==frames.ordinary&&frames.narrow==frames.small&&frames.restored==frames.ordinary;
                closed+=matched;
            }else{
                const auto model=class481_model(meaning,work);++decoded;
                const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*8u+4096u);
                class481_require(digest(encoded)==row.get_string("whole_native_model_sha256"),"Generic CRLF whole reviewed Model binding");
                item.add("whole_native_Model",report.copy_val(meaning));item.set("Model_sha256",digest(encoded));
                const auto allowance=work.left;item.set("postdecode_geometry_allowance",static_cast<std::int64_t>(allowance));phase="complete_CRLF_geometry";
                if(frames.wide==frames.ordinary)errors.emplace_back("Mandatory complete CRLF positive remains source fallback");
                else{
                    const auto large=validate_impl(frames.wide,model,work);class481_no_resource(large);errors.insert(errors.end(),large.begin(),large.end());
                    if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow);class481_no_resource(small);errors.insert(errors.end(),small.begin(),small.end());}
                    if(errors.empty()&&observations.empty()){
                        ++strong;phase="complete_semantic_mutations";const auto changes=class481_mutations(frames.wide,model,work);
                        work.spend((changes.executed.size()+changes.skipped.size())*256u+8192u);class35_counts(root,item,changes);
                        errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());matched=errors.empty();mutated+=matched;
                    }
                }
            }
        }catch(const std::exception& failure){++execution_errors;resource_errors+=class481_resource(failure.what());errors.emplace_back(phase+": "+failure.what());}
        EXPECT_TRUE(matched);EXPECT_TRUE(errors.empty())<<explain(errors);EXPECT_TRUE(observations.empty())<<explain(observations);
        item.set("phase",phase);item.set("mandatory_disposition_matched",matched);class35_errors(root,item,errors,observations);records.append(item);
    }
    EXPECT_EQ(observed,7u);EXPECT_EQ(decoded,2u);EXPECT_EQ(strong,2u);EXPECT_EQ(mutated,2u);EXPECT_EQ(closed,5u);EXPECT_EQ(execution_errors,0u);EXPECT_EQ(resource_errors,0u);
    root.set("qualification","Source-origin controls only: five complete bare-CR initial-profile boundaries are not drawing/upstream-invalid credit; two CRLF whole Models preserve exact reviewed LF semantics. All original suites and existing source Models remain immutable; no renderer output selected expectations.");
    root.set("source_facts_sha256",fixture_sha);root.set("public_observations",static_cast<int>(observed));root.set("complete_Models_decoded",static_cast<int>(decoded));root.set("whole_geometry_matches",static_cast<int>(strong));root.set("sources_with_mutations",static_cast<int>(mutated));root.set("whole_profile_sources_preserved",static_cast<int>(closed));root.set("execution_errors",static_cast<int>(execution_errors));root.set("resource_errors",static_cast<int>(resource_errors));root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-generic-source-origin-controls.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'));
#endif
}


