json::JsonDoc state_description_branch_document(Work& setup){
    setup.spend(8192u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kStateDescriptionBranchPath;
    class481_require(std::filesystem::file_size(path)==kStateDescriptionBranchBytes,"State description branch exact fixture size");
    setup.spend(kStateDescriptionBranchBytes*3u+4096u);const auto bytes=read(path);
    class481_require(bytes.size()==kStateDescriptionBranchBytes&&digest(bytes)==kStateDescriptionBranchSha,"State description branch complete fixture bytes/hash");
    auto parsed=json::parse(bytes);class481_require(parsed.has_value(),"State description branch JSON");const auto root=parsed->root();
    class481_keys(root,{"schema","source_contract_sha256","producer_design_lock_sha256","origin_presence_addendum_sha256","qualification","cases"},setup);
    class481_require(root.get("schema").as_str()=="state_description_branch_controls/v1"&&root.get("source_contract_sha256").as_str()=="799e25d4c7822397946aeab94205c250e00022f22d6919c60b004558eb2beda3"&&root.get("producer_design_lock_sha256").as_str()=="0957546e8654dcc42ee48ff07fd58a2c2cee4d326ffc9b4fe72c477aee5d1e1c"&&root.get("origin_presence_addendum_sha256").as_str()=="6c73df57982828684055915e3a103faf9da7f1f41886bd9c60a1177e1d1600e0","State description branch source/design authority");
    class481_require(root.get("cases").is_arr()&&root.get("cases").size()==kStateDescriptionBranchPins.size(),"State description branch complete denominator");return std::move(*parsed);
}
JsonVal state_description_branch_bind(JsonVal row,std::size_t at,Work& work){
    work.spend(4096u);class481_require(at<kStateDescriptionBranchPins.size(),"State description branch index domain");const auto& pin=kStateDescriptionBranchPins[at];
    class481_keys(row,{"name","source","source_sha256","model","model_sha256","expected"},work);
    const auto name=class481_text(row.get("name"),work,64u),source=class481_text(row.get("source"),work);work.spend(name.size()+source.size()*3u+256u);
    class481_require(name==pin.name,"State description branch exact name/order");
    class481_require((source.starts_with("stateDiagram-v2\n")||source.starts_with("stateDiagram-v2\r\n"))&&row.get("source_sha256").is_str()&&row.get("source_sha256").as_str()==pin.source_sha&&digest(source)==pin.source_sha,"State description branch complete raw source binding");
    const auto meaning=row.get("model");
    if(pin.model_sha.empty())class481_require(meaning.is_null()&&row.get("model_sha256").is_null()&&row.get("expected").as_str()=="whole_source_native_profile_closed","State description branch explicit unreviewed whole-source profile");
    else{
        class481_require(meaning.is_obj()&&row.get("model_sha256").is_str()&&row.get("model_sha256").as_str()==pin.model_sha&&row.get("expected").as_str()=="complete_geometry","State description branch complete Model authority");
        const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*3u+128u);class481_require(digest(encoded)==pin.model_sha,"State description branch complete Model binding");
    }
    return meaning;
}
