TEST(MermaidStateDescriptions, EverySourceOwnedOriginScopePhysicalLineAndPromotionBoundaryRemainsWhole){
    Work setup;const auto document=state_description_branch_document(setup);json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    int observed=0,decoded=0,matched=0,mutated=0,closed=0,oracle_errors=0,observation_errors=0,direction_contrasts=0;
    for(std::size_t at=0;at<kStateDescriptionBranchPins.size();++at){
        Work work;work.spend(131072u);const auto row=document.root().get("cases").at(at);auto item=root.make_obj();std::string phase="source_before_capture";std::vector<std::string> errors,observations;bool captured=false,good=false,done=false;
        const auto name=row.get("name").as_str();work.spend(name.size()*4u+128u);SCOPED_TRACE(std::string(name));
        try{
            const auto input=class481_text(row.get("source"),work);work.spend(input.size()*4u+256u);item.set("name",name);item.set("complete_source",std::string(input));item.set("source_sha256",digest(input));
            phase="all_public_captures_before_binding_or_Model_decode";const auto frames=class35_observe(input,work);captured=true;++observed;observations=class35_observations(frames,root,item,work);envelope22_stage3_ordinary_frames(frames,root,item,work);
            phase="strict_complete_source_Model_binding";const auto meaning=state_description_branch_bind(row,at,work);
            if(meaning.is_null()){
                phase="unreviewed_profile_whole_source_preservation";if(frames.wide==frames.ordinary&&frames.narrow==frames.small&&frames.restored==frames.wide&&observations.empty())++closed;else errors.emplace_back("State description unreviewed branch must preserve whole source at both widths");
            }else{
                const auto model=state85_model(meaning,work,true);++decoded;const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*4u+128u);item.set("complete_Model_json",encoded);item.set("complete_Model_sha256",digest(encoded));const auto allowance=work.left;item.set("postdecode_geometry_allowance",static_cast<std::int64_t>(allowance));
                phase="complete_same_chosen_State_geometry";
                if(frames.wide==frames.ordinary)errors.emplace_back("State description branch complete positive remains mandatory fallback");
                else{
                    const auto large=validate_impl(frames.wide,model,work,false,nullptr,true);state_description_result(large);errors.insert(errors.end(),large.begin(),large.end());
                    if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow,false,nullptr,true);state_description_result(small);errors.insert(errors.end(),small.begin(),small.end());}
                    good=errors.empty()&&observations.empty();if(good){
                        ++matched;phase="schema_valid_full_State_and_literal_body_mutants";auto changes=state_description_mutations(frames.wide,model,work);
                        for(const auto& owner:model.groups){work.spend(owner.id.size()+owner.direction.size()+320u);if(owner.direction.empty())continue;
                            Work contrast;static_cast<void>(class481_copy_charge(model,contrast));auto wrong=model;
                            for(auto& group:wrong.groups){contrast.spend(group.id.size()+owner.id.size()+16u);if(group.id==owner.id)group.direction=group.direction=="LR"?"RL":group.direction=="RL"?"LR":group.direction=="BT"?"TB":"BT";}
                            const auto rejected=validate_impl(frames.wide,wrong,contrast,false,nullptr,true);state_description_result(rejected);++changes.executed["observable_scoped_direction"];
                            if(!std::ranges::any_of(rejected,[](const std::string& error){return error=="Acyclic relation rank contradicts scope direction";}))changes.errors.emplace_back("State description scoped direction contrast did not reject its complete rank");else ++direction_contrasts;
                        }
                        work.spend((changes.executed.size()+changes.skipped.size())*256u+4096u);class35_counts(root,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());done=changes.errors.empty();mutated+=done;
                    }
                }
            }
        }catch(const std::exception& error){++oracle_errors;errors.emplace_back(phase+": "+error.what());}
        observation_errors+=!observations.empty();item.set("phase",phase);item.set("public_observed_before_decode",captured);item.set("complete_geometry_good_before_mutants",good);item.set("mutations_completed",done);item.set("foreign_predicates_certified",0);item.set("work_remaining",static_cast<std::int64_t>(work.left));class35_errors(root,item,errors,observations);records.append(item);
    }
    // Parsed controls refresh their own hashes and reach exact source/Model guards after all27 observations.
    auto protocol_reject=[&](std::size_t at,std::string_view expected,auto change,bool refresh_model=false){Work work;const auto row=document.root().get("cases").at(at);const auto encoded=class481_canonical(row,work);work.spend(encoded.size()*20u+4096u);json::JsonMutDoc copy;auto value=copy.raw_json(encoded);copy.set_root(value);change(value,work);
        if(refresh_model){work.spend((encoded.size()+64u)*16u+4096u);const auto changed=copy.to_string();auto immutable=json::parse(changed);ASSERT_TRUE(immutable.has_value());const auto model=class481_canonical(immutable->root().get("model"),work);work.spend(model.size()*3u+128u);value.set("model_sha256",digest(model));}
        const auto bytes=copy.to_string();work.spend(bytes.size()*4u+128u);auto parsed=json::parse(bytes);ASSERT_TRUE(parsed.has_value());bool rejected=false;
        try{static_cast<void>(state_description_branch_bind(parsed->root(),at,work));}catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()));EXPECT_EQ(std::string_view(error.what()),expected);rejected=true;}EXPECT_TRUE(rejected);};
    protocol_reject(0u,"State description branch complete raw source binding",[](auto value,Work& work){constexpr std::string_view changed="stateDiagram-v2\nA : Foreign\n";work.spend(changed.size()*4u+128u);value.set("source",changed);value.set("source_sha256",digest(changed));});
    protocol_reject(1u,"State description branch complete Model authority",[](auto value,Work& work){work.spend(256u);value.get("model").get("entities").at(0).set("label","Foreign");},true);
    protocol_reject(9u,"State description branch explicit unreviewed whole-source profile",[](auto value,Work& work){work.spend(256u);value.set("expected","complete_geometry");});
    protocol_reject(0u,"CLASS481 exact object fields",[](auto value,Work& work){work.spend(128u);value.set("unconsumed",true);});
    root.set("qualification","Twenty-seven complete source-authored State description controls only. Nine complete Models remain mandatory; eighteen unreviewed native profiles are whole-source preservation, never universal upstream-invalidity or geometry credit. Original85/four mandatory originals/five literal papers/thirty physical adversaries are unchanged. No producer or foreign predicate admission.");
    root.set("fixture_sha256",kStateDescriptionBranchSha);root.set("public_observations",observed);root.set("complete_Models_decoded",decoded);root.set("complete_geometry_matches",matched);root.set("sources_with_mutants",mutated);root.set("closed_whole_profiles",closed);root.set("observable_direction_contrasts",direction_contrasts);root.set("oracle_or_execution_errors",oracle_errors);root.set("observation_errors",observation_errors);root.set("setup_work_remaining",static_cast<std::int64_t>(setup.left));root.add("cases",records);report.set_root(root);state85_write("mermaid-state-description-branch-controls.json",report);
    EXPECT_EQ(observed,27);EXPECT_EQ(decoded,9);EXPECT_EQ(matched,9);EXPECT_EQ(mutated,9);EXPECT_EQ(closed,18);EXPECT_EQ(direction_contrasts,1);EXPECT_EQ(oracle_errors,0);EXPECT_EQ(observation_errors,0);
}

