    class481_keys(row,{"name","source","source_sha256","expected","whole_native_model","whole_native_model_sha256","source_witness"},work);
    const auto name=class481_text(row.get("name"),work,64),source=class481_text(row.get("source"),work);
    work.spend(source.size()*3u+256u);class481_require(name==pin.name&&row.get_string("source_sha256")==pin.source_sha&&digest(source)==pin.source_sha,"Compound rank complete source/order/name binding");
