TEST(MermaidClassCompoundRanks, CompleteLeafDAGAcrossCyclicRootQuotients){
    Work setup;const auto document=compound_rank_document(setup);setup.spend(8192u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();std::size_t observed=0,decoded=0,strong=0,mutated=0,rank_rejected=0,positive_fallbacks=0,resources=0,oracle_errors=0,geometry_errors=0,observation_errors=0;
    for(std::size_t n=0;n<kCompoundRankPins.size();++n){
        Work work;const auto& pin=kCompoundRankPins[n];work.spend(pin.name.size()*4u+128u);SCOPED_TRACE(std::string(pin.name));const auto row=document.root().get("cases").at(n);
        // Finite publication/catch storage is paid before capture. No catch resets Work.
        work.spend(131072u);auto item=root.make_obj();item.set("name",pin.name);item.set("source_sha256",pin.source_sha);item.set("source_facts_sha256",kCompoundRankSha);
        bool matched=false,good=false,done=false;std::string phase="capture_complete_source_before_Model",outcome="not_observed";std::vector<std::string> errors,observations;
        try{
            const auto source=class481_text(row.get("source"),work);const auto frames=class35_observe(source,work);++observed;
            observations=class35_observations(frames,root,item,work);envelope22_stage3_ordinary_frames(frames,root,item,work);
            work.spend(source.size()*4u+256u);item.set("complete_source",source);
            phase="strict_source_Model_primary_witness_binding";compound_rank_bind(row,n,work);
            const auto model=generic13_control_model(row,work);++decoded;work.spend(kGeneric13ModelBound*8u+4096u);item.add("complete_native_Model",report.copy_val(row.get("whole_native_model")));
            const auto allowance=work.left;item.set("postdecode_geometry_allowance",static_cast<std::int64_t>(allowance));phase="complete_native_geometry";
            if(frames.wide==frames.ordinary){++positive_fallbacks;outcome="mandatory_complete_source_positive_unmet";}
            else{
                const auto found=validate_impl(frames.wide,model,work);class481_no_resource(found);errors.insert(errors.end(),found.begin(),found.end());
                if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow);class481_no_resource(small);errors.insert(errors.end(),small.begin(),small.end());}
                geometry_errors+=!errors.empty();good=errors.empty()&&observations.empty();
                if(good){
                    phase="meaningful_complete_Model_adversaries";const auto changes=class481_mutations(frames.wide,model,work);work.spend((changes.executed.size()+changes.skipped.size())*256u+8192u);class35_counts(root,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());done=errors.empty();
                    if(done){
                        // This independent inverse assertion inherits the postdecode
                        // allowance; it never resets/retries the spent source ledger.
                        Work inverse{allowance};static_cast<void>(class481_copy_charge(model,inverse));auto reversed=model;
                        reversed.direction=model.direction=="LR"?"RL":"LR";
                        const auto rank_errors=validate_impl(frames.wide,reversed,inverse);class481_no_resource(rank_errors);
                        const bool rank_seen=std::ranges::any_of(rank_errors,[](const std::string& error){return error.find("Acyclic relation rank contradicts scope direction")!=std::string::npos;});
                        if(rank_seen){++rank_rejected;++strong;++mutated;outcome="complete_geometry_mutations_and_inverse_rank_match";}
                        else {done=false;errors.emplace_back("Compound rank inverse direction did not reach leaf-rank rejection");outcome="inverse_rank_error";}
                    }else outcome="semantic_adversary_error";
                }else outcome="whole_geometry_error";
            }
            matched=good&&done;
        }catch(const std::exception& e){++oracle_errors;resources+=class481_resource(e.what());errors.emplace_back(phase+": "+e.what());outcome="source_schema_resource_or_execution_error";}
        observation_errors+=!observations.empty();EXPECT_TRUE(matched);item.set("good_before_mutations",good);item.set("mutations_completed",done);item.set("mandatory_native_contract_satisfied",matched);item.set("phase",phase);item.set("outcome",outcome);item.set("work_remaining",static_cast<std::int64_t>(work.left));class35_errors(root,item,errors,observations);records.append(item);
    }
    EXPECT_EQ(observed,6u);EXPECT_EQ(decoded,6u);EXPECT_EQ(strong,6u);EXPECT_EQ(mutated,6u);EXPECT_EQ(rank_rejected,6u);EXPECT_EQ(positive_fallbacks,0u);EXPECT_EQ(resources,0u);EXPECT_EQ(oracle_errors,0u);EXPECT_EQ(geometry_errors,0u);EXPECT_EQ(observation_errors,0u);
    root.set("qualification","Six synthesized complete source-owned controls, not imported-test completion. All leaf DAG ranks, markers, members, namespace captions and ownership stay mandatory. Nested groups/actual leaf SCCs remain outside the proposed alternative producer profile, never upstream-invalid or omitted obligations. No c567/481 Model, checker, cap or routing change.");
    root.set("source_facts_sha256",kCompoundRankSha);root.set("public_sources",6);root.set("public_observations",static_cast<int>(observed));root.set("complete_Models_decoded",static_cast<int>(decoded));root.set("complete_geometry_and_mutations_match",static_cast<int>(strong));root.set("inverse_leaf_rank_rejections",static_cast<int>(rank_rejected));root.set("source_design_only_debts",2);root.set("resource_errors",static_cast<int>(resources));root.set("oracle_or_protocol_or_resource_errors",static_cast<int>(oracle_errors));root.add("cases",records);report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-class-compound-rank-controls.json",std::ios::binary);ASSERT_TRUE(output&&(output<<report.to_pretty_string()<<'\n'));
#endif
}

