json::JsonDoc caption_starvation_document(Work& setup){
    setup.spend(kCaptionStarvationBytes*3u+16384u);
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kCaptionStarvationFile;
    class481_require(std::filesystem::file_size(path)==kCaptionStarvationBytes,"Caption starvation exact fixture stat");
    const auto bytes=read(path);
    class481_require(bytes.size()==kCaptionStarvationBytes&&digest(bytes)==kCaptionStarvationSha,"Caption starvation complete fixture bytes/hash");
    auto parsed=json::parse(bytes);class481_require(parsed.has_value(),"Caption starvation fixture JSON");
    const auto root=parsed->root();
    class481_keys(root,{"schema","source_gate_sha256","source_plan_sha256","paper_plan_sha256","qualification","sources","papers","full_bad"},setup);
    class481_require(class481_text(root.get("schema"),setup,128)=="class_ordinary_caption_starvation_controls/v1"&&
        class481_text(root.get("source_gate_sha256"),setup,64)=="384b1b60cacf855f2f5bab50dc4e3b19fc72430c758b4db7d928ea035cc2f55c"&&
        class481_text(root.get("source_plan_sha256"),setup,64)=="15eee7ac887f0e6717e60065f26ab2e3a800fa84f8626bbec405e458c336f05c"&&
        class481_text(root.get("paper_plan_sha256"),setup,64)=="d20cd3da8febacdee99ced47971aebcf353d878bafb0d566162cb73681043d1a","Caption starvation exact source/paper authority");
    static_cast<void>(class481_text(root.get("qualification"),setup,1024));
    class481_require(root.get("sources").is_arr()&&root.get("sources").size()==8u&&root.get("papers").is_arr()&&root.get("papers").size()==9u&&root.get("full_bad").is_obj(),"Caption starvation complete source/paper counts");
    return std::move(*parsed);
}
Model caption_starvation_model(JsonVal row,std::size_t ordinal,Work& work){
    work.spend(4096u*16u+8192u+4u*sizeof(Model));
    class481_require(ordinal<kCaptionStarvationSources.size(),"Caption starvation source ordinal");
    const auto& pin=kCaptionStarvationSources[ordinal];
    class481_keys(row,{"name","source","source_sha256","whole_native_model","whole_native_model_sha256"},work);
    const auto source=class481_text(row.get("source"),work,2048);
    work.spend(source.size()*2u+pin.name.size()+256u);
    class481_require(class481_text(row.get("name"),work,128)==pin.name&&class481_text(row.get("source_sha256"),work,64)==pin.source_sha&&digest(source)==pin.source_sha,"Caption starvation complete source binding");
    const auto meaning=row.get("whole_native_model");const auto encoded=class481_canonical(meaning,work);
    class481_require(encoded.size()<=4096u&&class481_text(row.get("whole_native_model_sha256"),work,64)==pin.model_sha&&digest(encoded)==pin.model_sha,"Caption starvation complete Model binding");
    const auto complete=class481_canonical(row,work);
    class481_require(complete.size()<=4096u&&digest(complete)==pin.case_sha,"Caption starvation complete source row authority");
    return class481_model(meaning,work,true);
}
void caption_starvation_paper_binding(JsonVal paper,std::size_t ordinal,Work& work){
    work.spend(16384u*16u+8192u);
    class481_require(ordinal<kCaptionStarvationPapers.size(),"Caption starvation paper ordinal");const auto& pin=kCaptionStarvationPapers[ordinal];
    class481_keys(paper,{"name","source_index","width","height","literal_rows","physical_pixel_controls"},work);
    class481_require(class481_text(paper.get("name"),work,128)==pin.name&&paper.get("source_index").is_int()&&paper.get_int("source_index")==static_cast<std::int64_t>(pin.source),"Caption starvation whole paper source index");
    class481_require(paper.get("physical_pixel_controls").is_arr()&&paper.get("physical_pixel_controls").size()==pin.controls,"Caption starvation exact physical control count");
    const auto complete=class481_canonical(paper,work);class481_require(complete.size()<=16384u&&digest(complete)==pin.case_sha,"Caption starvation complete literal paper binding");
}
void caption_starvation_write(json::JsonMutDoc& report,std::string_view filename){
    // Every case prepays its report/serialization share before publication;
    // setup prepays the fixed header, filename and global report lifetime.
    static_cast<void>(filename);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/std::string(filename),std::ios::binary);
    ASSERT_TRUE(output&&(output<<report.to_string()<<'\n'));
#else
    static_cast<void>(report);
#endif
}
TEST(MermaidClassCaptionStarvation, IndependentWholePapersKeepRealRolesBeforePhysicalAndModelAdversaries){
    try{
        Work setup;const auto document=caption_starvation_document(setup);setup.spend(32768u);
        json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
        int visited=0,good_count=0,mutated=0,physical_executed=0,physical_rejected=0,counterframe_rejected=0,zero_resource=0,oracle_errors=0;
        for(std::size_t n=0;n<kCaptionStarvationPapers.size();++n){
            ++visited;Work work;const auto& pin=kCaptionStarvationPapers[n];work.spend(pin.name.size()*4u+32768u);SCOPED_TRACE(std::string(pin.name));
            auto item=root.make_obj();item.set("name",std::string(pin.name));std::vector<std::string> errors,observations;std::string phase="literal_binding";bool good=false,done=false;
            try{
                const auto paper=document.root().get("papers").at(n);caption_starvation_paper_binding(paper,n,work);
                const auto model=caption_starvation_model(document.root().get("sources").at(pin.source),pin.source,work);
                const auto grid=namespace45_grid(paper,work);phase="complete_good_before_adversaries";
                const auto found=validate_impl(grid,model,work);class481_no_resource(found);errors.insert(errors.end(),found.begin(),found.end());
                good=errors.empty();if(good){
                    ++good_count;phase="actual_physical_glyph_adversaries";
                    const auto controls=paper.get("physical_pixel_controls");
                    for(std::size_t c=0;c<controls.size();++c){
                        const auto change=controls.at(c);class481_keys(change,{"kind","point","before","after"},work);
                        static_cast<void>(class481_text(change.get("kind"),work,128));const auto at=change.get("point");
                        class481_require(at.is_arr()&&at.size()==2u&&at.at(0).is_int()&&at.at(1).is_int(),"Caption starvation integer physical point");
                        const auto x=at.at(0).as_int(),y=at.at(1).as_int();
                        class481_require(x>=0&&x<grid.width&&y>=0&&y<grid.height,"Caption starvation actual physical point bounds");
                        const auto before=class481_text(change.get("before"),work,4),after=class481_text(change.get("after"),work,4);const Point point{static_cast<int>(x),static_cast<int>(y)};
                        class481_require(grid.at(point)==before&&before!=after,"Caption starvation changed actual glyph witness");
                        work.spend(grid.cells.size()*(sizeof(std::string)+16u)+256u);
                        for(const auto& cell:grid.cells)work.spend(cell.size()*2u+1u);
                        auto wrong=grid;work.spend(after.size()*4u+128u);wrong.put(point,std::string(after));
                        const auto bad=validate_impl(wrong,model,work);class481_no_resource(bad);++physical_executed;
                        if(bad.empty())errors.emplace_back("Accepted actual caption/marker/extra-ink physical adversary");else ++physical_rejected;
                    }
                    phase="schema_valid_whole_Model_adversaries";
                    // New entry owns the existing mutator's orphan Grid copy
                    // without changing that helper's historical default fees.
                    work.spend(grid.cells.size()*(sizeof(std::string)+16u)+256u);
                    for(const auto& cell:grid.cells)work.spend(cell.size()*2u+1u);
                    const auto changes=endpoint29_mutations(grid,model,work);
                    work.spend((changes.executed.size()+changes.skipped.size())*512u+8192u);class35_counts(root,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());
                    if(n==1u){
                        phase="complete_real_caption_overwrite_counterframe";const auto bad=document.root().get("full_bad");
                        work.spend(8192u*16u+1024u);class481_keys(bad,{"source_index","good_paper_index","width","height","literal_rows"},work);
                        class481_require(bad.get("source_index").is_int()&&bad.get_int("source_index")==1&&bad.get("good_paper_index").is_int()&&bad.get_int("good_paper_index")==1,"Caption starvation counterframe uses identical good source Model");
                        class481_require(digest(class481_canonical(bad,work))=="2475e468b9a4d3b0304dbe8497a6e25cf7eca9876b9d7eb1878a0c1321ef11d0","Caption starvation complete actual counterframe binding");
                        const auto wrong=namespace45_grid(bad,work);class481_require(wrong.width==grid.width&&wrong.height==grid.height&&grid.at({55,9})=="x"&&wrong.at({55,9})=="┼","Caption starvation real later authored x overwritten");
                        const auto rejected=validate_impl(wrong,model,work);class481_no_resource(rejected);
                        if(rejected.empty())errors.emplace_back("Accepted full later-caption frame with actual missing source x");else ++counterframe_rejected;
                    }
                    if(n==0u){
                        Work zero{0};bool resource=false;
                        try{static_cast<void>(validate_impl(grid,model,zero));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}
                        class481_require(resource,"Caption starvation zero Work is resource, never geometry credit");++zero_resource;
                    }
                    done=errors.empty();if(done)++mutated;
                }
            }catch(const std::exception& error){++oracle_errors;errors.emplace_back(phase+": "+error.what());}
            item.set("phase",phase);item.set("good_before_mutants",good);item.set("all_adversaries_completed",done);class35_errors(root,item,errors,observations);records.append(item);
        }
        root.set("qualification","Nine full independent literal goods and one actual later-caption overwrite counterframe. Virtual future-strip crossings have no semantic predicate. Paper success is not public source/original4 completion; schema/resource/protocol errors never earn rejection credit.");
        root.set("fixture_sha256",std::string(kCaptionStarvationSha));root.set("paper_cases",visited);root.set("complete_good_geometry",good_count);root.set("papers_with_complete_adversaries",mutated);root.set("actual_physical_controls_executed",physical_executed);root.set("actual_physical_controls_rejected",physical_rejected);root.set("whole_real_counterframe_rejected",counterframe_rejected);root.set("separate_zero_resource_controls",zero_resource);root.set("oracle_or_protocol_or_resource_errors",oracle_errors);root.add("cases",records);report.set_root(root);caption_starvation_write(report,"mermaid-class-caption-starvation-papers.json");
        EXPECT_EQ(visited,9);EXPECT_EQ(good_count,9);EXPECT_EQ(mutated,9);EXPECT_EQ(physical_executed,45);EXPECT_EQ(physical_rejected,45);EXPECT_EQ(counterframe_rejected,1);EXPECT_EQ(zero_resource,1);EXPECT_EQ(oracle_errors,0);
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
TEST(MermaidCapabilityReport, ClassCaptionStarvation8) {
    try{
        Work setup;const auto document=caption_starvation_document(setup);setup.spend(32768u);
        json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
        struct NameGap { std::string name; std::string outcome; };
        std::vector<NameGap> mandatory_gaps;
        int visited=0,observed=0,decoded=0,matched=0,mutated=0,fallbacks=0,geometry_errors=0,oracle_errors=0,observation_errors=0;
        for(std::size_t n=0;n<kCaptionStarvationSources.size();++n){
            ++visited;Work work;const auto& pin=kCaptionStarvationSources[n];work.spend(pin.name.size()*4u+32768u);SCOPED_TRACE(std::string(pin.name));
            auto item=root.make_obj();item.set("name",std::string(pin.name));std::vector<std::string> errors,observations;std::string phase="public_capture_before_binding_or_Model_decode",outcome="execution_error";bool good=false,done=false;
            try{
                const auto row=document.root().get("sources").at(n);const auto input=class481_text(row.get("source"),work,2048);
                const auto frames=class35_observe(input,work);++observed;
                // Prepay this case's final report escaping/serialization share,
                // before the existing full-frame publication helpers allocate.
                for(const auto* frame:{&frames.wide,&frames.ordinary,&frames.narrow,&frames.small,&frames.restored}){
                    work.spend(frame->cells.size()+128u);for(const auto& cell:frame->cells)work.spend(cell.size()*12u+16u);
                }
                observations=class35_observations(frames,root,item,work);envelope22_stage3_ordinary_frames(frames,root,item,work);
                if(!class481_sentinel(frames.ordinary,work)||!class481_sentinel(frames.small,work))observations.emplace_back("Caption starvation ordinary physical following sentinel");
                phase="complete_source_and_Model_binding";const auto model=caption_starvation_model(row,n,work);++decoded;const auto allowance=work.left;
                item.set("postdecode_geometry_allowance",static_cast<std::int64_t>(allowance));const bool fallback=frames.wide==frames.ordinary;fallbacks+=fallback;
                if(fallback){outcome="mandatory_complete_positive_source_unmet";errors.emplace_back("Caption starvation complete positive remains whole-source fallback");}
                else{
                    phase="complete_wide_and_drawn_narrow_geometry";const auto wide=validate_impl(frames.wide,model,work);class481_no_resource(wide);errors.insert(errors.end(),wide.begin(),wide.end());
                    if(frames.narrow!=frames.small){Work narrow{allowance};const auto small=validate_impl(frames.narrow,model,narrow);class481_no_resource(small);errors.insert(errors.end(),small.begin(),small.end());}
                    good=errors.empty()&&observations.empty();if(!errors.empty())++geometry_errors;
                    if(good){
                        phase="meaningful_complete_Model_adversaries";
                        work.spend(frames.wide.cells.size()*(sizeof(std::string)+16u)+256u);
                        for(const auto& cell:frames.wide.cells)work.spend(cell.size()*2u+1u);
                        const auto changes=endpoint29_mutations(frames.wide,model,work);
                        work.spend((changes.executed.size()+changes.skipped.size())*512u+8192u);class35_counts(root,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());done=changes.errors.empty();if(done){++matched;++mutated;outcome="complete_native_geometry_and_adversaries";}else outcome="semantic_adversary_error";
                    }else outcome="complete_geometry_or_observation_error";
                }
            }catch(const std::exception& error){++oracle_errors;errors.emplace_back(phase+": "+error.what());outcome="oracle_or_protocol_or_resource_error";}
            observation_errors+=!observations.empty();item.set("phase",phase);item.set("native_outcome",outcome);item.set("good_before_mutants",good);item.set("mutations_completed",done);if(outcome=="mandatory_complete_positive_source_unmet")mandatory_gaps.push_back({std::string(pin.name),"mandatory_complete_positive_source_unmet"});class35_errors(root,item,errors,observations,false);records.append(item);
        }
        root.set("qualification","All eight complete independently source-authored controls: five public captures before binding/Model decode, whole chosen scene and meaningful existing endpoint adversaries. Source fallback is unmet. Original4/29/default/namespace/reciprocal/self/parallel/oldClass obligations stay in their existing mandatory gates; no private context or virtual-strip checker, production change or foreign API/SVG/ASCII admission.");
        root.set("fixture_sha256",std::string(kCaptionStarvationSha));root.set("whole_sources",visited);root.set("public_observations",observed);root.set("complete_Models_decoded",decoded);root.set("complete_geometry_and_mutations_match",matched);root.set("sources_with_mutations",mutated);root.set("whole_source_fallbacks",fallbacks);root.set("geometry_errors",geometry_errors);root.set("oracle_or_protocol_or_resource_errors",oracle_errors);root.set("observation_errors",observation_errors);auto caption_gaps=root.make_arr();for(const auto& gap:mandatory_gaps){auto gap_row=root.make_obj();gap_row.set("name",gap.name);gap_row.set("outcome",gap.outcome);caption_gaps.append(gap_row);}root.add("mandatory_gaps",caption_gaps);root.add("cases",records);report.set_root(root);caption_starvation_write(report,"mermaid-class-caption-starvation-source-scenes.json");
        EXPECT_EQ(visited,8);EXPECT_EQ(observed,8);EXPECT_EQ(decoded,8);EXPECT_EQ(matched,6);EXPECT_EQ(mutated,6);EXPECT_EQ(fallbacks,2);EXPECT_EQ(geometry_errors,0);EXPECT_EQ(oracle_errors,0);EXPECT_EQ(observation_errors,0);EXPECT_EQ(static_cast<int>(mandatory_gaps.size()),2);
        if(auto roster=gap_roster::load_verified_roster()){auto published=json::parse(report.to_string());ASSERT_TRUE(published.has_value());const auto gap_diff=gap_roster::diff_gate(*roster,"class_caption_starvation8",published->root().get("mandatory_gaps"));EXPECT_TRUE(gap_diff.ok())<<gap_diff.render("class_caption_starvation8");}
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
