Class481Mutations official_class285_classifier_mutations(const Grid& grid,const Model& model,const ClassPresentation& presentation,JsonVal mappings,Work& enumeration){
    enumeration.spend(4096u);Class481Mutations out;
    auto reject=[&](std::size_t entity,std::size_t row,std::string_view kind,auto change){
        Work negative;static_cast<void>(class481_copy_charge(model,negative));auto wrong=model;change(wrong.entities[entity].rows[row]);
        const auto errors=validate_impl(grid,wrong,negative,false,&presentation);class481_no_resource(errors);++out.executed[std::string(kind)];if(errors.empty())out.errors.emplace_back("Accepted OfficialClass285 classifier semantic adversary: "+std::string(kind));
    };
    mappings.iter([&](JsonVal mapped){
        enumeration.spend(4096u);const auto entity=static_cast<std::size_t>(mapped.get_int("entity_index")),row=static_cast<std::size_t>(mapped.get_int("row_index"));
        class481_require(entity<model.entities.size()&&row<model.entities[entity].rows.size(),"OfficialClass285 classifier complete mutation Row binding");
        const auto classifier=class481_text(mapped.get("primary_decoded_own_fields").get("classifier"),enumeration,1);const auto& values=model.entities[entity].rows[row].alternatives;
        class481_require(values.size()==1u&&!values[0].empty()&&classifier.size()==1u&&values[0].back()==classifier[0],"OfficialClass285 classifier complete mutation suffix binding");enumeration.spend(values[0].size()+128u);
        reject(entity,row,"typed_classifier_suffix",[](Row& wrong){wrong.alternatives[0].pop_back();});
        if(model.entities[entity].rows.size()>1u)reject(entity,row,"typed_member_role",[](Row& wrong){wrong.role=wrong.role=="method"?"attribute":"method";});else ++out.skipped["compact_single_member_role_has_no_distinct_geometry"];
        const auto star=values[0].find('*');if(star!=std::string::npos&&star+1u<values[0].size())reject(entity,row,"literal_internal_star",[&](Row& wrong){wrong.alternatives[0].erase(star,1u);});else ++out.skipped["no_internal_literal_star"];
    });
    return out;
}
