// Only the17 already bound regression cases are called below. The full285
// original aggregate remains mandatory and its facts/Model debts do not move.
void class285_harness_original(std::size_t n){
    const auto docs=official_class285_documents();const auto originals=official_class285_originals();
    Work work;work.spend(n+1u+32768u);const auto row=docs.facts.root().get("cases").at(n);SCOPED_TRACE(row.get_string("fixture"));
    const auto input=class481_text(row.get("source"),work);auto frames=class35_observe(input,work);
    json::JsonMutDoc report;auto root=report.object(),item=root.make_obj();
    const auto observations=official285_observations(frames,root,item,work);ASSERT_TRUE(observations.empty())<<explain(observations);
    ASSERT_TRUE(class481_sentinel(frames.ordinary,work));ASSERT_TRUE(class481_sentinel(frames.small,work));
    const auto selected=official_class285_bind(row,n,docs,originals,work);
    const bool pending=n==263u||n==264u||n==271u||n==284u;ASSERT_EQ(selected.meaning.is_null(),pending);
    item.set("application_ordinal",static_cast<std::int64_t>(n));item.set("source_sha256",row.get_string("source_sha256"));item.set("whole_Model_is_null",pending);item.set("five_captures_before_own_bind_decode",true);
    if(pending){ASSERT_GT(row.get("unresolved_terminal_obligations").size(),0u);item.set("qualification","Publication and unchanged whole-null debt only; no native geometry admission.");}
    else{
        const auto model=class481_model(selected.meaning,work,true);const auto allowance=work.left;
        work.spend(sizeof(ClassCardWitness)+128u);ClassCardWitness card;
        const auto wide=validate_impl(frames.wide,model,work,false,&selected.presentation,false,&card);class481_no_resource(wide);ASSERT_TRUE(wide.empty())<<explain(wide);
        ASSERT_TRUE(card.box);ASSERT_EQ(card.grid,&frames.wide);ASSERT_EQ(card.model,&model);
        if(frames.narrow!=frames.small){const auto narrow=validate_impl(frames.narrow,model,work,false,&selected.presentation);class481_no_resource(narrow);ASSERT_TRUE(narrow.empty())<<explain(narrow);}
        const auto changes=endpoint29_mutations(frames.wide,model,work,true);ASSERT_TRUE(changes.errors.empty())<<explain(changes.errors);work.spend((changes.executed.size()+changes.skipped.size())*512u+8192u);class35_counts(root,item,changes);
        const auto physical=envelope22_stage3_presentation_mutations(frames.wide,model,selected.presentation,allowance,work,&card);ASSERT_TRUE(physical.errors.empty())<<explain(physical.errors);
        ASSERT_EQ(physical.executed.at("complete_owned_divider_erasure")+physical.executed.at("unauthored_complete_divider_insertion"),1);
        item.set("qualification","Complete original Model geometry and unchanged semantic/physical adversary groups; foreign assertions remain unproved.");
    }
    item.set("work_remaining",static_cast<std::int64_t>(work.left));root.add("case",item);report.set_root(root);state85_write("mermaid-class285-harness-"+std::to_string(n)+".json",report);
}
void class285_harness_reject_grid(const Grid& good,const Model& model,const ClassPresentation& presentation,auto change){
    Work negative;negative.spend(4096u);class285_orphan_copy_prepay(good,negative);auto bad=good;
    change(bad);ASSERT_NE(bad,good)<<"Physical control must change real cells";
    const auto errors=validate_impl(bad,model,negative,false,&presentation);class481_no_resource(errors);ASSERT_FALSE(errors.empty())<<"Complete bad scene was accepted";
}
void class285_harness_reject_Model(const Grid& good,const Model& model,const ClassPresentation& presentation,auto change){
    Work negative;negative.spend(4096u);static_cast<void>(class481_copy_charge(model,negative));auto bad=model;change(bad);
    const auto errors=validate_impl(good,bad,negative,false,&presentation);class481_no_resource(errors);ASSERT_FALSE(errors.empty())<<"Complete changed Model was accepted";
}
void class285_harness_restore_protocol(const Class35Frames& good,const Model& model,const ClassPresentation& presentation){
    Work probe;probe.spend(65536u);int sentinel_y=-1,sentinel_x=-1;
    constexpr std::string_view token="AFTER_RELATIONS_SEMANTICS";
    for(int y=0;y<good.restored.height;++y){probe.spend(static_cast<std::size_t>(good.restored.width)*8u+128u);const auto row=good.restored.row(y);if(trim(row)==token){sentinel_y=y;sentinel_x=static_cast<int>(row.find(token));}}
    ASSERT_GE(sentinel_y,0);ASSERT_GE(sentinel_x,0);
    for(int kind=0;kind<5;++kind){
        Work negative;negative.spend(32768u);for(const auto* grid:{&good.wide,&good.ordinary,&good.narrow,&good.small,&good.restored})class285_orphan_copy_prepay(*grid,negative);auto changed=good;
        auto& bad=changed.restored;
        if(kind<3){for(int x=0;x<bad.width;++x)bad.put({x,sentinel_y}," ");
            if(kind==1)bad.put({sentinel_x,sentinel_y},std::string(token));
            if(kind==2){bad.put({sentinel_x,sentinel_y},"A");bad.put({sentinel_x+1,sentinel_y},"");for(std::size_t n=1;n<token.size();++n)bad.put({sentinel_x+static_cast<int>(n)+1,sentinel_y},std::string(token.substr(n,1)));}
        }else if(kind==3){int blank=-1;for(int y=0;y<bad.height&&blank<0;++y){negative.spend(static_cast<std::size_t>(bad.width)+1u);if(y!=sentinel_y){bool clear=true;for(int x=0;x<bad.width;++x)clear&=bad.at({x,y})==" ";if(clear)blank=y;}}
            ASSERT_GE(blank,0);for(std::size_t n=0;n<token.size();++n)bad.put({static_cast<int>(n),blank},std::string(token.substr(n,1)));
        }else{ASSERT_EQ(bad.width%2,0);ASSERT_LE(bad.height,520);bad.width/=2;bad.height*=2;}
        json::JsonMutDoc report;auto root=report.object();const auto errors=official285_observations(changed,root,root,negative);ASSERT_FALSE(errors.empty());
        // Protocol faults are not semantic-mutation credit. Every bad physical
        // scene still runs the complete checker; duplicate/missing following
        // text can leave the Model itself unchanged and is rejected by obs.
        const auto semantic=validate_impl(bad,model,negative,false,&presentation);class481_no_resource(semantic);
        std::size_t bytes=0;for(const auto* frame:{&changed.wide,&changed.narrow,&changed.restored})for(const auto& cell:frame->cells){negative.spend();bytes+=cell.size();}
        negative.spend(bytes*8u+65536u);report.set_root(root);const auto parsed=json::parse(report.to_string());ASSERT_TRUE(parsed);ASSERT_TRUE(parsed->root().get("restored_identically").is_bool());EXPECT_FALSE(parsed->root().get("restored_identically").as_bool());
        if(kind<4){
            ASSERT_TRUE(parsed->root().get("following_content_retained").is_bool());
            if(kind==3){
                // The last footer still has exact physical spelling. The extra
                // earlier token remains unowned ink in this complete scene.
                EXPECT_TRUE(parsed->root().get("following_content_retained").as_bool());
                EXPECT_FALSE(semantic.empty())<<"Complete scene must reject the extra earlier token";
            }else EXPECT_FALSE(parsed->root().get("following_content_retained").as_bool());
        }
    }
    Work zero{0};bool resource=false;try{static_cast<void>(class481_same_grid(good.wide,good.restored,zero));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource);
}
void class285_harness_header_paper(std::size_t n){
    Work setup;setup.spend(kClass285HarnessHeaderPapers.size()*3u+16384u);const auto doc=json::parse(kClass285HarnessHeaderPapers);ASSERT_TRUE(doc);const auto row=doc->root().at(n);
    Work work;work.spend(32768u);const auto input=class481_text(row.get("source"),work);auto frames=class35_observe(input,work);
    json::JsonMutDoc report;auto root=report.object();const auto observations=official285_observations(frames,root,root,work);ASSERT_TRUE(observations.empty());
    work.spend(input.size()*3u+256u);ASSERT_EQ(digest(input),row.get_string("source_sha256"));ASSERT_EQ(input.size(),static_cast<std::size_t>(row.get_int("source_bytes")));
    const auto meaning=row.get("whole_Model");ASSERT_EQ(digest(class481_canonical(meaning,work)),row.get_string("whole_Model_sha256"));const auto model=class481_model(meaning,work);const ClassPresentation presentation;const auto allowance=work.left;
    work.spend(sizeof(ClassCardWitness)+128u);ClassCardWitness card;const auto good=validate_impl(frames.wide,model,work,false,&presentation,false,&card);class481_no_resource(good);ASSERT_TRUE(good.empty())<<explain(good);ASSERT_TRUE(card.box);ASSERT_TRUE(card.separator);
    if(frames.narrow!=frames.small){const auto narrow=validate_impl(frames.narrow,model,work,false,&presentation);class481_no_resource(narrow);ASSERT_TRUE(narrow.empty())<<explain(narrow);}
    const auto& box=*card.box;const auto& expected=model.entities[0].headers[0][1];const int y=box.t+2,inner=box.r-box.l-1,width=ftxui::string_width(expected),start=box.l+1+(inner-width)/2;
    for(const int shift:{-1,1})class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){const auto glyphs=ftxui::Utf8ToGlyphs(expected);for(int x=box.l+1;x<box.r;++x)bad.put({x,y}," ");int x=start+shift;for(const auto& glyph_:glyphs){class481_require(x>box.l&&x<box.r,"Header shift stays inside owned row");bad.put({x++,y},glyph_);}});
    class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){for(int x=box.l+1;x<box.r;++x)bad.put({x,y}," ");});
    class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){class481_require(bad.at({box.l+1,y})==" ","Extra header ink requires a real SPACE");bad.put({box.l+1,y},"!");});
    class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){bad.put({start+2,y},"!");});
    class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){for(int x=box.l+1;x<box.r;++x)bad.put({x,*card.separator+1}," ");});
    class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){bad.put({box.l,*card.separator},"│");});
    class285_harness_reject_Model(frames.wide,model,presentation,[&](Model& bad){auto& e=bad.entities[0];e.headers[0][1].erase(0,2);e.label.clear();for(const auto& line:e.headers[0]){if(!e.label.empty())e.label+='\n';e.label+=line;}});
    if(n==2u){
        class285_harness_reject_grid(frames.wide,model,presentation,[&](Grid& bad){class481_require(bad.at({start+3,y}).empty(),"Wide continuation control must change the real continuation cell");bad.put({start+3,y},"X");});
        class285_harness_reject_Model(frames.wide,model,presentation,[&](Model& bad){auto& e=bad.entities[0];e.headers[0].erase(e.headers[0].begin()+2);e.label.clear();for(const auto& line:e.headers[0]){if(!e.label.empty())e.label+='\n';e.label+=line;}});
    }
    // A failed complete validation must clear a prior usable witness even if
    // a different whole Model is supplied. Output storage/reset is prepaid.
    Work rejected;rejected.spend(sizeof(ClassCardWitness)+128u);static_cast<void>(class481_copy_charge(model,rejected));auto wrong=model;wrong.entities[0].label="Wrong\n  Tail";wrong.entities[0].headers={{"Wrong","  Tail"}};ClassCardWitness stale=card;
    const auto bad=validate_impl(frames.wide,wrong,rejected,false,&presentation,false,&stale);class481_no_resource(bad);ASSERT_FALSE(bad.empty());ASSERT_FALSE(stale.box);ASSERT_EQ(stale.grid,nullptr);
    const auto physical=envelope22_stage3_presentation_mutations(frames.wide,model,presentation,allowance,work,&card);ASSERT_TRUE(physical.errors.empty())<<explain(physical.errors);ASSERT_EQ(frames.wide,frames.restored);
    if(n==0u)class285_harness_restore_protocol(frames,model,presentation);
}
void class285_harness_publication_boundaries(){
    // Deliberately packed byte protocol data, not a claimed geometry scene.
    // Complete source-bound publication is exercised by each original case.
    Work setup;setup.spend(16384u);const Grid bytes{4,1,{"a\"","b\\","\b\f\n\r\t",std::string("\x01")+"中"}};
    json::JsonMutDoc measure_doc;auto measured=measure_doc.object();Work measure;official285_publish_frame(bytes,"frame",measured,measured,measure);const auto cost=8000000u-measure.left;
    json::JsonMutDoc exact_doc;auto exact=exact_doc.object();Work exact_work{cost};official285_publish_frame(bytes,"frame",exact,exact,exact_work);EXPECT_EQ(exact_work.left,0u);exact_doc.set_root(exact);const auto parsed=json::parse(exact_doc.to_string());ASSERT_TRUE(parsed);
    std::string expected;for(const auto& cell:bytes.cells)expected+=cell;EXPECT_EQ(parsed->root().get("frame").at(0).as_str(),expected);
    json::JsonMutDoc short_doc;auto short_root=short_doc.object();Work short_work{cost-1u};bool resource=false;try{official285_publish_frame(bytes,"frame",short_root,short_root,short_work);}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource);EXPECT_EQ(short_work.left,0u);
    Work copy_measure;class285_orphan_copy_prepay(bytes,copy_measure);const auto copy_cost=8000000u-copy_measure.left;Work copy_exact{copy_cost};class285_orphan_copy_prepay(bytes,copy_exact);EXPECT_EQ(copy_exact.left,0u);Work copy_short{copy_cost-1u};resource=false;try{class285_orphan_copy_prepay(bytes,copy_short);}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource);
    Work zero{0};resource=false;try{class285_orphan_copy_prepay(bytes,zero);}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource);
}
