constexpr std::size_t kClassHierarchyBytes=34585u;
constexpr std::string_view kClassHierarchySha="1f229250fe6bffeb2c29aea411d4264304d68f641a9dc60cab9b4ad1167d52f9";
json::JsonDoc class_hierarchy_document(Work& setup){
    setup.spend(kClassHierarchyBytes*3u+32768u+8u*sizeof(json::JsonDoc));
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/kClassHierarchyFixture;
    class481_require(std::filesystem::file_size(path)==kClassHierarchyBytes,"ClassHierarchy immutable fixture stat");
    const auto bytes=read(path);class481_require(bytes.size()==kClassHierarchyBytes&&digest(bytes)==kClassHierarchySha,"ClassHierarchy immutable fixture hash");
    auto document=json::parse(bytes);class481_require(document.has_value(),"ClassHierarchy fixture JSON");
    const auto root=document->root();class481_keys(root,{"schema","qualification","source_design_lock_sha256","independent_source_review_sha256","cases"},setup);
    class481_require(root.get_string("schema")=="class_hierarchical_namespaces_controls/v1"&&root.get_string("source_design_lock_sha256")=="5f51aa9e884d451645ba4a9bf1f2ca56ccf887eaefe11b3e6ec41920a1811815"&&root.get_string("independent_source_review_sha256")=="b5a22fba2dfa5c4e6baf67eb18d8304b5f99dc3019f87bd4e1f83486391790bb","ClassHierarchy exact source design authority");
    class481_require(root.get("cases").is_arr()&&root.get("cases").size()==37u,"ClassHierarchy complete37 sources");return std::move(*document);
}
std::optional<Model> class_hierarchy_bind(JsonVal row,std::size_t ordinal,Work& work){
    class481_keys(row,{"ordinal","name","source","source_sha256","source_utf8_bytes","expected","whole_native_model","whole_native_model_sha256","source_authority_sha256"},work);
    class481_require(ordinal<kClassHierarchyPins.size()&&row.get("ordinal").is_int()&&row.get_int("ordinal")==static_cast<std::int64_t>(ordinal),"ClassHierarchy exact original ordinal");
    const auto& pin=kClassHierarchyPins[ordinal];work.spend(8u*sizeof(std::string_view)+8u*sizeof(Model)+512u);
    class481_require(class481_text(row.get("name"),work,128)==pin.name&&class481_text(row.get("source_authority_sha256"),work,64)==pin.authority,"ClassHierarchy exact whole source authority");
    const auto source=class481_text(row.get("source"),work);work.spend(source.size()*4u+128u);
    class481_require(row.get("source_utf8_bytes").is_int()&&row.get_int("source_utf8_bytes")==static_cast<std::int64_t>(source.size())&&class481_text(row.get("source_sha256"),work,64)==pin.source&&digest(source)==pin.source,"ClassHierarchy exact complete source");
    class481_require(class481_text(row.get("expected"),work,32)==(pin.positive?"complete_geometry":"whole_source_boundary"),"ClassHierarchy source-owned disposition");
    const auto meaning=row.get("whole_native_model");
    if(!pin.positive){class481_require(meaning.is_null()&&row.get("whole_native_model_sha256").is_null(),"ClassHierarchy boundary has no partial Model");return {};}
    class481_require(class481_text(row.get("whole_native_model_sha256"),work,64)==pin.model,"ClassHierarchy exact source Model authority");
    const auto encoded=class481_canonical(meaning,work);work.spend(encoded.size()*4u+128u);
    class481_require(digest(encoded)==pin.model,"ClassHierarchy complete Model canonical digest");
    return class481_model(meaning,work,true);
}
