TEST(MermaidClassHierarchyFlag, WholeSourceModelsAndFiniteBoundariesStayBound){
    Work setup;const auto document=class_hierarchy_document(setup);int positives=0,boundaries=0;
    for(std::size_t n=0;n<37u;++n){Work work;work.spend(kClassHierarchyPins[n].name.size()*4u+128u);SCOPED_TRACE(std::string(kClassHierarchyPins[n].name));
        try{if(class_hierarchy_bind(document.root().get("cases").at(n),n,work))++positives;else ++boundaries;}catch(const std::exception& error){ADD_FAILURE()<<error.what();}}
    EXPECT_EQ(positives,17);EXPECT_EQ(boundaries,20);
    auto reject=[&](std::string_view expected,auto change){
        Work work;const auto row=document.root().get("cases").at(0);const auto encoded=class481_canonical(row,work);work.spend((encoded.size()+512u)*32u+8192u);
        json::JsonMutDoc altered;auto value=altered.raw_json(encoded);altered.set_root(value);change(value,altered);
        const auto raw=altered.to_string();work.spend(raw.size()*8u+4096u);const auto parsed=json::parse(raw);ASSERT_TRUE(parsed);bool rejected=false;
        try{static_cast<void>(class_hierarchy_bind(parsed->root(),0,work));}catch(const std::runtime_error& error){ASSERT_FALSE(class481_resource(error.what()))<<error.what();EXPECT_EQ(std::string_view(error.what()),expected);rejected=true;}EXPECT_TRUE(rejected);
    };
    reject("ClassHierarchy exact original ordinal",[](json::JsonMutVal row,json::JsonMutDoc&){row.set("ordinal",1);});
    reject("ClassHierarchy exact whole source authority",[](json::JsonMutVal row,json::JsonMutDoc&){row.set("source_authority_sha256",std::string(64,'0'));});
    reject("ClassHierarchy exact complete source",[](json::JsonMutVal row,json::JsonMutDoc&){row.set("source","classDiagram\nclass Different\n");row.set("source_sha256",digest("classDiagram\nclass Different\n"));row.set("source_utf8_bytes",29);});
    reject("ClassHierarchy source-owned disposition",[](json::JsonMutVal row,json::JsonMutDoc&){row.set("expected","whole_source_boundary");});
    reject("ClassHierarchy complete Model canonical digest",[](json::JsonMutVal row,json::JsonMutDoc&){row.get("whole_native_model").get("groups").at(0).set("label","Changed");});
    Work zero;zero.left=0;bool resource=false;try{static_cast<void>(class_hierarchy_document(zero));}catch(const std::runtime_error& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource)<<"Resource failure is not source/schema rejection credit";
}
TEST(MermaidClassHierarchyFlag, All37SourcesCaptureBeforeDecodeAndRequireCompleteDispositions){
    Work setup;const auto document=class_hierarchy_document(setup);setup.spend(32768u);json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    int observed=0,decoded=0,strong=0,closed=0,positive_fallbacks=0,geometry_errors=0,oracle_errors=0,observation_errors=0;
    for(std::size_t n=0;n<37u;++n){Work work;work.spend(131072u+kClassHierarchyPins[n].name.size()*4u+128u);SCOPED_TRACE(std::string(kClassHierarchyPins[n].name));
        const auto row=document.root().get("cases").at(n);auto item=root.make_obj();item.set("name",kClassHierarchyPins[n].name);std::vector<std::string> errors,observations;bool captured=false,good=false,done=false;std::string phase="all_five_public_captures_before_binding_and_decode";
        try{
            const auto source=class481_text(row.get("source"),work);const auto frames=class35_observe(source,work);captured=true;++observed;
            observations=official285_observations(frames,root,item,work);envelope22_stage3_ordinary_frames(frames,root,item,work);
            work.spend(source.size()*16u+8192u);item.set("complete_source",source);item.set("source_sha256",kClassHierarchyPins[n].source);
            phase="source_and_complete_Model_binding";const auto model=class_hierarchy_bind(row,n,work);
            if(!model){phase="whole_source_boundary";good=frames.wide==frames.ordinary&&frames.narrow==frames.small&&frames.restored==frames.ordinary&&observations.empty();if(good)++closed;else errors.emplace_back("ClassHierarchy unreviewed complete source profile was drawn or changed");}
            else{
                ++decoded;work.spend(8192u);item.add("complete_native_Model",report.copy_val(row.get("whole_native_model")));
                if(frames.wide==frames.ordinary){++positive_fallbacks;errors.emplace_back("ClassHierarchy full positive remains mandatory drawing");}
                else{phase="same_chosen_complete_geometry";const auto wide=validate_impl(frames.wide,*model,work);class481_no_resource(wide);errors.insert(errors.end(),wide.begin(),wide.end());
                    if(frames.narrow!=frames.small){const auto narrow=validate_impl(frames.narrow,*model,work);class481_no_resource(narrow);errors.insert(errors.end(),narrow.begin(),narrow.end());}
                    geometry_errors+=!errors.empty();good=errors.empty()&&observations.empty();
                    if(good){phase="meaningful_complete_Model_mutations";const auto changes=class481_mutations(frames.wide,*model,work,nullptr,true);work.spend((changes.executed.size()+changes.skipped.size())*512u+8192u);class35_counts(root,item,changes);errors.insert(errors.end(),changes.errors.begin(),changes.errors.end());done=changes.errors.empty();if(done)++strong;}
                }
            }
        }catch(const std::exception& error){++oracle_errors;errors.emplace_back(phase+": "+error.what());}
        observation_errors+=!observations.empty();item.set("public_observed_before_decode",captured);item.set("phase",phase);item.set("good_before_mutants",good);item.set("mutations_completed",done);item.set("mandatory_native_contract_met",good&&(!kClassHierarchyPins[n].positive||done));item.set("work_remaining",static_cast<std::int64_t>(work.left));class35_errors(root,item,errors,observations);records.append(item);
    }
    root.set("qualification","All four unchanged official sources plus thirteen source-authored whole Models remain mandatory; twenty finite boundaries preserve whole source. Source/geometry/resource/protocol domains are separate. No original285/policy/API/SVG/font/layout assertion graduation. Same cumulative source Work pays captures/bind/wide/drawn narrow; each established mutation assertion has its own paid oracle scope.");root.set("source_design_lock_sha256","5f51aa9e884d451645ba4a9bf1f2ca56ccf887eaefe11b3e6ec41920a1811815");root.set("independent_source_review_sha256","b5a22fba2dfa5c4e6baf67eb18d8304b5f99dc3019f87bd4e1f83486391790bb");root.set("public_observations",observed);root.set("complete_Models_decoded",decoded);root.set("strong_complete_sources",strong);root.set("whole_source_boundaries",closed);root.set("positive_fallbacks",positive_fallbacks);root.set("geometry_errors",geometry_errors);root.set("oracle_or_protocol_or_resource_errors",oracle_errors);root.set("observation_errors",observation_errors);root.set("fixture_sha256",kClassHierarchySha);root.add("cases",records);report.set_root(root);state85_write("mermaid-class-hierarchical-namespaces-controls.json",report);
    EXPECT_EQ(observed,37);EXPECT_EQ(decoded,17);EXPECT_EQ(strong,17);EXPECT_EQ(closed,20);EXPECT_EQ(positive_fallbacks,0);EXPECT_EQ(geometry_errors,0);EXPECT_EQ(oracle_errors,0);EXPECT_EQ(observation_errors,0);
}

