                for(const auto* frame:{&frames.wide,&frames.ordinary,&frames.narrow,&frames.small,&frames.restored}){work.spend(frame->cells.size()+128u);for(const auto& cell:frame->cells)work.spend(cell.size()*12u+16u);}
