Grid stage_b_paper(Work& work,std::string_view token,bool footer){
    work.spend(40u*6u*(3u*sizeof(std::string)+16u)+3u*64u*(4u*sizeof(std::string)+32u)+4096u);
    Grid whole{40,6,std::vector<std::string>(240u," ")};
    const auto original=arrow_scene();
    for(int y=0;y<original.height;++y)for(int x=0;x<original.width;++x){
        const auto& cell=original.cells[static_cast<std::size_t>(original.index({x,y}))];work.spend(cell.size()*2u+4u);whole.put({x,y},cell);
    }
    if(footer)for(std::size_t n=0;n<token.size();++n){work.spend(2u*sizeof(std::string)+16u);whole.put({2+static_cast<int>(n),4},std::string(1,token[n]));}
    return whole;
}
Grid stage_b_paid_copy(const Grid& original,Work& work){
    work.spend(4u*sizeof(Grid)+128u);
    for(const auto& cell:original.cells){work.spend(cell.size()*2u+2u);}
    work.spend(original.cells.size()*(3u*sizeof(std::string)+8u));
    return original;
}
TEST(MermaidRelationsFollowingProtocol, WholeSceneFollowingRoleKeepsMocksBusinessAndOrphansDistinct){
    namespace oracle=loom::test::mermaid_relations;
    try{
        {
            Work original_work;
            original_work.spend(16u*sizeof(Model)+16u*sizeof(Entity)+16u*sizeof(Relation)+3u*64u*(4u*sizeof(std::string)+32u)+4096u);
            const auto original=arrow_scene();const auto model=basic_relation();
            original_work.spend(4u*sizeof(std::optional<int>));std::optional<int> row{0};
            const auto errors=validate_impl(original,model,original_work,false,nullptr,false,nullptr,oracle::kRelationsFollowingToken,&row);
            ASSERT_TRUE(errors.empty())<<explain(errors);
            EXPECT_FALSE(row.has_value());
        }
        for(const std::string_view token:{oracle::kRelationsFollowingToken,std::string_view{"AFTER_MERMAID"}}){
            Work good;
            good.spend(16u*sizeof(Model)+16u*sizeof(Entity)+16u*sizeof(Relation)+4096u+4u*sizeof(std::optional<int>));
            const auto model=basic_relation();
            const auto whole=stage_b_paper(good,token,true);
            std::optional<int> evidence;
            const auto errors=validate_impl(whole,model,good,false,nullptr,false,nullptr,token,&evidence);
            ASSERT_TRUE(errors.empty())<<explain(errors);
            ASSERT_EQ(evidence,std::optional<int>{4});
            EXPECT_EQ(oracle::following_row(whole,good,token),evidence);
            const auto nofooter=stage_b_paper(good,token,false);
            const auto nofooter_errors=validate_impl(nofooter,model,good,false,nullptr,false,nullptr,token,&evidence);
            ASSERT_TRUE(nofooter_errors.empty())<<explain(nofooter_errors);
            EXPECT_FALSE(evidence.has_value());
            auto reject=[&](const auto& mutate){
                Work negative;auto changed=stage_b_paid_copy(whole,negative);mutate(changed,negative);
                negative.spend(4u*sizeof(std::optional<int>));std::optional<int> ignored;
                const auto rejected=validate_impl(changed,model,negative,false,nullptr,false,nullptr,token,&ignored);
                class481_no_resource(rejected);
                EXPECT_FALSE(rejected.empty())<<"Extra/packed/split physical ink must not obtain a footer role";
            };
            reject([&](Grid& bad,Work& work){for(std::size_t n=0;n<token.size();++n){work.spend(2u*sizeof(std::string)+16u);bad.put({2+static_cast<int>(n),3},std::string(1,token[n]));}});
            reject([&](Grid& bad,Work& work){work.spend(token.size()*2u+4u*sizeof(std::string)+64u);bad.put({39,3},std::string(token));});
            reject([&](Grid& bad,Work& work){work.spend(40u*(sizeof(std::string)+8u)+token.size()*2u);for(int x=0;x<40;++x)bad.put({x,4}," ");bad.put({2,4},std::string(token));});
            reject([&](Grid& bad,Work& work){work.spend(40u*(sizeof(std::string)+8u)+token.size()*32u);for(int x=0;x<40;++x)bad.put({x,4}," ");for(std::size_t n=0;n<token.size();++n)bad.put({2+static_cast<int>(n)+(n>=5u?1:0),4},std::string(1,token[n]));bad.put({7,4},"");});
            reject([](Grid& bad,Work& work){work.spend(64u);bad.put({2,4},"?");});
            reject([](Grid& bad,Work& work){work.spend(64u);bad.put({39,4},"");});
            reject([](Grid& bad,Work& work){work.spend(64u);bad.put({0,5},"");});
            // Failure and exhaustion never certify an old output value.
            Work failed;auto wrong=stage_b_paid_copy(whole,failed);failed.spend(64u);wrong.put({0,3},"x");
            failed.spend(4u*sizeof(std::optional<int>));std::optional<int> stale{4};
            const auto failed_errors=validate_impl(wrong,model,failed,false,nullptr,false,nullptr,token,&stale);
            class481_no_resource(failed_errors);EXPECT_FALSE(failed_errors.empty());
            Work zero;zero.left=0;
            EXPECT_THROW(static_cast<void>(validate_impl(whole,model,zero,false,nullptr,false,nullptr,token,&stale)),std::runtime_error);
            EXPECT_THROW(static_cast<void>(oracle::following_row(whole,zero,token)),std::runtime_error);
            Work wrong_token;
            const auto wrong_token_errors=validate_impl(whole,model,wrong_token,false,nullptr,false,nullptr,"OTHER_TOKEN");
            class481_no_resource(wrong_token_errors);EXPECT_FALSE(wrong_token_errors.empty());
            EXPECT_GT(wrong_token.left,0u);
            Work invalid;
            EXPECT_THROW(static_cast<void>(oracle::following_row(whole,invalid,"")),std::runtime_error);
            EXPECT_THROW(static_cast<void>(oracle::following_row(whole,invalid,"HAS SPACE")),std::runtime_error);
            EXPECT_GT(invalid.left,0u);
        }
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}
}
