void class_notes18_paper_binding(JsonVal paper,std::size_t n,Work& work){
    class481_require(n<kClassNotes18PaperPins.size(),"ClassNotes18 paper ordinal");
    class481_require(digest(class481_canonical(paper,work))==kClassNotes18PaperPins[n],"ClassNotes18 immutable full paper/source/Model/cells binding");
    const auto source=class481_text(paper.get("source"),work,2048u);work.spend(source.size()*3u+128u);
    class481_require(digest(source)==paper.get("source_sha256").as_str()&&digest(class481_canonical(paper.get("whole_Model"),work))==paper.get("whole_Model_sha256").as_str(),"ClassNotes18 complete paper source and Model digest");
}
Grid class_notes18_literal_grid(JsonVal paper,Work& work){
    class481_require(paper.get("width").is_int()&&paper.get("height").is_int(),"ClassNotes18 literal dimensions types");
    const int width=static_cast<int>(paper.get_int("width")),height=static_cast<int>(paper.get_int("height"));
    class481_require(width>0&&width<=240&&height>0&&height<=1040,"ClassNotes18 literal dimensions bounds");
    const auto cells=paper.get("cells");class481_require(cells.is_arr()&&cells.size()==static_cast<std::size_t>(height),"ClassNotes18 literal rows");
    const auto count=static_cast<std::size_t>(width)*static_cast<std::size_t>(height);work.spend(sizeof(Grid)+count*(sizeof(std::string)+8u)+256u);
    Grid out{width,height,{}};out.cells.reserve(count);
    for(int y=0;y<height;++y){work.spend(static_cast<std::size_t>(y)+1u);const auto row=cells.at(static_cast<std::size_t>(y));class481_require(row.is_arr()&&row.size()==static_cast<std::size_t>(width),"ClassNotes18 exact physical row width");
        for(int x=0;x<width;++x){work.spend(static_cast<std::size_t>(x)+1u);const auto value=class481_text(row.at(static_cast<std::size_t>(x)),work,16u);work.spend(value.size()*4u+sizeof(std::string)+8u);out.cells.emplace_back(value);}}
    return out;
}
// Notes18 same-source binding is shared by the private header.
Class481Mutations class_notes18_mutations(const Grid& good,const Model& model,const ClassPresentation& presentation,Work& enumeration){
    enumeration.spend(16384u+model.notes.size()*512u);Class481Mutations out;
    auto reject=[&](std::string_view kind,auto change){
        enumeration.spend(kind.size()*4u+512u);Work negative;
        const auto baseline=validate_impl(good,model,negative,false,&presentation);class481_no_resource(baseline);class481_require(baseline.empty(),"ClassNotes18 mutation baseline must be complete good");
        static_cast<void>(class481_copy_charge(model,negative));auto wrong=model;negative.spend(4096u+model.notes.size()*sizeof(Note));change(wrong);
        const auto errors=validate_impl(good,wrong,negative,false,&presentation);class481_no_resource(errors);
        for(const auto& error:errors)class481_require(error!="Class Note attached to another family"&&error!="Unknown Class Note owner"&&error!="Unknown linked Class Note target/mode"&&error!="Standalone Note has target"&&error!="Class Note literal text domain","ClassNotes18 schema failure is not semantic rejection");
        ++out.executed[std::string(kind)];if(errors.empty())out.errors.emplace_back("Accepted ClassNotes18 semantic adversary: "+std::string(kind));
    };
    for(std::size_t n=0;n<model.notes.size();++n){
        reject("note_text",[&](Model& wrong){wrong.notes[n].text=wrong.notes[n].text=="X"?"Y":"X";});
        reject("note_erasure",[&](Model& wrong){wrong.notes.erase(wrong.notes.begin()+static_cast<std::ptrdiff_t>(n));});
        if(!model.groups.empty())reject("note_ownership",[&](Model& wrong){wrong.notes[n].owner=wrong.notes[n].owner.empty()?wrong.groups.front().id:std::string{};});
        else{enumeration.spend(512u);++out.skipped["no_independent_namespace_owner"];}
        if(model.notes[n].position=="linked"){
            const auto own=std::ranges::find_if(model.entities,[&](const Entity& e){enumeration.spend(e.id.size()+model.notes[n].target.size()+4u);return e.id==model.notes[n].target;});
            const auto other=std::ranges::find_if(model.entities,[&](const Entity& e){enumeration.spend(e.id.size()+e.label.size()+32u);return own!=model.entities.end()&&e.id!=own->id&&e.label!=own->label;});
            if(other!=model.entities.end())reject("note_target",[&](Model& wrong){wrong.notes[n].target=other->id;});
            else{enumeration.spend(512u);++out.skipped["no_visible_distinct_target"];}
        }
    }return out;
}
