                phase="complete_Model_decode_after_five_captures";const auto model=class481_model(row.get("whole_Model"),work);ready=true;++decoded;
                if(frames.wide==frames.ordinary){mandatory_fallback=true;++mandatory_fallbacks;phase="mandatory_source_drawing_unmet";}
