                if(frames.narrow!=frames.small){phase="complete_drawn_narrow_geometry";const auto narrow=class_notes18_drawn(frames.narrow,model,presentation,work);class481_require(narrow.empty(),narrow.empty()?std::string_view{}:std::string_view(narrow.front()));}
