TEST(MermaidErSingleSelfBT, ShortAndLongWholeSourcesKeepEveryRoleAndRecovery){
    Work setup;setup.spend(65536u+8u*sizeof(json::JsonMutDoc)+16u*sizeof(std::string)+4096u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    int observed=0,published=0,bound=0,decoded=0,strong=0,fallbacks=0,resources=0,protocol=0,geometry=0,mutation=0,observation=0;
    for(const auto& literal:kErSingleSelfBTLiterals){
        Work work{kEr206SceneLimit};
        // This source-local reserve owns bounded final error publication even
        // if capture/geometry later exhausts the same public128M ledger.
        work.spend(131072u+literal.source.size()*32u+literal.model_json.size()*32u+
            8u*sizeof(Class35Frames)+8u*sizeof(Class481Mutations)+16u*sizeof(std::vector<std::string>)+64u*sizeof(std::string)+8192u);
        auto item=root.make_obj();std::vector<std::string> errors,observations;errors.reserve(6u);
        item.set("name",literal.name);item.set("source",literal.source);item.set("expected","complete_whole_ER_BT_scene");
        item.set("source_sha256",literal.source_sha);item.set("complete_Model_sha256",literal.model_sha);
        bool captured=false,frames_published=false,source_bound=false,model_decoded=false,good=false,complete=false;
        std::string_view phase="five_public_views_before_source_Model_binding";
        auto fail=[&](std::string_view text){if(errors.size()<6u)errors.emplace_back(text.substr(0u,128u));};
        try{
            auto frames=er206_observe(literal.source,work);captured=true;++observed;
            const auto N=frames.wide.cells.size()+frames.ordinary.cells.size()+frames.narrow.cells.size()+frames.small.cells.size()+frames.restored.cells.size();
            work.spend(N*16u+65536u);
            observations=official285_observations(frames,root,item,work);
            official285_publish_frame(frames.ordinary,"ordinary_wide_frame",root,item,work);
            official285_publish_frame(frames.small,"ordinary_narrow_frame",root,item,work);frames_published=true;++published;
            class481_require(class481_sentinel(frames.ordinary,work)&&class481_sentinel(frames.small,work),"ER BT ordinary following spelling");
            phase="literal_full_source_and_Model_binding";
            work.spend(literal.source.size()*8u+literal.model_json.size()*8u+8192u);
            class481_require(digest(literal.source)==literal.source_sha&&digest(literal.model_json)==literal.model_sha,"ER BT complete literal source/Model SHA");
            source_bound=true;++bound;
            // Own the immutable JSON parse and the existing typed decoder's
            // full finite object/vector/string payload allocation before use.
            work.spend(literal.model_json.size()*131u+8u*sizeof(json::JsonDoc)+
                8u*sizeof(Model)+64u*sizeof(Entity)+64u*sizeof(ErTableSpec)+128u*sizeof(ErTableAttribute)+
                128u*sizeof(Relation)+64u*sizeof(Group)+512u*sizeof(std::string)+512u*sizeof(std::vector<std::string>)+65536u);
            const auto document=json::parse(literal.model_json);class481_require(document.has_value(),"ER BT complete literal Model JSON");
            class481_keys(document->root(),{"direction","entities","family","groups","notes","relations"},work);
            const auto encoded=class481_canonical(document->root(),work);
            class481_require(encoded==literal.model_json&&digest(encoded)==literal.model_sha,"ER BT exact complete canonical Model");
            const auto model=er296_typed_model(document->root(),work);
            class481_require(model.family=="er"&&model.direction=="BT"&&model.entities.size()==4u&&model.relations.size()==2u&&model.groups.empty()&&model.notes.empty(),"ER BT full four-entity two-edge profile");
            model_decoded=true;++decoded;item.add("complete_Model",report.raw_json(literal.model_json));
            if(!observations.empty()){++observation;for(const auto& text:observations)fail(text);}
            if(frames.wide==frames.ordinary){++fallbacks;fail("ER BT complete source remains mandatory whole-source drawing");}
            else{
                auto check=[&](const Grid& grid,std::string_view at){
                    phase=at;std::optional<int> footer;
                    const auto found=validate_impl(grid,model,work,false,nullptr,false,nullptr,
                        loom::test::mermaid_relations::kRelationsFollowingToken,&footer);
                    er_rich13_geometry_result(found);
                    for(const auto& text:found)fail(text);
                    if(found.empty())class481_require(footer.has_value(),"ER BT successful complete scene lacks unclaimed semantic footer role");
                    return found.empty()&&footer.has_value();
                };
                const bool wide=check(frames.wide,"whole_wide_geometry");item.set("wide_semantic_role",wide);
                bool narrow=false;
                if(frames.narrow==frames.small){
                    phase="exact_narrow_ordinary_protocol";
                    narrow=loom::test::mermaid_relations::following_row(frames.narrow,work).has_value();
                    class481_require(narrow,"ER BT exact ordinary narrow following protocol");item.set("narrow_exact_ordinary",true);
                }else{narrow=check(frames.narrow,"whole_drawn_narrow_geometry");item.set("narrow_semantic_role",narrow);}
                const bool restored=check(frames.restored,"whole_restored_geometry");item.set("restored_semantic_role",restored);
                if(!class481_same_grid(frames.wide,frames.restored,work))fail("ER BT same Node240/40/240 restoration differs");
                good=wide&&narrow&&restored&&errors.empty()&&observations.empty();
                if(!good)++geometry;
                if(good){
                    phase="complete_coherent_ER_mutants";
                    const auto changes=er206_mutations(frames.wide,model,literal.model_json.size(),work);
                    work.spend((changes.executed.size()+changes.skipped.size())*1024u+8192u);class35_counts(root,item,changes);
                    for(const auto& text:changes.errors)fail(text);
                    class481_require(!changes.executed.empty(),"ER BT meaningful semantic/physical mutants missing");
                    if(errors.empty()){complete=true;++strong;}else ++mutation;
                }
            }
        }catch(const std::exception& error){
            const char* text=error.what();std::size_t n=0;while(text&&n<128u&&text[n])++n;
            const std::string_view message=text?std::string_view(text,n):std::string_view("ER BT unknown exception");
            if(work.left==0u||class481_resource(message))++resources;
            else if(phase=="complete_coherent_ER_mutants")++mutation;else ++protocol;
            fail(message);
        }
        // All payloads here use the source-local pregeometry reserve.
        item.set("five_captures_complete",captured);item.set("five_frames_published",frames_published);
        item.set("source_bound",source_bound);item.set("complete_Model_decoded",model_decoded);
        item.set("good_before_mutants",good);item.set("complete_native_scene_strong",complete);
        item.set("phase",phase);item.set("work_remaining",static_cast<std::int64_t>(work.left));
        item.set("foreign_assertions_certified",0);item.set("formal_admission",false);class35_errors(root,item,errors,observations);records.append(item);
    }
    root.set("source_count",2);root.set("five_captures_complete",observed);root.set("all_five_frames_published",published);
    root.set("complete_source_bindings",bound);root.set("complete_Models_decoded",decoded);root.set("strong_complete_scenes",strong);
    root.set("mandatory_positive_fallbacks",fallbacks);root.set("resource_errors",resources);root.set("protocol_errors",protocol);
    root.set("geometry_errors",geometry);root.set("mutation_errors",mutation);root.set("observation_errors",observation);
    root.set("public_scene_limit",static_cast<std::int64_t>(kEr206SceneLimit));root.set("old_default8M_unchanged",true);
    root.set("production1M_unchanged",true);root.set("foreign_assertions_certified",0);root.set("formal_admissions",0);
    root.set("sizeof_Pixel",static_cast<std::int64_t>(sizeof(ftxui::Pixel)));root.set("sizeof_Pixel_row",static_cast<std::int64_t>(sizeof(std::vector<ftxui::Pixel>)));
    root.set("sizeof_string",static_cast<std::int64_t>(sizeof(std::string)));root.add("cases",records);report.set_root(root);
    state85_write("mermaid-er-single-self-bt-two-sources.json",report);
    EXPECT_EQ(observed,2);EXPECT_EQ(published,2);EXPECT_EQ(bound,2);EXPECT_EQ(decoded,2);EXPECT_EQ(strong,2);
    EXPECT_EQ(fallbacks,0);EXPECT_EQ(resources,0);EXPECT_EQ(protocol,0);EXPECT_EQ(geometry,0);EXPECT_EQ(mutation,0);EXPECT_EQ(observation,0);
}
