// ER Stage2 test-private explicit-token/same-ledger closure only. Source/Model
// literals are authored from the pinned ER grammar and DB, never a live frame.
namespace {
namespace er_stage2_core=loom::test::mermaid_relations;
constexpr std::size_t kErStage2SceneLimit=128000000u;
constexpr std::string_view kErStage2Token="AFTER_MERMAID";
constexpr std::string_view kErStage2Source="erDiagram\nAFTER_MERMAID {\n string AFTER_MERMAID PK \"kept\"\n}\nAFTER_MERMAID ||--o{ B : owns\nB { int id PK }\n";
constexpr std::string_view kErStage2Model=R"ERPAID({"direction":"TB","entities":[{"headers":[["AFTER_MERMAID"]],"id":"AFTER_MERMAID","label":"AFTER_MERMAID","owner":"","rows":[{"alternatives":["string AFTER_MERMAID PK \"kept\""],"role":"attribute","source_fields":{"comment":"kept","keys":["PK"],"name":"AFTER_MERMAID","type":"string"}}],"shape":"box"},{"headers":[["B"]],"id":"B","label":"B","owner":"","rows":[{"alternatives":["int id PK"],"role":"attribute","source_fields":{"comment":"","keys":["PK"],"name":"id","type":"int"}}],"shape":"box"}],"family":"er","groups":[],"notes":[],"relations":[{"end":"card:zero-many","label":"owns","order":0,"source":"AFTER_MERMAID","start":"card:one","stroke":"solid","target":"B"}]})ERPAID";
constexpr std::string_view kErStage2SourceSha="6fb93654dfec12d10535649b5e54ef76383127e6602e6770e75ecb46221b37b7";
constexpr std::string_view kErStage2ModelSha="1876b321c6e59e681c0cab5b883a0f5d9837b49957418ae88e9f8ce104b421ca";
Class35Frames er_stage2_observe(std::string_view input,Work& work){
    work.spend((input.size()+kErStage2Token.size()+128u)*(32u*sizeof(std::string)+256u)+8192u);
    auto fence=[&](std::string_view language){return "```"+std::string(language)+'\n'+std::string(input)+"\n```\n\n"+std::string(kErStage2Token);};
    const auto node=loom::ui::render_markdown(fence("mermaid")),plain=loom::ui::render_markdown(fence("text"));
    node->ComputeRequirement();plain->ComputeRequirement();
    const int required=std::max({1,node->requirement().min_y,plain->requirement().min_y});
    er_present_require(required<1040,"ER Stage2 complete capture viewport limit exceeded");const int height=required+1;
    return {note13_capture(node,240,height,work),note13_capture(plain,240,height,work),note13_capture(node,40,height,work),note13_capture(plain,40,height,work),note13_capture(node,240,height,work)};
}
void er_stage2_resource_result(const std::vector<std::string>& errors,Work& work){
    work.spend(errors.size()*512u+128u);
    for(const auto& error:errors){work.spend(error.size()*2u+128u);if(class481_resource(error))throw std::runtime_error("ER Stage2 resource is not semantic rejection: "+error);}
}
std::vector<std::string> er_stage2_scene(const Grid& grid,const Model& model,Work& work,std::optional<int>* row=nullptr){
    work.spend(8u*sizeof(std::optional<int>)+256u);
    const auto physical=er_stage2_core::following_row(grid,work,kErStage2Token);
    er_present_require(physical.has_value(),"ER Stage2 physical following row");
    std::optional<int> semantic;
    auto errors=validate_impl(grid,model,work,false,nullptr,false,nullptr,kErStage2Token,&semantic);
    er_stage2_resource_result(errors,work);
    if(errors.empty()){er_present_require(semantic.has_value()&&semantic==physical,"ER Stage2 successful semantic following role");if(row)*row=semantic;}
    return errors;
}
void er_stage2_copy_charge(const Grid& grid,Work& work){
    work.spend(3u*sizeof(Grid)+grid.cells.size()*(3u*sizeof(std::string)+16u)+256u);
    for(const auto& cell:grid.cells)work.spend(cell.size()*2u+1u);
}
} // namespace
