        official285_publish_frame(frames.narrow,"narrow_frame",root,root,work);official285_publish_frame(frames.small,"ordinary_narrow_frame",root,root,work);official285_publish_frame(frames.restored,"restored_frame",root,root,work);published=true;
        phase="literal_full_source_and_typed_Model_binding";
        work.spend(kErStage2Source.size()*8u+kErStage2Model.size()*131u+8u*sizeof(json::JsonDoc)+8u*sizeof(Model)+64u*sizeof(Entity)+64u*sizeof(ErTableSpec)+128u*sizeof(ErTableAttribute)+128u*sizeof(Relation)+64u*sizeof(Group)+512u*sizeof(std::string)+512u*sizeof(std::vector<std::string>)+65536u);
