TEST(MermaidErSubgraphSourceProfile, CompleteOwnershipTitlesTypedMembersAndRecovery){
    Work setup;setup.spend(131072u+8u*sizeof(json::JsonMutDoc)+32u*sizeof(std::string)+8192u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    int observed=0,published=0,bound=0,decoded=0,strong=0,malformed_closed=0,unsupported_observed=0;
    int fallbacks=0,resources=0,protocol=0,geometry=0,mutation=0,observation=0;
    for(const auto& literal:kErSubgraphLiterals){
        Work work{kEr206SceneLimit};
        work.spend(262144u+literal.source.size()*32u+literal.model_json.size()*32u+
            8u*sizeof(Class35Frames)+8u*sizeof(Class481Mutations)+32u*sizeof(std::vector<std::string>)+128u*sizeof(std::string)+16384u);
        auto item=root.make_obj();std::vector<std::string> errors,observations;errors.reserve(8u);
        item.set("name",literal.name);item.set("source",literal.source);item.set("source_sha256",literal.source_sha);
        item.set("profile",literal.profile);item.set("complete_Model_sha256",literal.model_sha);
        const bool positive=literal.profile=="mandatory_complete_positive";
        bool captured=false,pub=false,source_bound=false,model_decoded=false,good=false,strong_scene=false,closed_protocol=false;
        std::string_view phase="five_public_captures_before_binding";
        auto fail=[&](std::string_view text){if(errors.size()<8u)errors.emplace_back(text.substr(0u,128u));};
        try{
            auto frames=er206_observe(literal.source,work);captured=true;++observed;
            const auto N=frames.wide.cells.size()+frames.ordinary.cells.size()+frames.narrow.cells.size()+frames.small.cells.size()+frames.restored.cells.size();
            work.spend(N*16u+65536u);
            observations=official285_observations(frames,root,item,work);
            official285_publish_frame(frames.ordinary,"ordinary_wide_frame",root,item,work);
            official285_publish_frame(frames.small,"ordinary_narrow_frame",root,item,work);pub=true;++published;
            class481_require(class481_sentinel(frames.ordinary,work)&&class481_sentinel(frames.small,work),"ER subgraph ordinary following spelling");
            phase="compiled_complete_source_Model_binding";
            work.spend(literal.source.size()*8u+literal.model_json.size()*8u+8192u);
            class481_require(digest(literal.source)==literal.source_sha,"ER subgraph complete source literal SHA");source_bound=true;++bound;
            if(!observations.empty()){++observation;for(const auto& text:observations)fail(text);}
            if(!positive){
                phase="whole_closed_profile_protocol";
                class481_require(literal.model_json.empty()&&literal.model_sha.empty()&&literal.executed.empty()&&literal.skipped.empty(),"ER subgraph closed source acquired invented Model");
                const bool wide=class481_same_grid(frames.wide,frames.ordinary,work);
                const bool narrow=class481_same_grid(frames.narrow,frames.small,work);
                const bool restored=class481_same_grid(frames.restored,frames.ordinary,work);
                closed_protocol=wide&&narrow&&restored&&errors.empty();
                if(closed_protocol){if(literal.profile=="malformed_source")++malformed_closed;else ++unsupported_observed;}
                else{++geometry;fail("ER subgraph closed source drew a partial scene or failed ordinary recovery");}
            }else{
                work.spend(literal.model_json.size()*131u+8u*sizeof(json::JsonDoc)+8u*sizeof(Model)+64u*sizeof(Entity)+
                    64u*sizeof(ErTableSpec)+128u*sizeof(ErTableAttribute)+128u*sizeof(Relation)+64u*sizeof(Group)+
                    512u*sizeof(std::string)+512u*sizeof(std::vector<std::string>)+65536u);
                class481_require(digest(literal.model_json)==literal.model_sha,"ER subgraph literal complete Model SHA");
                const auto document=json::parse(literal.model_json);class481_require(document.has_value(),"ER subgraph complete literal Model JSON");
                class481_keys(document->root(),{"direction","entities","family","groups","notes","relations"},work);
                const auto encoded=class481_canonical(document->root(),work);
                class481_require(encoded==literal.model_json&&digest(encoded)==literal.model_sha,"ER subgraph exact complete Model canonical binding");
                const auto model=er296_typed_model(document->root(),work);class481_require(model.family=="er"&&!model.groups.empty()&&model.notes.empty(),"ER subgraph complete ER Group profile");
                model_decoded=true;++decoded;item.add("complete_Model",report.raw_json(literal.model_json));
                if(frames.wide==frames.ordinary){++fallbacks;fail("ER subgraph mandatory complete source remains fallback");}
                else{
                    auto check=[&](const Grid& grid,std::string_view at){
                        phase=at;std::optional<int> footer;
                        const auto found=validate_impl(grid,model,work,false,nullptr,false,nullptr,
                            loom::test::mermaid_relations::kRelationsFollowingToken,&footer);
                        er_rich13_geometry_result(found);for(const auto& text:found)fail(text);
                        if(found.empty())class481_require(footer.has_value(),"ER subgraph complete scene lacks semantic following role");
                        return found.empty()&&footer.has_value();
                    };
                    const bool wide=check(frames.wide,"complete_wide_geometry");item.set("wide_semantic_role",wide);
                    bool narrow=false;
                    if(frames.narrow==frames.small){phase="exact_ordinary_narrow";narrow=loom::test::mermaid_relations::following_row(frames.narrow,work).has_value();class481_require(narrow,"ER subgraph ordinary narrow following protocol");item.set("narrow_exact_ordinary",true);}
                    else{narrow=check(frames.narrow,"complete_narrow_geometry");item.set("narrow_semantic_role",narrow);}
                    const bool restored=check(frames.restored,"complete_restored_geometry");item.set("restored_semantic_role",restored);
                    if(!class481_same_grid(frames.wide,frames.restored,work))fail("ER subgraph same Node240/40/240 restoration differs");
                    good=wide&&narrow&&restored&&errors.empty();
                    if(!good)++geometry;
                    if(good){
                        phase="complete_coherent_group_ER_mutants";
                        const auto changes=er206_mutations(frames.wide,model,literal.model_json.size(),work);
                        work.spend((changes.executed.size()+changes.skipped.size())*1024u+8192u);class35_counts(root,item,changes);
                        for(const auto& text:changes.errors)fail(text);
                        work.spend(65536u+64u*sizeof(int)+64u*sizeof(std::string_view));
                        int semantic=0,physical=0;
                        class481_require(changes.executed.size()==literal.executed.size()&&changes.skipped.size()==literal.skipped.size(),"ER subgraph exact applicable mutation kind set differs");
                        for(const auto& expected:literal.executed){
                            const auto found=std::ranges::find_if(changes.executed,[&](const auto& entry){return std::string_view(entry.first)==expected.first;});
                            class481_require(found!=changes.executed.end()&&found->second==expected.second,"ER subgraph complete mutation count differs");
                            if(expected.first=="orphan_ink")physical+=found->second;else semantic+=found->second;
                        }
                        for(const auto& expected:literal.skipped){
                            const auto found=std::ranges::find_if(changes.skipped,[&](const auto& entry){return std::string_view(entry.first)==expected.first;});
                            class481_require(found!=changes.skipped.end()&&found->second==expected.second,"ER subgraph source-inapplicable mutation skip differs");
                        }
                        item.set("semantic_negative_count",semantic);item.set("shared_orphan_negative_count",physical);
                        class481_require(semantic==literal.semantic_count&&physical==1,"ER subgraph semantic coverage cannot be replaced by orphan ink");
                        int group_physical=0;
                        // Two independent legacy8M physical negatives. Their own
                        // actual Grid copies/locator/validation costs precede use.
                        for(const bool erase_header:{false,true}){
                            work.spend(8192u);
                            Work pixel;
                            pixel.spend(131072u+16u*128u*sizeof(Rect)+16u*128u*sizeof(std::string)+
                                16u*sizeof(std::vector<Rect>)+16u*sizeof(std::optional<Rect>)+8192u);
                            const auto rectangles=outlines(frames.wide,pixel);
                            std::optional<Rect> selected;int matches=0;
                            for(const auto& box:rectangles){
                                pixel.spend(8192u+8u*sizeof(std::string)+8u*sizeof(Rect));
                                if(box.shape!="box"||box.t+1>=box.b)continue;
                                std::string line;line.reserve(static_cast<std::size_t>(box.r-box.l));
                                for(int x=box.l+1;x<box.r;++x){pixel.spend(16u);line+=frames.wide.at({x,box.t+1});}
                                if(trim(std::move(line))==model.groups.front().label){selected=box;++matches;}
                            }
                            class481_require(matches==1&&selected.has_value(),"ER subgraph source Group needs unique physical header target");
                            Point target{selected->l,selected->t};
                            if(erase_header){
                                target={selected->l+1,selected->t+1};
                                while(target.x<selected->r&&frames.wide.at(target)==" "){pixel.spend(8u);++target.x;}
                                class481_require(target.x<selected->r,"ER subgraph complete header target absent");
                            }
                            class481_require(frames.wide.at(target)!=" ","ER subgraph physical mutation was not observable");
                            pixel.spend(frames.wide.cells.size()*2u*sizeof(std::string)+8u*sizeof(Grid)+4096u);
                            loom::test::mermaid_relations::class285_orphan_copy_prepay(frames.wide,pixel);
                            auto wrong=frames.wide;pixel.spend(8u*sizeof(std::string)+64u);wrong.put(target," ");
                            const auto rejected=validate_impl(wrong,model,pixel,false,nullptr,false,nullptr,
                                loom::test::mermaid_relations::kRelationsFollowingToken);
                            er_rich13_geometry_result(rejected);class481_require(!rejected.empty(),"ER subgraph physical Group header/corner loss accepted");++group_physical;
                        }
                        item.set("Group_physical_negative_count",group_physical);class481_require(group_physical==2,"ER subgraph Group physical checks incomplete");
                        if(errors.empty()){strong_scene=true;++strong;}else ++mutation;
                    }
                }
            }
        }catch(const std::exception& error){
            const char* text=error.what();std::size_t n=0;while(text&&n<128u&&text[n])++n;
            const std::string_view message=text?std::string_view(text,n):std::string_view("ER subgraph unknown exception");
            if(work.left==0u||class481_resource(message))++resources;
            else if(phase=="complete_coherent_group_ER_mutants")++mutation;else ++protocol;
            fail(message);
        }
        item.set("five_captures_complete",captured);item.set("five_frames_published",pub);item.set("source_bound",source_bound);item.set("complete_Model_decoded",model_decoded);
        item.set("good_before_mutants",good);item.set("strong_complete_scene",strong_scene);item.set("whole_closed_protocol_observed",closed_protocol);
        item.set("unsupported_obligation_satisfied",false);item.set("formal_admission",false);item.set("foreign_assertions_certified",0);
        item.set("phase",phase);item.set("work_remaining",static_cast<std::int64_t>(work.left));class35_errors(root,item,errors,observations);records.append(item);
    }
    root.set("source_count",16);root.set("mandatory_positive_sources",5);root.set("malformed_source_controls",4);root.set("valid_unimplemented_obligations",7);
    root.set("five_captures_complete",observed);root.set("all_five_frames_published",published);root.set("complete_source_bindings",bound);root.set("complete_Models_decoded",decoded);
    root.set("strong_complete_scenes",strong);root.set("malformed_whole_source_protocols",malformed_closed);root.set("unsupported_whole_source_protocols",unsupported_observed);
    root.set("mandatory_positive_fallbacks",fallbacks);root.set("resource_errors",resources);root.set("protocol_errors",protocol);root.set("geometry_errors",geometry);root.set("mutation_errors",mutation);root.set("observation_errors",observation);
    root.set("public_scene_limit",static_cast<std::int64_t>(kEr206SceneLimit));root.set("old_default8M_unchanged",true);root.set("production1M_unchanged",true);
    root.set("original_seven_Models_unchanged",true);root.set("formal_admissions",0);root.set("foreign_assertions_certified",0);
    root.set("sizeof_Pixel",static_cast<std::int64_t>(sizeof(ftxui::Pixel)));root.set("sizeof_Pixel_row",static_cast<std::int64_t>(sizeof(std::vector<ftxui::Pixel>)));root.set("sizeof_string",static_cast<std::int64_t>(sizeof(std::string)));
    root.add("cases",records);report.set_root(root);state85_write("mermaid-er-subgraph-sixteen-source-controls.json",report);
    EXPECT_EQ(observed,16);EXPECT_EQ(published,16);EXPECT_EQ(bound,16);EXPECT_EQ(decoded,5);EXPECT_EQ(strong,5);EXPECT_EQ(malformed_closed,4);EXPECT_EQ(unsupported_observed,7);
    EXPECT_EQ(fallbacks,0);EXPECT_EQ(resources,0);EXPECT_EQ(protocol,0);EXPECT_EQ(geometry,0);EXPECT_EQ(mutation,0);EXPECT_EQ(observation,0);
}

