// Only this finite caller accepts the source-cap partner65537. Its complete
// public acquisition is still exactly the existing paid capture primitive.
Class35Frames er_subgraph_boundary_observe(std::string_view source,Work& work){
    work.spend(8u*sizeof(std::size_t)+4u*sizeof(bool)+64u);
    class481_require(source.size()<=65537u,"ER subgraph boundary complete source range");
    work.spend((source.size()+128u)*(32u*sizeof(std::string)+256u)+8192u+8u*sizeof(Class35Frames)+8u*sizeof(int));
    const auto text=std::string(source);
    const auto node=loom::ui::render_markdown(fenced(text,"mermaid")),plain=loom::ui::render_markdown(fenced(text,"text"));
    node->ComputeRequirement();plain->ComputeRequirement();
    const int required=std::max({1,node->requirement().min_y,plain->requirement().min_y});
    class481_require(required<1040,"ER subgraph boundary complete viewport limit exceeded");
    const int height=required+1;
    return {note13_capture(node,240,height,work),note13_capture(plain,240,height,work),
        note13_capture(node,40,height,work),note13_capture(plain,40,height,work),note13_capture(node,240,height,work)};
}
TEST(MermaidErSubgraphResourceBoundaries, WholeFailureIsDistinctFromFitAndOracleBudget){
    Work setup;setup.spend(262144u+16u*sizeof(json::JsonMutDoc)+32u*sizeof(Work)+64u*sizeof(std::string)+8192u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    int captured_count=0,published_count=0,source_bound=0,models=0,above_closed=0,inbound_ordinary=0,inbound_geometry=0;
    int resources=0,protocol=0,geometry=0,observation=0,zero_guards=0;
    for(const auto& literal:kErSubgraphBoundaries){
        Work work{kEr206SceneLimit};
        work.spend(262144u+literal.source_bytes*32u+literal.model_json.size()*32u+
            16u*sizeof(Class35Frames)+32u*sizeof(std::vector<std::string>)+128u*sizeof(std::string)+16384u);
        // Avoid an overlength C++ string literal while retaining the exact
        // full65536/65537 source. This test-only builder is paid before reserve.
        std::string padding_source;std::string_view source=literal.source;
        if(literal.dimension=="source"){
            class481_require(literal.source_bytes>=literal.source.size()&&literal.source_bytes<=65537u,"ER subgraph padding byte bound");
            work.spend(literal.source_bytes*4u+4u*sizeof(std::string)+256u);
            padding_source.reserve(literal.source_bytes);padding_source=literal.source;
            padding_source.append(literal.source_bytes-literal.source.size(),'x');source=padding_source;
        }
        auto item=root.make_obj();std::vector<std::string> errors,observations;errors.reserve(8u);
        item.set("name",literal.name);item.set("dimension",literal.dimension);item.set("source",source);item.set("source_sha256",literal.source_sha);
        item.set("source_bytes",static_cast<std::int64_t>(source.size()));item.set("bound_value",static_cast<std::int64_t>(literal.value));item.set("above_bound",literal.above);
        item.set("credit",0);item.set("production_work_remaining","UNKNOWN_not_injected_or_read");
        bool captured=false,published=false,binding=false,decoded=false,safe=false,fit_unknown=false;
        std::string_view phase="five_public_captures_before_binding";
        auto fail=[&](std::string_view text){if(errors.size()<8u)errors.emplace_back(text.substr(0u,128u));};
        try{
            auto frames=er_subgraph_boundary_observe(source,work);captured=true;++captured_count;
            const auto N=frames.wide.cells.size()+frames.ordinary.cells.size()+frames.narrow.cells.size()+frames.small.cells.size()+frames.restored.cells.size();
            work.spend(N*16u+65536u);observations=official285_observations(frames,root,item,work);
            official285_publish_frame(frames.ordinary,"ordinary_wide_frame",root,item,work);
            official285_publish_frame(frames.small,"ordinary_narrow_frame",root,item,work);published=true;++published_count;
            if(!observations.empty()){++observation;for(const auto& text:observations)fail(text);}
            phase="strict_source_hash_and_actual_Markdown_code_owner";
            // At most two root blocks: the closed code fence and fixed following
            // paragraph. Source lines/strings and bounded BlockToken growth are
            // prepaid before constructing the extra ownership-only lexer input.
            work.spend(source.size()*64u+16u*sizeof(loom::ui::BlockToken)+64u*sizeof(std::string)+
                16u*sizeof(std::vector<loom::ui::BlockToken>)+65536u);
            const auto input=fenced(source,"mermaid");
            const auto blocks=loom::ui::detail::lex_blocks(input);
            class481_require(blocks.size()<=4u,"ER subgraph finite ownership block bound");int fences=0;
            for(const auto& block:blocks){
                work.spend(source.size()+1024u);
                if(block.kind!=loom::ui::BlockTokenKind::CodeBlock)continue;
                class481_require(block.code_lang=="mermaid"&&block.code_fence_closed&&block.code_content==source,
                    "ER subgraph complete raw source was changed by Markdown extraction");++fences;
            }
            work.spend(source.size()*8u+literal.model_json.size()*8u+8192u);
            class481_require(fences==1&&source.size()==literal.source_bytes&&digest(source)==literal.source_sha,"ER subgraph exact original byte boundary identity");binding=true;++source_bound;
            const bool wide_plain=class481_same_grid(frames.wide,frames.ordinary,work);
            const bool narrow_plain=class481_same_grid(frames.narrow,frames.small,work);
            const bool restored_plain=class481_same_grid(frames.restored,frames.ordinary,work);
            if(literal.above){
                phase="above_cap_mandatory_whole_ordinary_protocol";
                class481_require(literal.model_json.empty()&&literal.model_sha.empty(),"ER subgraph above-cap source acquired Model credit");
                safe=wide_plain&&narrow_plain&&restored_plain&&errors.empty();
                if(safe)++above_closed;else{++geometry;fail("ER subgraph above-cap source partially drew or did not fully recover ordinary source");}
            }else{
                phase="in_bound_complete_Model_binding";
                work.spend(literal.model_json.size()*131u+8u*sizeof(json::JsonDoc)+8u*sizeof(Model)+64u*sizeof(Entity)+
                    64u*sizeof(ErTableSpec)+128u*sizeof(ErTableAttribute)+128u*sizeof(Relation)+64u*sizeof(Group)+
                    1024u*sizeof(std::string)+1024u*sizeof(std::vector<std::string>)+131072u);
                class481_require(digest(literal.model_json)==literal.model_sha,"ER subgraph boundary complete Model SHA");
                const auto doc=json::parse(literal.model_json);class481_require(doc.has_value(),"ER subgraph boundary complete Model JSON");
                class481_keys(doc->root(),{"direction","entities","family","groups","notes","relations"},work);
                const auto canonical=class481_canonical(doc->root(),work);
                class481_require(canonical==literal.model_json&&digest(canonical)==literal.model_sha,"ER subgraph boundary canonical Model");
                const auto model=er296_typed_model(doc->root(),work);decoded=true;++models;item.add("complete_Model",report.raw_json(literal.model_json));
                if(wide_plain){
                    phase="in_bound_whole_ordinary_fit_UNKNOWN";fit_unknown=true;
                    safe=narrow_plain&&restored_plain&&errors.empty();
                    if(safe)++inbound_ordinary;else{++geometry;fail("ER subgraph in-bound fallback exposed a partial narrow/restored scene");}
                }else{
                    auto check=[&](const Grid& grid,std::string_view at){
                        phase=at;std::optional<int> footer;
                        const auto found=validate_impl(grid,model,work,false,nullptr,false,nullptr,
                            loom::test::mermaid_relations::kRelationsFollowingToken,&footer);
                        er_rich13_geometry_result(found);for(const auto& text:found)fail(text);
                        if(found.empty())class481_require(footer.has_value(),"ER subgraph boundary draw lacks semantic following role");
                        return found.empty()&&footer.has_value();
                    };
                    const bool wide=check(frames.wide,"in_bound_complete_wide_geometry");
                    bool narrow=false;
                    if(narrow_plain){narrow=loom::test::mermaid_relations::following_row(frames.narrow,work).has_value();class481_require(narrow,"ER subgraph boundary ordinary narrow following");}
                    else narrow=check(frames.narrow,"in_bound_complete_narrow_geometry");
                    const bool restored=check(frames.restored,"in_bound_complete_restored_geometry");
                    safe=wide&&narrow&&restored&&errors.empty()&&class481_same_grid(frames.wide,frames.restored,work);
                    if(safe)++inbound_geometry;else{++geometry;fail("ER subgraph in-bound draw or restoration lacks complete semantics");}
                }
            }
        }catch(const std::exception& error){
            const char* text=error.what();std::size_t n=0;while(text&&n<128u&&text[n])++n;
            const std::string_view message=text?std::string_view(text,n):std::string_view("ER subgraph boundary unknown error");
            if(work.left==0u||class481_resource(message)||message.find("limit exceeded")!=std::string_view::npos)++resources;else ++protocol;
            fail(message);
        }
        item.set("five_captures_complete",captured);item.set("five_frames_published",published);item.set("source_bound",binding);item.set("complete_Model_decoded",decoded);
        item.set("observed_all_or_nothing_safety",safe);item.set("in_bound_production_fit_UNKNOWN",fit_unknown);item.set("phase",phase);
        item.set("work_remaining",static_cast<std::int64_t>(work.left));item.set("formal_admission",false);item.set("foreign_assertions_certified",0);
        class35_errors(root,item,errors,observations);records.append(item);
    }
    // This independently declared zero ledger is ORACLE before-use evidence,
    // never injected productionWork or a claim that public production exhausted.
    setup.spend(65536u+8u*sizeof(ftxui::Element)+16u*sizeof(std::string)+8u*sizeof(Work));
    const auto element=ftxui::text("x");Work zero{0};bool exact_resource=false;
    try{static_cast<void>(note13_capture(element,1,1,zero));}
    catch(const std::exception& error){
        const char* text=error.what();std::size_t n=0;while(text&&n<128u&&text[n])++n;
        exact_resource=text&&n<128u&&std::string_view(text,n)=="Relation oracle work exhausted"&&zero.left==0u;
    }
    if(exact_resource)++zero_guards;
    root.set("source_cap_cases",10);root.set("five_captures_complete",captured_count);root.set("all_five_frames_published",published_count);root.set("exact_raw_source_bindings",source_bound);
    root.set("in_bound_Models_decoded",models);root.set("above_bound_whole_ordinary",above_closed);root.set("in_bound_ordinary_fit_UNKNOWN",inbound_ordinary);root.set("in_bound_complete_geometry_observed",inbound_geometry);
    root.set("oracle_zero_before_use_guard",zero_guards);root.set("oracle_resource_errors",resources);root.set("protocol_errors",protocol);root.set("geometry_errors",geometry);root.set("observation_errors",observation);
    root.set("group65_also_exceeds_combined64",true);root.set("no_internal_production_gate_attribution",true);root.set("in_bound_drawing_required",false);
    root.set("formal_admissions",0);root.set("drawing_coverage_credit",0);root.set("foreign_assertions_certified",0);root.set("public_scene_limit",static_cast<std::int64_t>(kEr206SceneLimit));
    root.set("old_default8M_unchanged",true);root.set("production1M_unchanged",true);root.set("sizeof_Pixel",static_cast<std::int64_t>(sizeof(ftxui::Pixel)));
    root.set("sizeof_Pixel_row",static_cast<std::int64_t>(sizeof(std::vector<ftxui::Pixel>)));root.set("sizeof_BlockToken",static_cast<std::int64_t>(sizeof(loom::ui::BlockToken)));
    root.add("cases",records);report.set_root(root);state85_write("mermaid-er-subgraph-resource-boundaries.json",report);
    EXPECT_EQ(captured_count,10);EXPECT_EQ(published_count,10);EXPECT_EQ(source_bound,10);EXPECT_EQ(models,5);EXPECT_EQ(above_closed,5);
    EXPECT_EQ(inbound_ordinary+inbound_geometry,5);EXPECT_EQ(zero_guards,1);EXPECT_EQ(resources,0);EXPECT_EQ(protocol,0);EXPECT_EQ(geometry,0);EXPECT_EQ(observation,0);
}
