                    bool narrow=false;
                    if(frames.narrow==frames.small){phase="exact_ordinary_narrow";narrow=loom::test::mermaid_relations::following_row(frames.narrow,work).has_value();class481_require(narrow,"ER Grouped lexical boundary ordinary narrow following protocol");item.set("narrow_exact_ordinary",true);}
                    else{narrow=check(frames.narrow,"complete_narrow_geometry");item.set("narrow_semantic_role",narrow);}
