                r11::require_rejected(frames.wide,scene,[](Grid& bad,const r11::Geometry& proof){const auto& p=proof.circles.front();bad.put(p.marker," ");bad.put(p.border,"⊕");},work,"Requirement11 circle perimeter mutant");
                r11::require_rejected(frames.wide,scene,[&](Grid& bad,const r11::Geometry& proof){const auto& p=proof.circles.front();for(const auto& edge:scene.edges)if(edge.kind==r11::EdgeKind::Contains){const int target=r11::scene_node(scene,edge.target);r11::need(target>=0,"Requirement11 circle target mutation");bad.put(p.marker," ");bad.put({proof.boxes[static_cast<std::size_t>(target)].l,proof.boxes[static_cast<std::size_t>(target)].t},"⊕");return;}r11::need(false,"Requirement11 circle target mutation edge");},work,"Requirement11 circle moved-to-target mutant");
                r11::require_rejected(frames.wide,scene,[&](Grid& bad,const r11::Geometry& proof){const auto& p=proof.circles.front();for(int d=0;d<4;++d)if(d!=p.exterior&&(d+2)%4!=p.exterior&&bad.has(move(p.marker,d))){bad.put(move(p.marker,d),d==0||d==2?"│":"─");return;}r11::need(false,"Requirement11 circle second arm placement");},work,"Requirement11 circle two-arm mutant");
