                r11::require_rejected(frames.wide,scene,[](Grid& bad,const r11::Geometry& proof){const auto& p=proof.arrows.front();bad.put(p.marker,r11::arrow_for_exterior((p.exterior+1)%4));},work,"Requirement11 open-arrow rotation mutant");
