            r11::require_rejected(frames.wide,scene,[](Grid& bad,const r11::Geometry& proof){r11::need(!proof.edges.empty()&&!proof.edges.front().label.cells.empty(),"Requirement11 label witness");bad.put(proof.edges.front().label.cells.front(),"─");},work,"Requirement11 label-route-intersection mutant");
            r11::require_rejected(frames.wide,scene,[&](Grid& bad,const r11::Geometry& proof){for(const auto cell:proof.edges.front().path){const auto point=bad.point(cell);for(int d=0;d<4;++d){const auto next=move(point,d);if(bad.has(next)&&bad.at(next)==" "){bad.put(point,"┼");bad.put(next,d==0||d==2?"│":"─");return;}}}r11::need(false,"Requirement11 route branch placement");},work,"Requirement11 route branch mutant");
            r11::require_rejected(frames.wide,scene,[](Grid& bad,const r11::Geometry& proof){Point at;r11::need(r11::first_blank(bad,proof,at),"Requirement11 control blank for orphan");bad.put(at,"X");},work,"Requirement11 unclaimed ink mutant");
            phase="good_first_lifecycle_mutants";r11::require_lifecycle_rejected(frames,[](r11::Frames& bad){Work local{r11::kSetupLimit};const auto row=loom::test::mermaid_relations::following_row(bad.wide,local,r11::kFollowing);r11::need(row.has_value(),"Requirement11 following mutation row");for(int x=0;x<bad.wide.width;++x)if(bad.wide.at({x,*row})!=" "){bad.wide.put({x,*row}," ");return;}},work,"Requirement11 missing following mutant");r11::require_lifecycle_rejected(frames,[](r11::Frames& bad){bad.restored.put({0,0},bad.restored.at({0,0})=="X"?"Y":"X");},work,"Requirement11 restore differs mutant");
            if(p6){r11::Scene wrong=scene;wrong.direction=scene.direction=="LR"?"RL":scene.direction=="RL"?"LR":scene.direction=="TB"?"BT":"TB";bool rejected=false;try{r11::Geometry ignored;const auto errors=r11::geometry(frames.wide,wrong,work,&ignored);if(errors.empty())r11::directional_rank(frames.wide,wrong,ignored,work);}catch(const std::exception& error){if(class481_resource(error.what()))throw;rejected=true;}r11::need(rejected,"Requirement11 P6 rank swap Model mutant");}
