    const std::array<std::string,10> p5_bad{{std::string(p5).replace(0,3,"----"),std::string(p5).replace(p5.find("---\nrequirementDiagram"),4,""),std::string(p5).replace(p5.find(">-"),2,"|"),std::string(p5).insert(p5.find("---\nrequirementDiagram"),"unknown: yes\n"),std::string(p5).insert(p5.find("---\nrequirementDiagram"),"config: {}\n"),std::string(p5).insert(p5.find("---\nrequirementDiagram"),"title: hidden\n"),std::string(p5).insert(p5.find("---\nrequirementDiagram"),"description: >-\n  duplicate\n"),std::string(p5).replace(p5.find("  Source"),2,"\t"),std::string(p5).replace(p5.find("  Source"),2," "),std::string(p5).insert(3,1,'\r')}};
    int p5_negative_protocol=0;
