TEST(MermaidRequirement11, ZeroAndInsufficientWorkPrepayAsResourceBeforePathOrMarkdownAllocation){
    Work setup{r11::kSetupLimit};setup.spend(8u*sizeof(std::string)+4u*sizeof(Point)+sizeof(Label)+512u);
    const auto route=mock({"────"});const Label clearance{"<<satisfies>>",{1,1,2,1},{}};
    const std::vector<Point> goals{{3,0}};const std::vector<Rect> no_boxes;
    auto resource_only=[](Work& work,auto invoke){bool resource=false;try{invoke();}catch(const std::exception& error){resource=class481_resource(error.what());}EXPECT_TRUE(resource);EXPECT_EQ(work.left,0u);};
    const auto path_fee=r11::owned_path_workspace_fee(route.cells.size());ASSERT_GT(path_fee,0u);
    Work path_zero{0u};resource_only(path_zero,[&]{static_cast<void>(r11::owned_path(route,{0,0},goals,no_boxes,clearance,path_zero));});
    Work path_short{path_fee-1u};resource_only(path_short,[&]{static_cast<void>(r11::owned_path(route,{0,0},goals,no_boxes,clearance,path_short));});
    constexpr std::string_view source="requirementDiagram\n";const auto observe_fee=r11::observe_prepay_fee(source.size());ASSERT_GT(observe_fee,0u);
    Work observe_zero{0u};resource_only(observe_zero,[&]{static_cast<void>(r11::observe(source,observe_zero));});
    Work observe_short{observe_fee-1u};resource_only(observe_short,[&]{static_cast<void>(r11::observe(source,observe_short));});
}

// Test-local physical controls for Requirement11 marker and route-style
// recognition.  The Grids are handwritten and do not derive from a report row
// or a renderer capture; they exercise the existing test-only oracle directly.
struct R11MarkerControl {
    Grid grid;
    Rect box;
    Point border,marker,route;
};

void r11_draw_marker_box(Grid& grid,const Rect& box){
    grid.put({box.l,box.t},"┌");grid.put({box.r,box.t},"┐");
    grid.put({box.l,box.b},"└");grid.put({box.r,box.b},"┘");
    for(int x=box.l+1;x<box.r;++x){grid.put({x,box.t},"─");grid.put({x,box.b},"─");}
    for(int y=box.t+1;y<box.b;++y){grid.put({box.l,y},"│");grid.put({box.r,y},"│");}
}

R11MarkerControl r11_marker_control(int exterior){
    Grid grid{15,15,std::vector<std::string>(225u," ")};
    Rect box{5,5,9,9,"box"};r11_draw_marker_box(grid,box);
    Point border{};
    switch(exterior){
    case 0:border={7,5};break;
    case 1:border={9,7};break;
    case 2:border={7,9};break;
    case 3:border={5,7};break;
    default:throw std::runtime_error("Requirement11 handwritten marker exterior");
    }
    const auto marker=move(border,exterior),route=move(marker,exterior);
    grid.put(marker,r11::arrow_for_exterior(exterior));
    grid.put(route,exterior==0||exterior==2?"│":"─");
    return {std::move(grid),std::move(box),border,marker,route};
}

TEST(MermaidRequirement11, NativeMarkerAndStraightStrokeControlsRejectRotationBranchAndStyleSubstitution){
    for(const int exterior:std::array<int,4>{{0,1,2,3}}){
        const auto control=r11_marker_control(exterior);
        Work good{r11::kSceneLimit};const auto endpoints=r11::endpoints(control.grid,{control.box},false,good);
        ASSERT_EQ(endpoints.size(),1u);EXPECT_EQ(endpoints.front().exterior,exterior);EXPECT_EQ(endpoints.front().border.x,control.border.x);EXPECT_EQ(endpoints.front().border.y,control.border.y);EXPECT_EQ(endpoints.front().marker.x,control.marker.x);EXPECT_EQ(endpoints.front().marker.y,control.marker.y);EXPECT_EQ(endpoints.front().route.x,control.route.x);EXPECT_EQ(endpoints.front().route.y,control.route.y);
        auto rotated=control.grid;rotated.put(control.marker,r11::arrow_for_exterior((exterior+1)%4));
        Work rotated_work{r11::kSceneLimit};EXPECT_TRUE(r11::endpoints(rotated,{control.box},false,rotated_work).empty());
        auto branched=control.grid;const int side=(exterior+1)%4;const auto branch=move(control.marker,side);
        branched.put(branch,side==0||side==2?"│":"─");
        Work branch_work{r11::kSceneLimit};EXPECT_TRUE(r11::endpoints(branched,{control.box},false,branch_work).empty());
    }
    // A disconnected neighbor may carry an outward bit without a reciprocal
    // arm toward the marker. These asymmetric corners distinguish the two.
    for(const bool circle:std::array<bool,2>{{false,true}}){
        auto control=r11_marker_control(0);
        if(circle)control.grid.put(control.marker,"⊕");
        const auto neighbor=move(control.marker,1);control.grid.put(neighbor,"└");
        Work disconnected_work{r11::kSceneLimit};const auto found=r11::endpoints(control.grid,{control.box},circle,disconnected_work);
        ASSERT_EQ(found.size(),1u);EXPECT_EQ(found.front().exterior,0);
        control.grid.put(neighbor,"┘");
        Work reciprocal_work{r11::kSceneLimit};EXPECT_TRUE(r11::endpoints(control.grid,{control.box},circle,reciprocal_work).empty());
    }
    const auto dotted_vertical=mock({"┆","┆","┆"});
    const std::vector<int> vertical_path{{dotted_vertical.index({0,0}),dotted_vertical.index({0,1}),dotted_vertical.index({0,2})}};
    Work vertical_good{r11::kSceneLimit};EXPECT_TRUE(r11::expected_straight_stroke(dotted_vertical,vertical_path,1,vertical_good));
    Work vertical_wrong{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(dotted_vertical,vertical_path,0,vertical_wrong));
    auto solid_vertical=dotted_vertical;for(int y=0;y<3;++y)solid_vertical.put({0,y},"│");
    Work vertical_solid_good{r11::kSceneLimit};EXPECT_TRUE(r11::expected_straight_stroke(solid_vertical,vertical_path,0,vertical_solid_good));
    Work vertical_solid_wrong{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(solid_vertical,vertical_path,1,vertical_solid_wrong));
    const auto dotted_turn=mock({"┄┄┐","  ┆"});
    const std::vector<int> turn_path{{dotted_turn.index({0,0}),dotted_turn.index({1,0}),dotted_turn.index({2,0}),dotted_turn.index({2,1})}};
    Work dotted_work{r11::kSceneLimit};EXPECT_TRUE(r11::expected_straight_stroke(dotted_turn,turn_path,1,dotted_work));
    Work dotted_as_solid{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(dotted_turn,turn_path,0,dotted_as_solid));
    auto solid_turn=dotted_turn;solid_turn.put({0,0},"─");solid_turn.put({1,0},"─");solid_turn.put({2,1},"│");
    Work solid_work{r11::kSceneLimit};EXPECT_TRUE(r11::expected_straight_stroke(solid_turn,turn_path,0,solid_work));
    Work replacement_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(solid_turn,turn_path,1,replacement_work));
    // The first and final visible straight cells must also retain the
    // declared stroke; they are not omitted from physical consistency.
    for(const int y:std::array<int,2>{{0,2}}){
        auto wrong_dotted=dotted_vertical;wrong_dotted.put({0,y},"│");
        Work wrong_dotted_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(wrong_dotted,vertical_path,1,wrong_dotted_work));
        auto wrong_solid=solid_vertical;wrong_solid.put({0,y},"┆");
        Work wrong_solid_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(wrong_solid,vertical_path,0,wrong_solid_work));
    }
    for(const Point point:std::array<Point,2>{{{0,0},{2,1}}}){
        auto wrong_dotted=dotted_turn;wrong_dotted.put(point,point.y?"│":"─");
        Work wrong_dotted_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(wrong_dotted,turn_path,1,wrong_dotted_work));
        auto wrong_solid=solid_turn;wrong_solid.put(point,point.y?"┆":"┄");
        Work wrong_solid_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(wrong_solid,turn_path,0,wrong_solid_work));
    }
    const auto light_junction=mock({"┄┼┄"});
    const std::vector<int> straight_path{{light_junction.index({0,0}),light_junction.index({1,0}),light_junction.index({2,0})}};
    Work junction_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(light_junction,straight_path,1,junction_work));
    const auto elbow_only=mock({"┐","│"});
    const std::vector<int> elbow_path{{elbow_only.index({0,0}),elbow_only.index({0,1})}};
    Work elbow_work{r11::kSceneLimit};EXPECT_FALSE(r11::expected_straight_stroke(elbow_only,elbow_path,0,elbow_work));
}

TEST(MermaidRequirement11, MultipleIncomingMarkersBindEachCompletePathLabelAndSourceBeforeConsumption){
    constexpr std::string_view source="requirementDiagram\ndirection TB\nrequirement R {}\nelement A {}\nelement B {}\nA - traces -> R\nB - copies -> R\n";
    Work work{r11::kSceneLimit};json::JsonMutDoc report;auto output=report.object(),record=output.make_obj();
    bool complete=false;std::string_view phase="five_captures_before_binding";
    try{
        const auto frames=r11::observe(source,work);r11::publish(frames,output,record,work);
        phase="complete_source_binding";r11::need(digest(source)=="2934fc3aea3e8d8dc45f4e63b4d439fbcd590c5a10b8473db6fdce19d07f4f29","Requirement11 full incoming literal SHA");r11::lifecycle(frames,work);
        phase="complete_Model_after_capture_and_binding";r11::Scene scene{0,{},{},"TB",{r11_req("R"),r11_element("A"),r11_element("B")},{r11_edge(r11::Role::Element,"A",r11::EdgeKind::Traces,r11::Role::Requirement,"R",0),r11_edge(r11::Role::Element,"B",r11::EdgeKind::Copies,r11::Role::Requirement,"R",1)}};
        r11::semantic_well_formed(scene,work);r11::need(frames.wide!=frames.source240,"Requirement11 incoming control mandatory drawing");
        phase="complete_geometry";r11::Geometry evidence;const auto errors=r11::geometry(frames.wide,scene,work,&evidence);r11::need(errors.empty(),errors.empty()?"":errors.front());
        r11::need(evidence.edges.size()==2u&&evidence.arrows.size()==2u,"Requirement11 two distinct incoming witnesses");
        r11::need(r11::geometry(frames.restored,scene,work).empty(),"Requirement11 incoming restored geometry");
        if(frames.narrow!=frames.source40)r11::need(r11::geometry(frames.narrow,scene,work).empty(),"Requirement11 incoming narrow geometry");
        phase="good_first_mutations";
        r11::require_model_rejected(frames.wide,scene,[](r11::Scene& bad){bad.edges.front().source=bad.nodes.back().ref;},work,"Requirement11 incoming source ownership");
        r11::require_model_rejected(frames.wide,scene,[](r11::Scene& bad){bad.edges.pop_back();},work,"Requirement11 missing incoming edge");
        r11::require_model_rejected(frames.wide,scene,[](r11::Scene& bad){bad.edges[1]=bad.edges[0];bad.edges[1].order=1;},work,"Requirement11 no marker/path reuse");
        r11::require_rejected(frames.wide,scene,[&](Grid& bad,const r11::Geometry& good){
            const auto& a=good.edges[0].label.cells;const auto& b=good.edges[1].label.cells;r11::need(a.size()==b.size()&&!a.empty(),"Requirement11 equal-length incoming caption swap");
            for(std::size_t n=0;n<a.size();++n){work.spend(2u*sizeof(std::string)+16u);bad.put(a[n],std::string(frames.wide.at(b[n])));bad.put(b[n],std::string(frames.wide.at(a[n])));}
        },work,"Requirement11 physical incoming caption exchange");
        r11::require_rejected(frames.wide,scene,[](Grid& bad,const r11::Geometry& good){bad.put(good.edges.front().label.cells.front(),"X");},work,"Requirement11 missing incoming caption");
        complete=true;record.set("outcome","complete_geometry_and_good_first_mutations");
    }catch(const std::exception& error){record.set("outcome",class481_resource(error.what())?"resource_error":"verification_error");record.set("error",error.what());ADD_FAILURE()<<phase<<": "<<error.what();}
    record.set("source_sha256","2934fc3aea3e8d8dc45f4e63b4d439fbcd590c5a10b8473db6fdce19d07f4f29");record.set("phase",phase);record.set("complete",complete);record.set("work_remaining",static_cast<std::int64_t>(work.left));output.set("qualification","One complete synthetic three-node/two-edge source. Five PixelAt views published before full source binding and independent complete Model. No original/foreign admission.");output.add("scene",record);report.set_root(output);state85_write("mermaid-requirement11-multiple-incoming-native.json",report);EXPECT_TRUE(complete);
}


TEST(MermaidRequirement11, LabelClearanceOwnershipRequiresAnActualReciprocalRouteArm){
    // The full-source failure has a DL corner immediately below another
    // relation's padding. Spatial adjacency alone cannot own that label.
    const auto grid_with=[](std::string_view ink){
        auto grid=mock({"                  ","   <<traces>>      ","                  ","                  ","                  "});
        grid.put({7,3},std::string(ink));return grid;
    };
    const Label label{"<<traces>>",{2,0,13,2,"label"},{}};
    for(const auto ink:{std::string_view("┐"),std::string_view("┌"),std::string_view("─"),std::string_view("┄"),std::string_view("X")}){
        const auto grid=grid_with(ink);const std::vector<int> path{grid.index({7,3})};
        EXPECT_FALSE(r11::path_touches_label(grid,path,label));EXPECT_FALSE(r11::point_touches_label(grid,{7,3},label));
    }
    for(const auto ink:{std::string_view("│"),std::string_view("┆"),std::string_view("┘"),std::string_view("└")}){
        const auto grid=grid_with(ink);const std::vector<int> path{grid.index({7,3})};
        EXPECT_TRUE(r11::path_touches_label(grid,path,label));EXPECT_TRUE(r11::point_touches_label(grid,{7,3},label));
    }
}


// Source-derived SCC columns are independent of producer layout and routing.
void r11_peer_columns(const r11::Scene& scene,const r11::Geometry& evidence,Work& work,bool wrong_peer_column=false){
    work.spend(4096u);r11::need(scene.nodes.size()==9u&&evidence.boxes.size()==9u,"Requirement11 full peer geometry");
    const std::array<std::array<int,5>,3> members{{{{6,7,8,-1,-1}},{{0,1,3,4,5}},{{2,-1,-1,-1,-1}}}};
    std::array<int,3> left{},right{},center{};
    for(std::size_t col=0;col<members.size();++col){
        bool first=true;
        for(int member:members[col]){if(member<0)continue;if(wrong_peer_column&&member==7)member=2;
            const auto& box=evidence.boxes[static_cast<std::size_t>(member)];
            if(first){left[col]=box.l;right[col]=box.r;center[col]=box.l+box.r;first=false;}
            else{r11::need(std::abs(box.l+box.r-center[col])<=1,"Requirement11 source peers share physical column center");left[col]=std::min(left[col],box.l);right[col]=std::max(right[col],box.r);}
        }
        for(std::size_t a=0;a<members[col].size();++a)for(std::size_t b=a+1;b<members[col].size();++b){
            const int first_member=members[col][a],second_member=members[col][b];if(first_member<0||second_member<0)continue;
            const auto& first=evidence.boxes[static_cast<std::size_t>(first_member)];const auto& second=evidence.boxes[static_cast<std::size_t>(second_member)];
            r11::need(first.b<second.t||second.b<first.t,"Requirement11 whole same-column peers do not overlap");
        }
    }
    for(std::size_t col=1;col<3u;++col){
        if(scene.direction=="LR")r11::need(right[col-1]<left[col],"Requirement11 complete LR SCC column ordering");
        else if(scene.direction=="RL")r11::need(left[col-1]>right[col],"Requirement11 complete RL SCC column ordering");
        else r11::need(false,"Requirement11 peer control direction domain");
    }
}
TEST(MermaidCapabilityReport, Requirement11Overflow) {
    Work setup{r11::kSetupLimit};const auto raw_models=r11::load(r11_root()/"requirement11_overflow_peers.models.json",setup);
    // RFC 0031 E6c: the single LR source-fallback verification error is a
    // reviewed gap matched on index, outcome and error prefix; any other
    // throw or a resource failure stays a hard ADD_FAILURE.
    struct OverflowGap { std::int64_t index; std::string outcome; std::string error_prefix; };
    std::vector<OverflowGap> mandatory_gaps;
    r11::need(digest(raw_models)=="ce2b6edc674cc524b49cc9e79909fe3ca084bcd9e2d67e5dd7db0fbb45fd2560","Requirement11 complete source-derived peer Models asset SHA");
    const auto model_document=json::parse(raw_models);r11::need(model_document.has_value(),"Requirement11 peer Models parse");
    const auto models=model_document->root().get("models");r11::need(models.is_arr()&&models.size()==2u,"Requirement11 two complete peer Models");
    const std::array<std::string_view,2> sources{{"requirementDiagram\ndirection LR\nrequirement R {\n  id: R-1\n  text: owner requirement\n  risk: high\n  verifymethod: test\n}\nfunctionalRequirement F {\n  id: F-1\n  text: child requirement\n  risk: low\n  verifymethod: inspection\n}\ninterfaceRequirement I {\n  id: I-1\n  text: endpoint requirement\n  risk: medium\n  verifymethod: analysis\n}\nperformanceRequirement P {\n  id: P-1\n  text: performance requirement\n  risk: medium\n  verifymethod: demonstration\n}\nphysicalRequirement H {\n  id: H-1\n  text: physical requirement\n  risk: low\n  verifymethod: test\n}\ndesignConstraint D {\n  id: D-1\n  text: constraint requirement\n  risk: high\n  verifymethod: inspection\n}\nelement E {\n  type: test system\n  docref: docs/e\n}\nR - contains -> F\nF - contains -> I\nE - copies -> R\nR - traces -> F\nR - traces -> F\nF - derives -> P\nP - satisfies -> H\nH - verifies -> D\nD - refines -> R\nI <- copies - E\nrequirement PeerX {}\nrequirement PeerY {}\n","requirementDiagram\ndirection RL\nrequirement R {\n  id: R-1\n  text: owner requirement\n  risk: high\n  verifymethod: test\n}\nfunctionalRequirement F {\n  id: F-1\n  text: child requirement\n  risk: low\n  verifymethod: inspection\n}\ninterfaceRequirement I {\n  id: I-1\n  text: endpoint requirement\n  risk: medium\n  verifymethod: analysis\n}\nperformanceRequirement P {\n  id: P-1\n  text: performance requirement\n  risk: medium\n  verifymethod: demonstration\n}\nphysicalRequirement H {\n  id: H-1\n  text: physical requirement\n  risk: low\n  verifymethod: test\n}\ndesignConstraint D {\n  id: D-1\n  text: constraint requirement\n  risk: high\n  verifymethod: inspection\n}\nelement E {\n  type: test system\n  docref: docs/e\n}\nR - contains -> F\nF - contains -> I\nE - copies -> R\nR - traces -> F\nR - traces -> F\nF - derives -> P\nP - satisfies -> H\nH - verifies -> D\nD - refines -> R\nI <- copies - E\nrequirement PeerX {}\nrequirement PeerY {}\n"}};
    const std::array<std::string_view,2> pins{{"e434b33109d9edcc809b342b2c71ce502edbab6393f571da448db93d6d98b6fa","da1541384f6b4cd6d52719dd80a7ad89307e7a9dd289d58b357775c12358624c"}};
    json::JsonMutDoc report;auto output=report.object(),records=output.make_arr();int complete=0,fallbacks=0,resources=0,errors=0;
    for(std::size_t index=0;index<sources.size();++index){Work work{r11::kSceneLimit};auto record=output.make_obj();std::string_view phase="five_actual_captures_before_binding";
        try{
            const auto source=sources[index];const auto frames=r11::observe(source,work);r11::publish(frames,output,record,work);
            phase="full_source_binding";r11::need(source.size()==911u&&digest(source)==pins[index],"Requirement11 full SCC plus peer literal binding");r11::lifecycle(frames,work);
            phase="full_independent_Model_after_capture";const auto scene=r11::decode_scene(models.at(index),work);r11::need(scene.source_sha==pins[index]&&scene.direction==(index?"RL":"LR"),"Requirement11 full peer Model/source binding");
            r11::need(scene.nodes.size()==9u&&scene.edges.size()==10u,"Requirement11 complete peer Model denominator");
            phase="mandatory_full_geometry";if(frames.wide==frames.source240){++fallbacks;throw std::runtime_error("Requirement11 whole overflow peer source fallback");}
            r11::Geometry evidence;const auto good=r11::geometry(frames.wide,scene,work,&evidence);r11::need(good.empty(),good.empty()?"":good.front());r11_peer_columns(scene,evidence,work);
            r11::need(r11::geometry(frames.restored,scene,work).empty(),"Requirement11 peer restored geometry");
            if(frames.narrow!=frames.source40)r11::need(r11::geometry(frames.narrow,scene,work).empty(),"Requirement11 peer narrow geometry");
            phase="good_first_column_and_physical_mutations";
            bool rejected=false;try{r11_peer_columns(scene,evidence,work,true);}catch(const std::exception& error){if(class481_resource(error.what()))throw;rejected=true;}r11::need(rejected,"Requirement11 wrong peer-column obligation rejected");
            work.spend(65536u);auto wrong_direction=scene;wrong_direction.direction=index?"LR":"RL";rejected=false;try{r11_peer_columns(wrong_direction,evidence,work);}catch(const std::exception& error){if(class481_resource(error.what()))throw;rejected=true;}r11::need(rejected,"Requirement11 wrong complete direction rejected");
            // Isolate the non-overlap contract on the discovered actual
            // boxes, after the same unchanged whole Grid passed geometry.
            work.spend(evidence.boxes.size()*(2u*sizeof(Rect)+4u*sizeof(std::string))+4096u);
            r11::Geometry overlapping;overlapping.boxes=evidence.boxes;overlapping.boxes[7]=overlapping.boxes[8];rejected=false;
            try{r11_peer_columns(scene,overlapping,work);}catch(const std::exception& error){if(class481_resource(error.what()))throw;r11::need(std::string_view(error.what())=="Requirement11 whole same-column peers do not overlap","Requirement11 isolated overlap rejection reason");rejected=true;}
            r11::need(rejected,"Requirement11 overlapping discovered peer boxes rejected");
            r11::require_model_rejected(frames.wide,scene,[](r11::Scene& bad){bad.nodes.pop_back();},work,"Requirement11 omitted incomparable peer rejected");
            r11::require_rejected(frames.wide,scene,[&](Grid& bad,const r11::Geometry& original){
                const auto& source_box=original.boxes[7];const auto& target_box=original.boxes[8];r11::need(source_box.r-source_box.l==target_box.r-target_box.l&&source_box.b-source_box.t==target_box.b-target_box.t,"Requirement11 equal whole peer frames for physical overlap");
                for(int y=source_box.t;y<=source_box.b;++y)for(int x=source_box.l;x<=source_box.r;++x){work.spend(2u*sizeof(std::string)+32u);bad.put({x-source_box.l+target_box.l,y-source_box.t+target_box.t},std::string(frames.wide.at({x,y})));bad.put({x,y}," ");}
            },work,"Requirement11 physically overlapping peer replacement rejected");
            ++complete;record.set("outcome","complete_full_geometry_columns_and_good_first_mutants");
        }catch(const std::exception& error){const std::string message=error.what();if(class481_resource(message)){++resources;record.set("outcome","resource_error");}else{++errors;record.set("outcome","verification_error");}record.set("error",message);
            const bool rostered_gap=index==0&&!class481_resource(message)&&message=="Requirement11 whole overflow peer source fallback";
            if(rostered_gap)mandatory_gaps.push_back({0,"verification_error",message});else ADD_FAILURE()<<phase<<": "<<message;}
        record.set("direction",index?"RL":"LR");record.set("source_sha256",pins[index]);record.set("phase",phase);record.set("work_remaining",static_cast<std::int64_t>(work.left));records.append(record);
    }
    output.set("qualification","Two complete synthetic 911-byte sources and independent nine-node/ten-edge Models. All original P1 fields retained. Five actual PixelAt captures precede source binding and Model construction. No original/foreign admission.");output.set("sources",2);output.set("complete",complete);output.set("mandatory_fallbacks",fallbacks);output.set("resource_errors",resources);output.set("errors",errors);auto overflow_gaps=output.make_arr();for(const auto& gap:mandatory_gaps){auto gap_row=output.make_obj();gap_row.set("index",gap.index);gap_row.set("outcome",gap.outcome);gap_row.set("error_prefix",gap.error_prefix);overflow_gaps.append(gap_row);}output.add("mandatory_gaps",overflow_gaps);output.add("cases",records);report.set_root(output);state85_write("mermaid-requirement11-overflow-peers-native.json",report);EXPECT_EQ(complete,1);EXPECT_EQ(fallbacks,1);EXPECT_EQ(resources,0);EXPECT_EQ(errors,1);EXPECT_EQ(static_cast<int>(mandatory_gaps.size()),1);
    if(auto roster=gap_roster::load_verified_roster()){auto published=json::parse(report.to_string());ASSERT_TRUE(published.has_value());const auto gap_diff=gap_roster::diff_gate(*roster,"requirement11_overflow",published->root().get("mandatory_gaps"));EXPECT_TRUE(gap_diff.ok())<<gap_diff.render("requirement11_overflow");}
}


// RFC 0031 E2a: config-free stateDiagram-v2 frontmatter admission.
namespace e2a_state {
std::string surface(const std::string& source, const char* language) {
    auto element = loom::ui::render_markdown(fenced(source, language));
    auto grid = capture(element, 240, 60);
    std::string joined;
    for (const auto& cell : grid.cells) joined += cell;
    return joined;
}
bool draws(const std::string& source) {
    const auto native = surface(source, "mermaid");
    const auto control = surface(source, "text");
    return native != control &&
           native.find("stateDiagram") == std::string::npos &&
           native.find("description") == std::string::npos;
}
} // namespace e2a_state

TEST(MermaidStateEnvelope, V2DescriptionOnlyDraws) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  SecretStateDescriptionToken\n"
        "---\n"
        "stateDiagram-v2\n"
        "  [*] --> State1\n"
        "  State1 --> [*]\n";
    EXPECT_TRUE(e2a_state::draws(source));
    EXPECT_EQ(e2a_state::surface(source, "mermaid").find("SecretStateDescriptionToken"),
              std::string::npos);
}

TEST(MermaidStateEnvelope, TitleProjectsAboveDiagram) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  d\n"
        "title: ProjectedStateTitle\n"
        "---\n"
        "stateDiagram-v2\n"
        "  [*] --> State1\n";
    const auto native = e2a_state::surface(source, "mermaid");
    EXPECT_NE(native.find("ProjectedStateTitle"), std::string::npos);
    EXPECT_NE(native.find("State1"), std::string::npos);
}

TEST(MermaidStateEnvelope, ConfigFrontmatterStaysSource) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  d\n"
        "config:\n"
        "  theme: dark\n"
        "---\n"
        "stateDiagram-v2\n"
        "  [*] --> State1\n";
    EXPECT_FALSE(e2a_state::draws(source));
}

TEST(MermaidStateEnvelope, InitThemeFrontmatterStaysSource) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  d\n"
        "---\n"
        "%%{init: {\"theme\": \"dark\"}}%%\n"
        "stateDiagram-v2\n"
        "  [*] --> State1\n";
    EXPECT_FALSE(e2a_state::draws(source));
}

TEST(MermaidStateEnvelope, CompositeBraceOnNextLineStaysSource) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  d\n"
        "---\n"
        "stateDiagram-v2\n"
        "  state X\n"
        "  {\n"
        "    a\n"
        "  }\n"
        "  [*] --> X\n";
    EXPECT_FALSE(e2a_state::draws(source));
}

TEST(MermaidStateEnvelope, CompositeDividerStaysSource) {
    const std::string source =
        "---\n"
        "description: >-\n"
        "  d\n"
        "---\n"
        "stateDiagram-v2\n"
        "  state s2 {\n"
        "  s3\n"
        "  --\n"
        "  s4\n"
        "  }\n";
    EXPECT_FALSE(e2a_state::draws(source));
}

